INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252874827', 'Eucatex Verniz Marítimo Natural Premium Acetinado Eucatex 900ml', 'O Verniz Marítimo Natural Premium da Eucatex é a escolha ideal para quem busca proteção e beleza em ambientes internos e externos. Com um acabamento brilhante, este produto realça a beleza da madeira, proporcionando um aspecto sofisticado e duradouro.Com um tempo de secagem de apenas 4 horas, você pode aplicar e desfrutar rapidamente dos resultados. O rendimento de 4 m2 por unidade garante que você tenha o suficiente para cobrir suas necessidades, tornando-o uma opção prática e eficiente.Desenvolvido para resistir às condições mais desafiadoras, o Verniz Marítimo é perfeito para áreas expostas à umidade e ao sol. A qualidade Eucatex assegura que sua madeira fique protegida e com um visual impecável por muito mais tempo.', 79.9, 79.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj8wmlq9p4hyc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1027399414%2F58252874827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897868754', 'Anjos cruéis - Darkside Books - Crime Scene', 'Impactante e real, maligno e surpreendente. A refer&ecirc ncia para o estudo de crian&ccedil as psicopatas. &Nbsp Rostinhos angelicais podem encantar e esconder muitas inten&ccedil &otilde es. Por tr&aacute s da do&ccedil ura aparente e da inoc&ecirc ncia infantil, reside um mist&eacute rio obscuro que desafia as concep&ccedil &otilde es tradicionais sobre a natureza humana. &Eacute nesse territ&oacute rio sombrio onde traumas, desejos, raivas, frustra&ccedil &otilde es, aus&ecirc ncias e descobertas podem emoldurar atos de profunda viol&ecirc ncia praticados por pequenas criaturas aparentemente indefesas. Um mergulho em mentes ainda em forma&ccedil &atilde o, mas j&aacute machucadas pela falta de amparo psicol&oacute gico. Casos estarrecedores s&atilde o documentados e estudados por todo o mundo, uma infinidade de profissionais busca encontrar respostas para comportamentos t&atilde o brutais e, por vezes, inesperados. Os anjos cru&eacute is existem, eles vivem entre n&oacute s e podem ser filhos das cicatrizes mais profundas de nossa sociedade. &Nbsp Agora, a DarkSide&reg Books convida voc&ecirc a desvendar os segredos por tr&aacute s destas fei&ccedil &otilde es, lan&ccedil ando luz sobre um aspecto muitas vezes negligenciado da psicologia humana. Anjos Cru&eacute is, um projeto original Crime Scene&reg criado pela DarkSide&reg Books em parceria com Daniel Cruz, o renomado autor do site OAV, nos leva a uma jornada envolvente pelo labirinto da psicopatia infantil, onde a inoc&ecirc ncia e a crueldade se entrela&ccedil am de maneiras inesperadas. &Nbsp Anjos Cru&eacute is &eacute um documento poderoso onde fatos, pesquisas e relatos&nbsp se juntam para transformar a obra em uma ferramenta de di&aacute logo e enfrentamento de tabus que cercam o assunto. Um livro destinado a se tornar refer&ecirc ncia para todos que desejam estudar, conhecer e explorar as contradi&ccedil &otilde es e a complexidade da mente humana ainda nos seus primeiros passos. Anjos Cru&eacute is conta com mais de vinte estudos de caso de crian&ccedil as psicopatas como Mary Bell, Jesse Pomeroy e Shinichiro Azuma, an&aacute lises hist&oacute ricas e sociais que lan&ccedil am luz sobre as complexidades subjacentes desse fen&ocirc meno intrigante e uma galeria com mais de trinta casos cru&eacute is esquecidos no tempo, al&eacute m de uma lista de filmes cuidadosamente selecionados para oferecer uma perspectiva cinematogr&aacute fica &uacute nica sobre o tema, e introdu&ccedil &atilde o especial da escritora Barbara Bradley Hagerty. &Nbsp Um livro que nasceu com muita dedica&ccedil &atilde o e pesquisa, Anjos Cru&eacute is s&oacute poderia chegar aos leitores brasileiros pela marca Crime Scene&reg , dedicada ao estudo profundo e cient&iacute fico de crimes reais. H&aacute mais de dez anos pavimentando o mercado true crime no Brasil ao lado de pesquisadores, investigadores, psiquiatras, m&eacute dicos-legistas e promotores, a Crime Scene&reg &eacute respons&aacute vel pelo lan&ccedil amento dos livros mais importantes do g&ecirc nero como Lady Killers: Assassinas em S&eacute rie, Serial Killers: Anatomia do Mal, Arquivos Serial Killers: Louco ou Cruel &amp Made in Brazil, Cruel: &Iacute ndice da Maldade, entre muitos outros. Anjos Cru&eacute is ilumina um dos aspectos mais sombrios da psicologia humana e nos fornece uma nova perspectiva do que se esconde por tr&aacute s daqueles rostinhos angelicais.', 98.18, 98.18, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-m0eq7us5h9s9f4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F21897868754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
