INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797750999', 'Luna Clara & Apolo Onze - Salamandra', 'Desencontros levam os pais de Luna Clara - Doravante e Aventura - a se perder e a se encontrar. O avô da menina, Erudito, perde as histórias que havia colecionado e também o papagaio. As tias perdem os namorados. Em um constante ir e vir, na região de Desatino do Norte, as vidas de Luna Clara e Apolo Onze acabam se cruzando.', 102.52, 102.52, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdxv-lxe2rkjdne73ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20797750999', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
