INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193804616', 'Calha de Chuva Toyota Corolla Sedan 2008 a 2014 TG Poli Defletor 4 portas Protetor Janelas Fumê', 'Calha de Chuva Toyota Corolla Sedan 2008 a 2014 4 Portas TG Poli Defletor Portas Protetor Janelas Fumê Descrição do Produto: Proteja o interior do seu veículo contra chuva, vento e sol com este kit de calha de chuva defletor de alta qualidade da marca TG Poli. Este acessório automotivo essencial permite deixar os vidros semiabertos em dias de chuva, garantindo conforto, circulação de ar e segurança, evitando o embaçamento dos vidros. Compatibilidade: Modelo: Toyota Corolla Sedan (4 Portas) Anos: 2008, 2009, 2010, 2011, 2012, 2013 e 2014 Modelo Disponível: Código TG Poli 27.004 Especificações Técnicas: Cor Fumê Instalação rápida sem furos no veículo Peça auto adesiva de encaixe perfeito Fabricado 100% em Acrílico automotivo resistente Fixação com Fita Dupla Face de alta aderência Protege contra Chuva, Sol e Vento Garante Conforto, Segurança e Proteção interna Design exclusivo para cada carro e modelo Possui aditivos que protegem o acrílico dos raios UV Reduz o ruído do vento na janela em velocidade Permite que abra as janelas em dias chuvosos evitando o embaçamento dos vidros Peso: 1,410 Kg Largura: 26,0cm Comprimento: 117,0cm Altura: 4,2cm Conteúdo da Embalagem: 04 Calhas de Chuva (portas dianteiras e traseiras) 01 Manual de instalação ilustrado 01 Tubo de Primer para limpeza e aderência Importante: Garantia de 5 anos pelo fabricante As imagens são meramente ilustrativas e fornecidas pelo fabricante Recomendamos que a instalação seja realizada por um profissional especializado e não nos responsabilizamos pelo mau uso do produto. Atenção: As compras realizadas em nome de Pessoa Jurídica estão sujeitas à cobrança de ICMS ST, conforme Protocolo ICMS 41, de 4 de Abril de 2008. Caso você tenha dúvidas sobre o percentual a ser aplicado, consulte a Cláusula Segunda, §1° do referido Protocolo.', 191.0, 191.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Deflectors', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqmf69wkp3wh10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F718208305%2F23193804616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
