INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44030795346', 'Whey Protein Joypro Refil 900g Cookie De Banana Com Canela - Shark', '------------------------------------------------------------ WHEY PROTEIN JOYPRO REFIL 900G ------------------------------------------------------------ Com 20g de proteína por dose, vitaminas e minerais essenciais, JoyPro é o suplemento ideal para quem busca desempenho, recuperação e bem-estar com prazer. Leve, zero glúten e sem adição de açúcares, ele oferece suporte nutricional completo em sabores irresistíveis: Iogurte de Morango com Framboesa, Brigadeiro, Paçoca e Cookies de Banana com Canela. ------------------------- INGREDIENTES ------------------------- Proteína concentrada do soro de leite, peptídeos de colágeno hidrolisado, cookies de biscoito zero adição de açúcar, mix de vitaminas e minerais (acetato de retinol, mononitrato de tiamina, riboflavina, niacinamida, pantotenato de cálcio, cloridrato de piridoxina, ácido ascórbico, acetato de tocoferol, D-biotina, carbonato de cálcio, bisglicinato de ferro, picolinato de cromo, iodeto de potássio), aroma idêntico ao natural de cookies de banana, canela em pó, goma xantana e edulcorantes (aspartame, ciclamato de sódio, acessulfame de potássio, sacarina sódica).', 129.9, 109.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820m0-mossm09ccxdx24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389266749%2F44030795346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
