INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298727833', 'Cooler para Notebook Sony Vaio SVF15213CBW', 'Cooler compatível com Sony Vaio SVF15213CBW Interno Este é um Cooler bringIT compatível com o notebook Sony Vaio SVF15213CBW. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Sony Vaio. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.28A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL158-SV-0005', 49.29, 44.36, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mqt7wjtymb5v10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22298727833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
