INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25421341181', 'JUMISO Peptide Snail Cream 100ml', 'JUMISO Peptide Snail Cream 100ml POWERFUL SKIN REPAIR FORMULA: Korean face cream with 88% Snail Secretion Filtrate provides intensive healing for damaged skin barrier while delivering exceptional moisture to keep your skin plump, healthy, and revitalized ADVANCED 5-PEPTIDE COMPLEX: Features Copper Tripeptide-1, Palmitoyl Pentapeptide-4, Acetyl Hexapeptide-8, Palmitoyl Tripeptide-1, and Palmitoyl Tetrapeptide-7 to facilitate collagen production and restore bounce HYDRATION AND ELASTICITY BOOST: Enhanced with Sodium Hyaluronate and Niacinamide to boost deep hydration, improve skin elasticity, and control excessive oil production while maintaining optimal moisture balance HYDRATION AND ELASTICITY BOOST: Enhanced with Sodium Hyaluronate and Niacinamide to boost deep hydration, improve skin elasticity, and control excessive oil production while maintaining optimal moisture balance LIGHTWEIGHT GEL TEXTURE: Non-comedogenic tested formula absorbs swiftly without sticky residue. Safe for sensitive skin with completed irritation testing. Apply at final skincare step and gently pat for absorption', 114.02, 109.0, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134207-7rce8-lteufc1s1rqtf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F25421341181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
