INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18830132501', 'Chave Combinada Fixa 18x19mm Tramontina', 'Chave Fixa 18x19mm Tramontina é uma ferramenta essencial para qualquer kit, oferecendo precisão e eficiência. Com um acabamento cromado, garante resistência à corrosão, tornando-a ideal para uso prolongado. Fabricada em aço especial forjado, proporciona alta durabilidade e desempenho superior. Seu design leve facilita o manuseio em diversas aplicações, desde a mecânica até a montagem de móveis. A Tramontina, renomada por sua qualidade, oferece uma chave que se adapta tanto ao uso profissional quanto doméstico. Vantagens: Aço especial forjado e temperado: Proporciona alta resistência e durabilidade. Acabamento cromado: Protege contra corrosão e desgaste. Bocas calibradas: Garantem encaixe preciso em parafusos e porcas. Leveza e praticidade: Facilita o manuseio em diversas tarefas. Uso versátil: Adequada para profissionais e tarefas domésticas. Manutenção simples: Fácil de limpar e armazenar. Especificações técnicas: Marca: Tramontina Material: Aço especial forjado e temperado Acabamento: Cromado Tamanho da Abertura: 18mm e 19mm Cor: Cromado Peso: Leve Resistência: Alta durabilidade Conteúdo da embalagem: Uma chave fixa com abertura de 18mm e 19mm Garantia: Garantia de 12 meses contra defeitos de fabricação pelo fabricante.', 46.9, 32.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3z5kao8e1fl32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F18830132501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
