INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098834311', 'Dispenser Porta Detergente Dosador 650ml Com Suporte p/ Esponja Ou Trium', 'Dispenser para Detergente e Organizador de Pia OU 650ml – Linha Trium | Organização Inteligente com Design Sofisticado O Dispenser para Detergente com Organizador de Pia da marca OU, da Linha Trium, foi desenvolvido para facilitar a rotina da cozinha com elegância e eficiência. Com design moderno e acabamento clean, ele integra dispenser e compartimento organizador em uma única peça funcional, mantendo a pia sempre limpa e organizada. Com capacidade de 650ml, o reservatório permite armazenar uma boa quantidade de detergente, evitando recargas frequentes. Seu sistema de acionamento com bomba dosadora proporciona uso econômico e prático, liberando a quantidade ideal de produto a cada pressão. O compartimento lateral acomoda esponjas, escovas ou panos de pia, mantendo tudo à mão sem comprometer o espaço. Fabricado em plástico de alta qualidade (PP e PET), é resistente à umidade, fácil de desmontar e limpar, ideal para uso frequente. Destaques do produto: Capacidade do dispenser: 650ml Reservatório translúcido: facilita a visualização do nível de detergente Bomba dosadora eficiente: acionamento suave, com saída controlada Organizador lateral: espaço para esponjas, escovas ou panos Base firme e antiderrapante, que evita tombamentos e deslizamentos Design moderno e compacto, ideal para pias pequenas ou grandes Material resistente: em polipropileno (PP) e PET, fácil de limpar Medidas: A 18cm x L 9cm x C 16cm Marca OU: referência em organização doméstica e qualidade Cuidados e recomendações: Produto não compatível com micro-ondas Pode ser higienizado com água e sabão neutro Evitar uso de esponjas abrasivas para preservar o acabamento', 49.9, 29.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-mdd9fbxe2a807c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349137150%2F22098834311', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
