INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397457682', 'Tensor Correia Alternador SCENIC 1999/2011 - 48837 - T507868', 'Tensor Correia Alternador SCENIC 1999/2011 1.6 16v / 2.0 8/16v - (Com Ar Condicionado) (Com Direção Hidráulica) Tensor correia alternador: Aplica-se na parte de fora do motor. Sua função é aplicar carga/pressão constante na correia, com a finalidade de evitar que a mesma se solte do sistema de polias, compensar eventuais folgas ou tensões excessivas que possam prejudicar o sincronismo do motor e o funcionamento dos acessórios do veículo.', 168.4, 168.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmh-lnd7tga5h50s2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20397457682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
