INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199496370', 'Calculadora de Mesa Deli 12 Dígitos Duplo Display Função Check Grande Visor Preta', 'A Calculadora de Mesa Deli com 12 dígitos é ideal para escritório, comércio, caixa, financeiro e uso diário. Seu grande diferencial é o duplo display, permitindo que usuário e cliente visualizem o cálculo ao mesmo tempo, trazendo mais praticidade e clareza no atendimento e nas operações do dia a dia. O modelo conta com visor grande e de fácil leitura, além de função Check de até 120 passos, facilitando a conferência e revisão dos cálculos. Também possui teclas confortáveis, base estável e pés antiderrapantes, oferecendo mais segurança e conforto durante o uso. É uma calculadora prática, funcional e indicada para ambientes profissionais que exigem agilidade e precisão. Fabricada em material resistente, possui design clássico na cor preta e excelente desempenho para rotinas de escritório e atendimento comercial. Marca: Deli Modelo: EM049 Tipo: calculadora de mesa Capacidade: 12 dígitos Funções: duplo display, função Check, operações básicas Cor: preta Alimentação: 1 pilha AA Material: ABS', 99.9, 63.0, NULL, 'Stationery > School & Office Equipment > Calculators', 'https://cf.shopee.com.br/file/sg-11134201-823pw-molmb602gbgif5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1747380222%2F22199496370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
