INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259393679', 'KitKat Chocolate Wafer', 'Quando você precisar de um #Break, Kitkat te ajuda a quebrar a rotina: você abre, separa um finger, quebra ao meio e “hmmmmm”. Ele é o único capaz de mostrar as coisas incríveis que podem acontecer durante um #Break. Desfrute do equilíbrio perfeito entre o wafer crocante e o delicioso chocolate ao leite Nestlé. Cada embalagem contém um KitKat de 41,5g no icônico formato de trapézio.', 6.49, 5.29, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqnel8dayn7z94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554932%2F58259393679', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
