INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092528722', 'Filtro Ar Fiat Mobi 2016 a 2017 - 186412 - FAP9054', 'Filtro Ar Fiat Mobi 2016 a 2017 186412 FAP9054 (Easy On/Like/Way) - Motor 1.0 8v Flex - (Mecânico) Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 31.71, 31.71, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbn2-lmqh7csoixcpf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23092528722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
