INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259470024', 'Filme Plástico PVC Wyda 30m x 28 cm', 'O Filme Plástico PVC da Wyda é ideal para embalar alimentos de forma segura e prática, mantendo o frescor e protegendo contra contaminações. * Atóxico e inodoro, não interfere no sabor dos alimentos. * Transparente e brilhante, facilita a identificação do conteúdo. * Embalagem em caixa, fácil de usar e armazenar.', 12.49, 12.49, NULL, 'Home & Living > Kitchenware > Cling Wrap', 'https://cf.shopee.com.br/file/sg-11134201-82596-mqnekpx6kg0b3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555024%2F58259470024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493586261', 'Flexível Freio Gm Corsa 1994 a 2002 - 125757 - 4017', 'Flexível Freio Gm Corsa 1994 a 2002 125757 4017 PICK UP TRASEIRO (FÊMEA/FÊMEA - 231mm) É o componente que transmite a pressão hidráulica da tubulação para as rodas, permitindo o livre movimento das mesmas. Promover o controle do veículo em situações de baixo atrito entre pneu e solo, através da modulação da pressão hidráulica de frenagem impedindo assim o bloqueio das rodas. (Mangueira que tem a função de conduzir o fluído Hidráulico entre o cilindro mestre até a pinça de freio).', 29.95, 29.95, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbkw-lmyrkc7lvozd05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22493586261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492532964', 'Válvula Solenóide Nissan Tiida 2008 a 2013 - 187906 - 2011', 'Válvula Solenóide Nissan Tiida 2008 a 2013 187906 2011 Motor 1.8 16v Flex - (2 Vias) Problemas mais comuns no sistema de partida a frio Estão relacionados ao combustível ruim. A utilização de um combustível de baixa qualidade faz com que as vias de passagem da solenoide venham a entupir e não permitir a passagem do combustível. Outro problema no sistema pode ser a falta do uso. O combustível resseca os locais de passagem, fazendo com que a falta de lubrificação venha a tornar o material mais frágil, pois algumas partes do sistema são feitas de plástico.', 76.59, 76.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-lmt6enwl7j2xf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492532964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899028302', 'Filtro Ar Cabine Citroen C4 2009 a 2014 - 7529 - AKX1446', 'Filtro Ar Cabine Citroen C4 2009 a 2014 7529 AKX1446 (GLX) Motor 1.6 16v Flex (Mecânico)/(Exclusive/GL/Sport) Motor 2.0 16v Flex (Automático/Mecânico) (Sem carvão) (Com Abas laterais) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 32.89, 32.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7ravq-maoqsvrleuds3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18899028302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
