INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399399433', 'Rack Bancada Para Sala Ambiente Studio 1.8 Off White Nature - Imcal', 'Rack Bancada Para Sala Ambiente Studio 1.8 Off White Nature - Imcal Rack Bancada para Sala Ambiente Studio 1.8 Off White Nature - Imcal O rack da linha Studio 1.8 é uma peça elegante e funcional, perfeita para organizar sua sala de estar. Com seus três nichos, oferece amplo espaço para acomodar seus aparelhos eletrônicos. As duas portas proporcionam um espaço discreto para guardar seus acessórios, enquanto a gaveta com corrediça telescópica garante praticidade para acessar seu interior. Os pés em madeira maciça conferem estabilidade e um toque de sofisticação, além de garantir durabilidade. Destaque para o pé central com sapata regulável, que permite ajustar a altura conforme o nivelamento. Com seu design moderno e materiais de qualidade é fabricado pela Imcal combinando funcionalidade e estilo para complementar de forma elegante. Confira e garanta o seu! Características técnicas: - Produzido em MDP/ MDF de 15mm - Pintura na cor Off White Nature - Acabamento em UV fosco brilho - Possui 2 portas - Possui 3 nichos - Possui 1 gaveta - Corrediças telescópicas - Dobradiças metálicas - Pés em madeira maciça - 1 pés central com sapata regulável - Lindo design Dimensões: Altura: 55,6 cm Largura: 184 cm Profundidade: 40 cm Informações importantes: *Não realizamos a montagem ou instalação do produto, porém acompanha manual de instruções. *Toda mercadoria segue segurada contra qualquer sinistro, em caso de anormalidade, recuse. *As caixas ou pacotes possuem identificação com o nome, cidade e quantidades de volumes relativos à compra para conferencia do recebedor.', 635.55, 635.55, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-lzp4vngcwcj891', 'htt