INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094685600', 'Capa para Notebook 14" Preta | Sleeve Coca-Cola', 'A Capa para Notebook Sleeve Coca-Cola é a escolha perfeita para quem busca estilo, proteção e conveniência. Ideal para notebooks de 14", oferece proteção superior contra riscos e impactos, graças ao seu interior acolchoado de alta qualidade. Seu design icônico com a logo Coca-Cola garante um visual moderno, enquanto o fechamento em zíper duplo proporciona acesso fácil e seguro. O bolso frontal extra é perfeito para guardar acessórios essenciais como cabos, fones e adaptadores. Uma combinação perfeita de funcionalidade e estilo para seu notebook! Especificações: Design exclusivo e licenciado Coca-Cola, garantindo estilo, autenticidade e alta qualidade Compatível com: notebooks de 14 polegadas Interior acolchoado para uma proteção extra contra riscos e impactos Zíper duplo para fácil abertura e segurança Bolso frontal para organizar acessórios como cabos, carregadores e outros itens essenciais Cor preta, um visual sofisticado e versátil para qualquer situação Garantia: 3 meses Garantia Legal de 3 meses contra defeitos de fabricação. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 219.9, 129.9, NULL, 'Computers & Accessories > Peripherals & Accessories > Laptop Skins & Covers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh0xw52abf9j14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671199849%2F23094685600', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298258445', 'Mangueira Radiador Superior VW GOL G5 1.6 8v 2008 Ate 2012 - 89722 - 8603', 'Mangueira Radiador Superior VW GOL G5 1.6 8v 2008 Ate 2012 Superior Radiador (G5) - 1.0/1.6 8vO liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 42.03, 42.03, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-m6u4k70n058pad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298258445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
