INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256896336', 'Protetor De Colchão Queen Buddemeyer Maison Algodão Branco', 'CARACTERÍSTICA DO PRODUTO:Além de serem não alérgicos, são impermeáveis e feitos com material de alta qualidade. Confeccionados em malha de algodão, mantêm a temperatura da cama agradável.Tecido com toque suave e acabamento de excelente qualidade.Qualidade e design Buddemeyer.CONTEÚDO DA EMBALAGEM:Contém: 1 protetor de colchão 160x200x40cm.COMPOSIÇÃO: Tecido da Frente em 100% Algodão, Enchimento e Tecido Lateral em 100% Poliéster, Forro em 100% Poliuretano.COR: 001 - Branco.DESCRIÇÃO:Protetor de colchão queen Maison II. Tecido da frente em 100% algodão. Enchimento e tecido lateral em 100% poliéster. Forro em 100% poliuretano. Adequado para colchão com altura até 40cm. A coleção de protetores Maison II da Buddemeyer proporciona proteção e conforto para sua cama. Produto não alérgico, impermeável e confeccionado com material de alta qualidade. Feito em malha de algodão, mantém a temperatura da cama agradável. Os protetores podem ser lavados à máquina, garantindo higienização ideal. Acabamento com elástico para ajuste perfeito ao colchão.INSTRUÇÕES DE CUIDADO:Lavar antes de usar. Cores escuras devem ser lavadas separadamente das cores claras. Lavar em água fria ou em temperatura de até 30°C em processo suave. O sabão recomendado para manter as características do produto é o de coco ou neutro, não aplicar diretamente no produto. Evitar produtos com cloro. Não exagerar no uso de sabão em pó e usar pouco amaciante. Permite secadora em temperatura baixa. Não passar.', 461.5, 299.9, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134207-820md-mls36t9yc0li01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1027399414%2F58256896336', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
