INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294035014', 'Módulo Lateral São Paulo', 'Descrição O Módulo Lateral São Paulo integra o Conjunto Modular São Paulo e foi desenvolvido para agregar sofisticação e funcionalidade ao ambiente. Possui uma porta com puxador metálico embutido, garantindo um visual moderno e elegante. Conta com três prateleiras de 25 mm de espessura, sendo duas delas com iluminação em LED, ideais para valorizar objetos decorativos. O tampo robusto de 37 mm e a haste decorativa metálica na cor dourada reforçam o design contemporâneo do móvel. Versátil, o módulo pode ser montado tanto do lado esquerdo quanto do direito, adaptando-se facilmente à composição do espaço. Medidas • Altura: 1,98 m • Largura: 0,58 m • Profundidade: 0,41 m • Peso bruto: 32,95 kg Informações Técnicas • Marca: Linea Brasil • Modelo: Módulo Lateral São Paulo Linea Brasil • Material: MDP/MDF • Tampo: MDP com espessura de 37 mm • Portas: 1 porta de abrir em MDP • Prateleiras: 3 prateleiras em MDP com espessura de 25 mm • Iluminação: Fitas de LED • Puxador: 1 puxador de alumínio embutido • Dobradiças: 2 dobradiças metálicas • Pés: Não possui • Acessórios: 2 hastes metálicas decorativas • Quantidade de volumes: 1 Conteúdo da Embalagem • 1 Módulo Lateral São Paulo', 972.99, 749.0, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfgx-ma0c97m51kfdd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1423420147%2F22294035014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
