INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55658070653', 'Filtro Ar Motor Jeep Compass 2.0 16v Turbo Gasolina Após 2025 68469692AA', 'Garanta a máxima performance e proteção para o motor do seu Jeep Compass 2.0 16v Turbo gasolina (modelos a partir de 2025) com o filtro de ar Japanparts 68469692AA. Projetado com materiais de alta eficiência, ele bloqueia impurezas e partículas que comprometem o funcionamento do motor, melhorando a queima de combustível e reduzindo o desgaste das peças internas. Aplicações: JEEP COMPASS 2.0 16V TURBO GASOLINA APÓS 2025 Especificações: Tipo de Produto: Filtro de Ar Motor Comprimento: 357mm Largura: 232mm Altura: 45mm Referência: FABR410S Marca: Japanparts EAN: 7908374436230 Números Originais: 68469692AA', 49.9, 49.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-81zw9-mmix74ko5slgc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F55658070653', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16299683306', 'Rato Vertical UGREEN Ergonômico 4000DPI Sem Fio Silent Click Mouse Para PC Portátil Windows Mac OS', '· Modo duplo: Este mouse ergonômico oferece conectividade Bluetooth e 2.4GHz, permitindo conectar um dispositivo 2.4G e dois dispositivos Bluetooth simultaneamente. Precisão de 4000DPI: Com quatro opções de DPI (1000/1600/2000/4000), você pode ajustar facilmente a sensibilidade para combinar com sua resolução de uso ou tela, garantindo um controle preciso. Conecte-se a 3 dispositivos: Conecte perfeitamente este mouse ergonômico sem fio a três computadores de uma só vez. O modo DPI possui memória independente, permitindo alternar entre os dispositivos sem afetar suas configurações preferidas. · Ampla Compatibilidade: Compatível com uma ampla gama de sistemas operacionais, incluindo Windows 7/8.1/10/11, macOS 10.15 e acima, iOS 13.4 e acima, iPad OS 14.0 e acima, Linux, Chrome OS e Android 5.0, Versátil para vários dispositivos. Este mouse vertical oferece uma faixa sem fio de até 10m. Apresenta testes de laboratório, com os botões esquerdo e direito classificados por 5 milhões de cliques e o botão do meio classificado por 1 milhão de cliques, garantindo durabilidade e estabilidade de longa duração. ==========================================================================================', 198.5, 98.9, NULL, 'Computers & Accessories > Keyboards & Mice > Mice', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m627gkzv16oh69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F218996205%2F16299683306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
