INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209673704', 'SuperCoffee 3.0 Língua de Gato', 'Mais do que um pré-treino e mais do que um café, o SuperCoffee é uma bebida energética e um suplemento alimentar com benefícios para o corpo, a mente e o bem-estar diário. Reunimos tudo que acreditávamos ser necessário, em uma fórmula única, para proporcionar energia inteligente, potente e que não oscila e maior performance cognitiva, para quem deseja bem-estar e alta performance. O SuperCoffee Língua de Gato é uma edição especial, resultado da parceria entre a Caffeine Army e a Kopenhagen, que traz o sabor clássico do chocolate Língua de Gato com os benefícios funcionais do SuperCoffee. Rico em nutrientes que promovem energia limpa e duradoura, ideal para quem busca manter o foco e a disposição ao longo do dia.', 219.99, 219.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mqnel13mtfy99b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555006%2F58209673704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
