INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22319127433', 'Pneu Falcon 400 XT 600 Traseiro 120/90-17 Sahara 350', 'CONTEÚDO DA EMBALAGEM : - 1 PNEU FALCON XT 120/90-17 TRASEIRO REMOLD Posição: Traseiro Medida: 120/90-17 Carga: 257 Kg Aro: 17 Tipo: com câmara Tipo: REMOLD Montagem: USA CÂMARA (câmara não inclusa na compra) Garantia de TRÊS MESES contra defeitos de fabricação A Cesari Pneus LTDA é uma empresa brasileira com raízes profundas no estado de Santa Catarina. Fundada em 2010, a empresa se destaca por dar uma nova vida a pneus que seriam descartados, transformando-os em produtos de alta qualidade para uso off road e com um custo mais acessível. Esse processo não só reduz o impacto ambiental, mas também contribui para a economia local, gerando empregos e movimentando o mercado de peças para motocicletas. DESPACHAMOS EM ATÉ 24 HORAS ÚTEIS SATISFAÇÃO E RESPEITO COM O CLIENTE EM PRIMEIRO LUGAR.', 200.0, 200.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1px2qumt9zl91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674490148%2F22319127433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
