INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41210194755', 'Conjunto De Mesa Com 2 Cadeiras Empoli Em-6021 Para Jardim', 'DESCRIÇÃO RESUMIDA: Este conjunto de jardim com duas cadeiras é perfeito para uso interno e externo. É ideal para jardim, pátio, varanda ou terraço, para passar momentos ao ar livre. As cadeiras são empilháveis, permitindo um armazenamento prático e fácil quando não estão em uso. Projetadas para anos de diversão, a estrutura de aço, o tampo de vidro e os assentos de textilene garantem proteção contra ferrugem e raios UV, prevenindo o desgaste quando expostos às intempéries. Características: Marca: Empoli Modelo: EM-6021 Especificações: Peças: 3 Cor: Preto Uso: Adequado para ambientes internos e externos Mesa: O tampo da mesa é feito de vidro, fácil de limpar e resistente a arranhões. Seus quatro pés em formato de garra, com almofadas protetoras na base, melhoram a estabilidade da mesa e protegem o piso contra arranhões. Cadeiras: Seu tecido textilene é impermeável, durável e bem ventilado. Essa confortável cadeira de pátio também possui apoios de braços e encosto que proporcionam excelente suporte lombar. Armazenamento: Cadeiras empilháveis Resistência: Material impermeável, resistente à ferrugem e proteção UV, suporta de 90 à 120Kg Dimensões do produto: Mesa: 72x60x60 (AxLxC) Cadeira: 93x41x46 (AxLxC) Conteúdo da embalagem: 1 × Mesa de jantar com tampo de vidro 2 × Cadeiras com estrutura de aço e assento em malla Garantia: 6 meses Peso: Mesa: 5,9Kg Cadeira: 3,7Kg Total: 13Kg', 499.99, 347.99, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcmkmmpketde77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359168917%2F41210194755', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
