INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598030798', 'Kit 2, 3 ou 5 Shorts Infantil Menina Bermuda Moletinho 100% Algodão Com Friso Constratante', 'Opções de kits disponíveis : 🌸Kit 5 Shorts Infantil Menina🌸 🌸Kit 3 Shorts Infantil Menina🌸 🌸Kit 2 Shorts Infantil Menina🌸 Confeccionados em moletinho 100% algodão, são leves, frescos e perfeitos para todas as aventuras das crianças. ✨ Detalhes do Produto: Modelo: Bermuda de moletinho, prática e estilosa. Composição: 100% Algodão, garantindo maciez e conforto para a pele delicada das crianças. Acabamento: Detalhes encantadores com cadarço ajustável e friso contrastante que deixam o visual ainda mais moderno. Conforto Total: Tecido leve e fresco, ideal para brincar, passear ou relaxar. Kit Sortido: Shorts enviados em cores variadas, sempre com combinações lindas e exclusivas para sua pequena. 📌 Observação Importante: Na compra de 1 kit, você receberá cores diferentes em cada short, sem repetições. Na compra de mais de 1 kit, algumas cores podem se repetir. 📏 Guia de Tamanhos: Tamanho 1: Veste 6 a 12 meses Tamanho 2: Veste 1 ano Tamanho 3: Veste 2 anos Tamanho 4: Veste 3 anos Tamanho 6: Veste 4/5 anos Tamanho 8: Veste 6/7 anos Tamanho 10: Veste 8/9 anos 🔍 Atenção: Os tamanhos podem variar de acordo com o biotipo/tamanho de cada criança. 👉 Consulte a tabela de medidas nas imagens ou na guia de tamanho da Shopee para escolher o tamanho ideal. 🚀 Envio Rápido: Pedidos realizados até as 11h são enviados em até 24 horas! 👗 Adquira já o seu kit e garanta peças práticas, confortáveis e estilosas para sua pequena!', 46.0, 19.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6ieskkhbltz25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F20598030798', NULL, NULL, '2026-07-28T02:11:3