INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259024909', 'Cheirinho Para Carro - Dr. Marcus Cosmic Cat/dog Jeep', 'Frescor com durabilidade de 45 dias Enviamos para todo o Brasil Transforme a experiência de dirigir com o Aromatizante Dr. Marcus, disponível nos modelos Cosmic Cat e Cosmic Dog. Este aromatizante foi projetado para proporcionar um ambiente agradável dentro do seu carro ou caminhonete, eliminando odores indesejados e deixando um aroma fresco e envolvente.', 52.0, 52.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820m8-mo05ampotjic4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1774364292%2F58259024909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
