INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994264167', 'Atuador Marcha Lenta Ranger 4.0 V6 Explorer 4 / 6 Cilindros', 'PRODUTO: Atuador de Marcha Lenta MARCA: LP Industria CÓDIGO: LP695020/623 A LP Industria, com mais de 30 anos no mercado de reposição é especializada na produção de componentes essenciais para o controle da rotação do motor em situações de marcha lenta. Esses atuadores garantem que o motor funcione suavemente quando o veículo não está em movimento, ajustando o fluxo de ar de maneira precisa. A LP Industria dedica-se à alta qualidade, utilizando materiais duráveis e processos de fabricação rigorosos para assegurar o desempenho confiável e eficiente dos motores. OBSERVAÇÕES: - ESTE É UM PRODUTO ORIGINAL LP INDUSTRIA - Qualidade garantida APLICAÇÕES: Ford Explorer 4 / 6 Cilindros - 1995 até 2000 Ford Ranger 4.0 V6 - 1993 até 2000 OUTROS CÓDIGOS PARA REFERÊNCIA: 96TF9F715AB / 96TF-9F715-AB', 299.9, 299.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rdw5-mcrr9bsbms0e9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353894917%2F23994264167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
