INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799319273', 'Boneca Sonho Azul Sem Cabelo Cotiplás 2072', 'Boneca Interativa - Sonho Azul - Sem Cabelo - Cotiplás: as crianças irão adorar brincar de casinha e cuidar da Boneca Sonho Azul que fala. Ela é muito fofinha e precisa de cuidado e proteção. A Boneca Sonho Azul pede carinho e atenção, proporcionando horas de diversão e entretenimento para a criança. Com 56 cm de altura e muita interação. “Gosto de você”, “Você é linda” e “Oi, você quer brincar comigo?” são apenas algumas das tantas frases que essa boneca reproduz de um jeito todo meigo. A Sonho Azul é macia, gostosa de abraçar e tem um cheirinho delicioso. Além disso, possui um lindo vestido de tecido todo colorido. As crianças vão passar horas conversando com essa bebê. Detalhes: - Pede carinho e atenção - Macia e gostosa de abraçar - Vestidinho em tecido Características: - Marca: Cotiplás - Modelo: 2072 Imagens meramente ilustrativas Ficha Técnica: - Referência: 2072 - Embalagem (C x A x L): 33 x 65 x 16.5 cm - Embalagem (Peso): 1.236 kg - Material / Composição: Vinil macio e corpo em tecido - Funcionamento: à pilhas - 03 Pilhas AG 13/LR44 1.5V (inclusas) - Recomendação: para crianças a partir de 03 anos de idade - Categoria: Bonecas e Cia - Coleção: Sonho Azul - Tipo: Boneca Bebê Interativa Conteúdo da Embalagem: - 1x Boneca Sonho Azul Sem Cabelo - Boneca - Cabelo - Azul - Sonho - 120 - Frases - Cotiplás - Aniversário - Interativa - Infantil - Acessórios - Bebê - Menina', 161.12, 145.01, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd53-lwfsmnes232jf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F19799319273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
