INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193129843', 'Própolis Verde Amesse - Extrato Concentrado em Cápsulas (60 Unidades)', 'O Própolis Verde Amesse em forma de extrato concentrado em cápsulas é um poderoso aliado para a sua saúde. Extraído das abelhas, este produto oferece uma série de benefícios graças às suas propriedades únicas. A Própolis Verde Amesse é conhecida por fortalecer o sistema imunológico, auxiliando na defesa do organismo contra agentes externos. Rica em nutrientes e compostos antioxidantes, como flavonoides, ácidos fenólicos e vitaminas, ela combate o estresse oxidativo, protegendo as células contra danos e contribuindo para uma vida mais saudável. Como Consumir: Contraindicação: Fortaleça sua imunidade e promova o bem-estar com o Própolis Verde Amesse. Experimente agora e descubra uma nova forma de cuidar da sua saúde de maneira natural e eficaz.', 83.07, 49.0, NULL, 'Health > Food Supplement > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6o3yexv8g1c34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434178148%2F22193129843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
