INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17335614926', 'Creme Relaxante Óleo de Coco e Óleo de Avelã 200gr - Salon Line', 'Creme Relaxante Óleo de Coco e Óleo de Avelã 200gr - Salon Line O Creme Relaxante Salon Line Óleo de Coco e Óleo de Avelã Cachos Definidos e Soltos foi especialmente desenvolvido para promover a soltura dos cachos. Sua fórmula à base de Guanidina, proporciona o relaxamento de cabelos crespos até atingirem o ponto de cacheados. Uso profissional. Indicações: Para quais tipos de cabelo? Cabelos cacheados e crespos. Qual a indicação? Cabelos volumosos e com frizz. Pode usar a partir de quantos anos? A partir de 12 anos. Não é Vegano, não é liberado. Ativos: A fórmula do Creme de Relaxamento Cachos Definidos e Soltos conta com Óleo de Avelã para os cabelos, uma poderosa fonte de Vitamina A, E, do complexo B e Ácido Linoleico, que atua na nutrição capilar e antioxidação do fios. Modo de Uso: As instruções de uso completas estão contidas no folheto explicativo que acompanha o produto. A utilização incorreta pode danificar o cabelo. Especificações: Código interno: 9694953 Volume: 200gr Importante: * Produtos de decoração não inclusos. Imagens meramente ilustrativas; * As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário; * Os dados divulgados são de responsabilidade do fabricante/fornecedor.', 59.9, 59.9, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj4lgwu8129c08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F17335614926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20597918501', 'Testador de Baterias Automotivas Vonder Com Impressora – Diagnóstico Rápido e Preciso', 'Testador de Baterias Vonder Automotivas Com Impressora O Testador de Baterias Automotivas TBV 1400 é uma ferramenta digital multifuncional projetada para diagnósticos precisos e eficientes em baterias automotivas de 12V. Com visor em cristal líquido e impressora integrada, ele permite registrar os resultados dos testes de forma rápida e prática, sendo ideal para profissionais da área automotiva, oficinas e entusiastas. Itens Inclusos: 1 Testador de Baterias Automotivas TBV 1400; 2 Bobinas de papel para impressora; Bateria de 9V (NEDA 1604 ou 6F22); Manual de instruções. Detalhes Técnicos Modelo: TBV 1400; Tipo de Bateria Testada: Baterias automotivas de 12V (chumbo-ácido convencionais e VRLA); Alimentação: Bateria de 9V (NEDA 1604 ou 6F22); Faixa de Tensão de Operação: 1,5V a 17V; Corrente de Arranque a Frio (CCA): 50A - 1400A; Temperatura de Operação: -18°C a 50°C; Peso: 0,78 kg; Impressora Integrada: Inclui 2 bobinas de papel para registro dos resultados. Por que escolher este produto? ✔ Produto novo e original; ✔ Pronta entrega e envio em até 24 horas; ✔ Compra 100% segura.', 1119.9, 1119.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Battery Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1qzjichgj4h09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F20597918501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
