INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42251846031', 'Fundo Fotográfico Textura para Chão Tapete Painel Em Tecido Sublimado - Diversos Modelos', '>> FUNDO FOTOGRÁFICO EM TECIDO TEXTURA CHÃO IDEAL PARA SEU ENSAIO << O Fundo fotográfico em tecido textura chão possibilita diversos ensaios. Com artes exclusivas elaboradas por uma equipe especializada e o melhor material do mercado, pois buscamos melhorar a cada dia! • BENEFÍCIOS DOS FUNDOS CRIATEMA: - Produzido em tecido com toque suave - Não reflete luz - Após dobrado não amassa - Cores vivas e nitidez incrível - Impressão impecável - Pode ser lavado - Não desbota • ACABAMENTO: Pode ser em overloque ou à laser, à depender da demanda. Ambos com acabamento perfeito que garantem sua durabilidade. • TAMANHO : 2,20 x 1,50m - Horizontal: 2,20 de largura por 1,50 de altura. • TAMANHO : 2,60 x 1,70m - Horizontal: 2,60 de largura por 1,70 de altura. • DICAS DE USO: - Ideal para fotos Newborn e infantil. - Para utilizar o fundo fotográfico em tecido textura chão recomendamos que fixe com fita adesiva larga ou fita dupla face 3M. • ITEM INCLUSO: - 1 fundo fotográfico em tecido Malha. • FICHA TÉCNICA: Tecido: Malha New (estica e não amassa) Composição: 95% Poliéster + 5% elastano Gramatura: 140g m² Informação complementar: As cores podem variar nas fotografias devido à qualidade da câmera fotográfica, ajustes/configurações da câmera, lente e iluminação do ambiente. Além disso, as configurações brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. ** Todos os nossos produtos passam pelo processo de sublimação, sendo uma etapa onde passam por uma temperatura muito alta, podendo ter uma pequena variação em seu tamanho de até 5cm.** Nossos fundos fotográficos têm uma qualidade incomparável e é simplesmente incrível! Nosso tecido é maravilhoso, proporciona um toque suave e sem marcas de dobras, as cores são bem vivas e a nitidez da resolução incrível. Praticidade e economia de espaço, podem ser lavados, dobrados, guardados e é só esticar e arrasar nas fotografias. Possui acabamento impecável, não desbota e o caimento é perfeito! Uma combinação de qualidades especiais.', 139.9, 52.8, NULL, 'Cameras & Drones > Camera Accessories > Lighting & Studio Equipments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcs6pjzwqqeq10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F42251846031', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8275421449', '1~4 FORMAS BWB COM SILICONE (3 PARTES) CÓD.:9994- TABLETE ONDULADO 250g. (CHOCO)', 'MODELO: TABLETE ONDULADO- CÓD.:9994 FORMA ESPECIAL (3 PARTES), FACILIDADE DE USO E PRECISÃO NA PRODUÇÃO DE CHOCOLATES. ELAS SÃO PROJETADAS PARA FACILITAR A PRODUÇÃO COM PROCESSOS SIMPLES E RÁPIDOS. E GARANTEM CHOCOLATES COM CASCAS UNIFORMES, ACABAMENTO BRILHANTE E PESO CONSISTENTE. QUANTIDADE: 1~4 UNIDADES COR: TRANSPARENTE MATERIAL: ACETATO(PVC) E SILICONE DESCRIÇÃO DO PRODUTO CAVIDADES: 2 DIMENSÕES (mm): COMP.: 140 x LARG.: 70 x ALT.: 17cm PESO CASQUINHA: 70g PESO MÉDIO: 250g **** ESCOLHER Á QUANTIDADE NA VARIAÇÃO DO ANÚNCIO****', 16.85, 16.85, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6cpkrsqmj5x31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F8275421449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
