INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198150227', 'Jogo Monopoly Classic Refresh - Hasbro', 'Jogo Monopoly Classic Refresh - HasbroO Jogo Monopoly Classic Refresh da Hasbro proporciona diversão garantida para toda a família. Nesta edição do renomado jogo de tabuleiro, os jogadores poderão experimentar a jogabilidade tradicional, com recursos aprimorados que incluem uma bandeja de armazenamento elegante para manter o dinheiro, cartões e componentes organizados. Com fichas, casas e hotéis de tamanho ampliado em relação às edições anteriores, a experiência de jogo torna-se ainda mais prática e agradável. Os participantes movem-se pelo tabuleiro comprando propriedades e cobrando aluguéis, com o objetivo de permanecer com dinheiro enquanto os adversários declaram falência. Ideal para crianças e adultos, o Monopoly Classic Refresh é um presente perfeito para momentos de lazer em família. Desfrute de disputas emocionantes e muita interação em um dos jogos de tabuleiro mais populares do mundo. Diferenciais:Jogo clássico e divertido para toda a família. Bandeja de armazenamento para organização dos componentes. Fichas, casas e hotéis de tamanho ampliado para facilitar o manuseio. Estimula o pensamento estratégico e a negociação. Mais sobre o Produto:Jogabilidade tradicional do Monopoly. Componentes aprimorados para melhor experiência de jogo. Ideal para crianças e adultos. Promove a interação entre os jogadores. Dicas de Uso:Organize os componentes na bandeja de armazenamento para facilitar o acesso durante o jogo. Estimule a negociação e a estratégia entre os jogadores. Aproveite os momentos em família e divirta-se com partidas emocionantes do Monopoly. Ficha Técnica:Marca: Hasbro; Nome do produto: Jogo Monopoly Classic Refresh; Idade recomendada: A partir de 8 anos; Selo Inmetro: 003707/2021; Contém: 1 jogo de tabuleiro.', 172.49, 172.49, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m9ojyp5zf4bt1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19198150227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
