INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699049333', 'Jogo Talher Inox 48 Pecas Garfo Faca Colher Sobremesa Restaurante Buffet Premium Euro Original Line', 'Jogo Talher Inox 48 Pecas Garfo Faca Colher Sobremesa Restaurante Buffet Premium Euro Original Line O Kit Garfo Faca Colher de Mesa Inox Euro com 48 pecas e perfeito para quem busca qualidade e elegancia em suas refeicoes. Feito em aco inoxidavel, tanto a lamina quanto o cabo, esse kit Garfo Faca Colher sao resistentes e duraveis, garantindo sua satisfacao por muito tempo. O Kit ele e ideal para uso em mesas de jantar, proporcionando conforto e praticidade. Adquira agora mesmo o Kit Garfo Faca Colher de Mesa Inox Euro com 48 pecas e tenha uma experiencia gastronomica ainda mais especial. Medidas Garfo Mesa: . Peso: 0,40 g . Comprimento: 20 cm . Largura: 2,5 cm . Espessura: 3 mm . Material: Aco inox . Marca: Original Line Medidas Faca Mesa: . Peso: 0,64 g . Comprimento: 23 cm . Largura: 2,2 cm . Espessura: 4 mm . Material: Aco inox . Marca: Original Line Medidas Colher Mesa: . Peso: 0,50 g . Comprimento: 20 cm . Largura: 2 cm . Espessura: 3 mm . Material: Aco inox . Marca: Original Line Medidas Colher Sobremesa: . Peso: 0,44 g . Comprimento: 18,2 cm . Largura: 3,8 cm . Espessura: 2,5 mm . Material: Aco inox . Marca: Original Line Conteudo Da Embalagem: . 12 Garfos Mesa . 12 Facas Mesa . 12 Colheres Mesa . 12 Colheres Sobremesa Cuidados: Para manter seus talheres sempre brilhando, lave com esponja macia, sabao ou detergente neutro. Produtos abrasivos como palha de aco podem riscar e prejudicar o brilho. Seque imediatamente para evitar manchas. Recomenda-se o uso de agua quente para melhorar o brilho Nao guarde em local umido, a umidade pode provocar manchas. Importante: Garantia de 3 Meses. Valor do Kit. Imagens Meramente Ilustrativas. Nao nos responsabilizamos pelo mau uso do produto.', 336.9, 199.9, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/br-11134211-7r98o-lnrdbyqpul3b62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F281898655%2F20699049333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47162464744', 'Perfume Khadlaj Island EDP 100ml', 'Apresentando Khadlaj Island Extrait de Parfum – uma fragrância luxuosa de 100 ml que exala sofisticação tropical. Notas principais: A fragrância começa com uma explosão brilhante e picante de bergamota, criando um tom refrescante. Notas do Meio Oposto: No seu ceração, uma deliciosa mistura de coco, gengibre e abacaxi transporta você para uma ilha banhada pelo sol com sua doçura cremosa e exótica. Notas de base: O aroma termina com uma base rica de âmbar, feijão tonka e sândalo, oferecendo um acabamento quente, suave e sensual que permanece lindamente. Aproveite a elegância tropical da Ilha Khadlaj, uma fragrância que captura a essência do paraíso a cada borrifada.', 399.9, 239.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820li-mpmkg0oe9loh90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369057850%2F47162464744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
