INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27780953462', 'Livro Livro tapete Comfy and Cozy - Meu livrão de colorir', 'Divirta-se com este livro-tapete super fofinho! Ao desdobrar as páginas, você vai encontrar algumas atividades para aprender a desenhar e também ilustrações exclusivas que retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo enquanto relaxa, seja colorindo com lápis de cor ou marcadores. Convide sua família e torne esse momento memorável!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Aleksandra Bozhbova_x000D_ Idioma: Português_x000D_ Páginas: 16_x000D_ Dimensões: L 24.20 x A 33.00 x E 0.10_x000D_ ISBN: 9786526123669_x000D_ Coleção: Comfy goods (livro tapete)_x000D_ Linha Editorial: Ciranda Cultural - Lab_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Colorir, Atividades, Passatempos, Relaxar, Arteterapia_x000D_ BISAC: Não Ficção Infantil / Mídia Tie-in_x000D_ Linha de Produto: Livro tapete_x000D_ Encadernação: Flexível_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 9.9, 6.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd3n-m7tqx12hrqnb66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F27780953462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
