INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193983287', 'Rolamento Universal 6202 RS 15x35x11 mm Vedado Borracha Aço Forjado - IR16202 RS', 'Especificações Técnicas: • Marca: IRB AUTOMOTIVE • Cód. da peça: IR16202 RS • Tipo de rolamento: Esferas Vedado Borracha Medidas: • Diâmetro Interno (mm): 15 • Diâmetro Externo (mm): 35 • Espessura (mm): 11 • Peso (g): 40 Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. Rolamento ideal para diversas aplicações automotivas e industriais.', 14.9, 14.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9gbhi2g61x574', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F22193983287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
