INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593671371', 'Livro Jesus e Eu', 'Converse com os pequeninos sobre Deus com este livro de orações que traz vinte temas importantes, como orar, compartilhar, ajudar e perdoar, além de abordar sentimentos como preocupação, medo, animação e outros. Um livro com perguntas simples, orações doces e sugestões de trechos da Bíblia, ideal para ser lido em família. _x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Katherine Walker_x000D_ Ilustrador: Danielle Mudd_x000D_ Idioma: Português_x000D_ Páginas: 42_x000D_ Dimensões: L 13.00 x A 18.40 x E 3.80_x000D_ ISBN: 9786526115930_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Deus, Devocional, Criança, Ensinamentos_x000D_ BISAC: Não Ficção Infantil / Religiosa / Cristã / Devocional & Oração_x000D_ Linha de Produto: Almofadado médio_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Cartonado', 59.9, 59.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmn-m5kdzv9b53sw48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22593671371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294530397', 'Bicicleta ARO 12 AÇO - Meninas 2 a 7 Anos - Pneu Borracha Automotivo - Freio VBRAKE - Banco Estofado', '🚴‍♀️ FORCE BIKE – Modelo Runner Girl Roxo e Rosa Estilo, resistência e segurança para as pequenas campeãs! A FORCE BIKE Runner Girl une design moderno e materiais de alta qualidade para garantir conforto, estabilidade e diversão em cada pedalada. Ideal para crianças de 2 a 7 anos, suporta até 50 kg e é perfeita para quem quer pedalar com muito charme e confiança. 💜UNICO MODELO COM RODAS DE AÇO Características Técnicas: Quadro em aço carbono de alta resistência Rodas, aros e cubos em aço – mais durabilidade e firmeza Pneus de borracha inflável padrão automotivo – melhor aderência e conforto Freios V-Brake dianteiro e traseiro – mais segurança na frenagem Banco estofado com regulagem de altura e estampa floral exclusiva Cestinha azul funcional e resistente Paralamas dianteiro e traseiro Proteção de corrente para evitar acidentes Pézinho de apoio combinando com as cores da bike Certificação Inmetro – qualidade e segurança garantidas 📏 Dimensões: 86 x 54 x 52 cm 🎨 Cores: Roxo, Rosa e Branco ⚠️ Instruções de Segurança: Utilize sempre com supervisão de um adulto Verifique freios, pneus e fixações antes do uso Use capacete, joelheiras e cotoveleiras para maior proteção', 499.0, 368.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-820lz-mopkjeialvcw7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F23294530397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23820087474', 'Sandália Infantil Menina Feminina Nº28 Ao 36 Laço Pérola Renda 05.04J', 'A sandália de saltinho é um clássico que não sai de moda. Modelinho super delicado e confortável que traz todo encanto para os looks femininos. DESCRIÇÃO Estilo salto, confeccionada em material sintético com palmilha estofada e confortável. Possui um saltinho com 2,5 cm de altura, fechamento com fivela em resina e solado antiderrapante. DETALHES DO PRODUTO Material Externo: Sintético Material Interno: Sintético Material da Sola: PVC Material da Palmilha: Sintético dublado com espuma Estilo: Saltinho Fechamento: Fivela Embalagem: Caixa individual Nós da Pópidi cuidamos com carinho da relação pré e pós-venda, afinal a satisfação de nossos clientes é muito importante para nós! Atendimento: Segunda à sexta: 07:00 às 18:00 Sábado: 09:00 às 13:00 TABELA DE MEDIDAS 28 ----- 19,0 cm 29 ----- 20,0 cm 30 ----- 20,5 cm 31 ----- 21,0 cm 32 ----- 22,0 cm 33 ----- 22,5 cm 34 ----- 23,0 cm 35 ----- 24,0 cm 36 ----- 24,5 cm COMO MEDIR: Coloque o pé em cima de uma folha de papel e risque em volta dele com um lápis ou caneta. Meça o comprimento do topo até a base do contorno e adicione 0,5 cm de folga. LIMPEZA E CONSERVAÇÃO: Evite usar substâncias abrasivas como álcool, detergentes ou solventes nos calçados. Nunca os mergulhe na água, os deixe de molho ou lave na máquina. A secagem dos produtos deve ser feita à temperatura ambiente e na sombra, nunca no sol ou em máquinas. SOBRE A EMPRESA Visão Estar em constante expansão e inovação, de uma forma consistente e arrojada. Missão Proporcionar o bem estar dos nossos clientes, satisfazendo-os em um ambiente agradável e cortês com produtos a preços justos e de qualidade. Valores Respeito, Dedicação, Conexão e Atitude.', 94.9, 89.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcaxrhhzvch77c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318839552%2F23820087474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
