INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48506210877', 'Tênis Asics Dynablast 5 Rose Bege e Coral - Feminino', 'Mais energia e conforto a cada passada! Tênis Asics Dynablast 5 Rose Bege e Coral - Feminino Ficha Técnica: Marca: Asics Cor: Rose bege e coral Gênero: Feminino Cabedal: Engineered jacquard mesh para melhor ajuste e respirabilidade Palmilha: OrthoLite X-30 Sola: Borracha com AHAR™ LO para maior resistência ao desgaste Fechamento: Cadarço Amortecimento: Médio Estabilidade: Neutra-supinada Tecnologias: FF BLAST PLUS, FlytefoamBlast, OrthoLite X-30, AHAR LO Entressola: FF BLAST PLUS, com design inspirado em trampolim para maior retorno de energia Indicado: Corrida, academia e treinos Detalhes: Pelo menos 50% do cabedal é feito com materiais reciclados para reduzir impactos ambientais O Asics Dynablast 5 foi criado para quem busca amortecimento eficiente e conforto de alto nível. Porque investir: Seu cabedal em engineered mesh garante respirabilidade e ajuste anatômico, enquanto a entressola FF BLAST PLUS oferece um retorno de energia explosivo, inspirado em trampolins. A palmilha OrthoLite X-30 acrescenta suavidade em cada passo e o solado com AHAR LO garante durabilidade mesmo nos treinos mais intensos. Um tênis perfeito para correr mais longe com menos esforço. Conteúdo da embalagem: 1 par de Tênis Asics Dynablast 5 Rose Bege e Coral – Feminino', 799.99, 686.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82614-mko740l1tfcx3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F48506210877', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498256684', 'Top Fitness De Academia Corrida Basic Alça Fina - Olympikus', 'Top Fitness de Academia Basic – Olympikus O Top Basic da Olympikus é a peça coringa ideal para a rotina de treinos e atividades diárias. Com um design minimalista e funcional, ele oferece conforto, suporte e liberdade de movimentos, se adaptando facilmente a diferentes combinações de looks esportivos. Seu visual discreto e moderno é valorizado por alças finas e pelo logo Elos ton sur ton nas costas, que trazem um toque de estilo sem abrir mão da simplicidade. A modelagem ajustada ao corpo garante firmeza durante os exercícios, sem causar desconforto ou restrições. Confeccionado em malha de poliéster com elastano, o Top Basic oferece toque macio, leveza e excelente elasticidade, adaptando-se ao corpo com facilidade. Sua composição permite maior respirabilidade, tornando-o ideal para treinos intensos, caminhadas ou até mesmo para o uso no dia a dia. Combinando estilo, praticidade e funcionalidade, esse top é uma excelente escolha para quem procura uma peça versátil e confortável, pronta para acompanhar todos os tipos de movimento com segurança e discrição. Especificações Marca: Olympikus Modelo: Top Fitness Basic Gênero: Feminino Composição: 92% poliéster e 8% elastano Estilo: Esportivo discreto Detalhes: Alças finas e logo Elos ton sur ton nas costas Indicação: Treinos, academia, caminhada e uso diário Modelagem: Ajustada ao corpo Conforto: Toque macio e boa elasticidade', 99.9, 57.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sports Bras', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbnyp7hs2kkn9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F21498256684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22699057934', 'Açucareiro com Colher Break 200ml AC450 - Ou', 'Açucareiro Break 200ml - Ou O Açucareiro Break é a escolha perfeita para quem busca praticidade com elegância no servir, seja no cotidiano ou em momentos especiais. Seu design minimalista se integra harmoniosamente a qualquer estilo de cozinha, proporcionando um toque de cor e transparência que facilita a visualização dos ingredientes na mesa. A linha Break destaca-se pelos acabamentos cuidadosos. Internamente, o açucareiro possui um polimento que facilita a limpeza, enquanto externamente apresenta uma textura que reduz a visibilidade de riscos. Fabricado com base em polipropileno resistente e texturizado, e tampas e cúpulas transparentes em poliestireno, o produto combina durabilidade e estética. Cor e beleza são os pilares da linha Break, projetada para elevar a qualidade da organização da mesa no dia a dia. Especificações Marca: Ou Modelo: Açucareiro Break 200ml - Ou Medidas: 12 x 10 x 9 cm Material: PS (Poliestireno) + PP (Polipropileno) Capacidade: 200ml Peso Aproximado: 100g', 29.9, 19.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mg5i8ev5xxcf27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F22699057934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
