INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40960365016', '(Trendy) Lovito Vestido Curva Plus Size Casual Com Babados Lisos Para Mulheres LBL18844', '✅DESTAQUES -❤️Bainha Babado Babado -❤️Resistente a rugas -❤️Alça ajustável ✅DESCRIÇÕES Padrão: liso Estilo do estilo: Casual Tipo de vestido: Uma linha Tamanho Plus Tamanho: Sim Material: Poliéster Composição: 100% Poliéster Tipo de Encaixe: Encaixe Regular Folha pura: não Estica: Não estica Região de Origem: China continental ✅O pacote inclui Vestido 1X ✅Introdução LOVITO Lovito é uma marca emergente que acredita no poder da menina, comprometida em fornecer escolhas de roupas da moda e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertando, e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é autoconfiança. ✅Notas de compra Por favor consulte gentilmente sua altura e a tabela de tamanhos antes de comprar. Há uma diferença de 2-3% de acordo com a medição manual. Todas as fotos do produto desta loja são 100% reais de tiro. Devido à luz e tela diferentes, uma diferença de cor sutil e erro real é normal. Siga nossa loja e conheça novos itens e melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 78.65, 52.3, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-7rfey-m3fv7y6wjwd24e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F40960365016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
