INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15965618580', 'Carcaça Painel Completa Moto Pro Tork Yamaha YBR 125 2000 2001 2002 2003 2004 2005 Preto', 'A Pro Tork possui uma linha completa de plásticos para que você possa realizar a substituição por um excelente custo x benefício. A linha de painéis contém todos os componentes compatíveis com as principais motos do mercado brasileiro, fabricados nos moldes do original. Especificações: - Fabricada em termoplástico de alta resistência; - Resistente aos raios Ultra Violeta; - Design personalizado e mais resistente; - Mesmo molde do modelo original, não necessita adaptações; - ABS 100% virgem Aplicação: - YBR 125 2000; - YBR 125 2001; - YBR 125 2002; - YBR 125 2003; - YBR 125 2004; - YBR 125 2005. - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. - Para realizar a instalação, leve sua moto à uma oficina especializada. Nós não nos responsabilizamos por danos causados pela má instalação do produto.', 126.21, 45.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfgx3jwl0ie64a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F15965618580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
