INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9143405446', 'Lâmpada Super Led Mini Shocklight 32w S14 Nano H3 6000k', 'Descrição Lâmpada Super Led Mini S14 Nano Headlight Shocklight: Equipar o farol do carro com lâmpadas de LED é o desejo de muitos motoristas, porém nem sempre é tão simples. A maioria dos LEDs do mercado possui tamanho maior do que a lâmpada original em seu modelo de encaixe equivalente, dificultando o encaixe e a vedação do farol. A lâmpada de LED para farol ShockLight S14 Nano tem tamanho equivalente a lâmpada original, tornando simples a instalação de LED em qualquer farol. Além do tamanho, a disposição dos LEDs no corpo da lâmpada também é equivalente a posição do filamento da lâmpada halógena original, fazendo com que este lâmpada tenha um excelente foco de acordo com o projeto do farol original. Especificações técnicas: - Voltagem: DC9V-12V - Potência: 32W - Lumens: 3600LM - IP Rate: IP68 - Chip COREANO - Temperatura de Cor: 6000K - Dissipador: ALUMINIO S/COOLER - Temperatura de Operação: -40?C ~ +80?C - Feixe de Luz: 360° - VIDA ÚTIL: 30.000 HORAS Conteúdo da embalagem: - Par Lâmpadas H3 Importante: Garantia de 1 ano. Todos produtos postados em até 24h úteis! A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 82.9, 79.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/ce1bdb736efe74f642008e81b64c6b74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F9143405446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
