INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22525366342', 'Lixeira Com Tampa Basculante - Brinox Decorline 64 Litros Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! Lixeira Com Tampa Basculante Brinox Decorline 64 Litros Aço Inox Ambientes residenciais e comerciais precisam de recipientes para depositar os resíduos e, normalmente, estes objetos são super manuseados e utilizados. Por isso, a Decorline lançou uma linha de lixeiras completa: discretas e muito elegantes, resistentes, fáceis de limpar e manusear. Seu corpo em aço inox com acabamento alto brilho não apresenta porosidades, o que evita o acúmulo de resíduos e facilita a limpeza. A tampa basculante é super fácil de usar e resistente e o fundo plástico protege a lixeira e garante longa vida útil ao produto. A lixeira Decorline com tampa basculante está disponível em oito tamanhos e é perfeita para os mais diversos ambientes da sua casa ou empresa: 3,2L (ø 15,5cmx17cm), 5,4L (18,5cmx20cm), 7,8L (18,5cmx29cm), 21,2L (25cmx46cm), 28,17L (25cmx60cm), 40,5L (30cmx60cm), 47L (30cmx70cm) e 64L (35cmx70cm). Material: Aço Inox', 779.99, 585.0, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpqtpg6t9ee700', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22525366342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
