INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211234974', 'Hand Grip Agnite Ajustável 5-60kg Fitness Fortalecedor de Mãos Punho e Antebraço', 'O Hand Grip Agnite é indicado para exercícios de fortalecimento das mãos, punhos e antebraços, sendo uma opção prática para treinos de resistência muscular, condicionamento físico e atividades voltadas ao desenvolvimento da força de pegada. Possui sistema de ajuste de intensidade com variação entre 5kg e 60kg, permitindo adaptar o nível de resistência conforme a necessidade do treino. Fabricado para proporcionar praticidade durante o uso, conta com mola de resistência ajustável, estrutura desenvolvida para exercícios individuais em casa, academias, escritórios ou durante a rotina diária, e também possui contador de repetições integrado para monitorar o número de apertos. Seu formato compacto facilita o transporte e armazenamento, tornando o produto uma alternativa funcional para diferentes perfis de usuários. Indicado para exercícios de fortalecimento muscular, coordenação motora, resistência de mãos e punhos, podendo ser utilizado em rotinas esportivas, treinos funcionais e práticas de condicionamento físico. Informações técnicas: Marca: Agnite Tipo: hand grip ajustável para mãos, punhos e antebraço Resistência ajustável: 5kg a 60kg Sistema: mola regulável de tensão Contador: sim (integrado) Indicação: fortalecimento de mãos, punhos, dedos e antebraços Uso indicado: treino funcional, condicionamento físico, resistência muscular e força de pegada Características: ajustável, portátil, compacto, fácil utilização Conteúdo da embalagem: 1 Hand Grip Agnite ajustável 5kg a 60kg', 49.8, 21.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-820lr-mok5xq01zu2r4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1747380222%2F58211234974', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
