INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298716881', 'Serra Copo Aço Rápido 50mm Para Inox - TNT', 'Serra Copo HSS 50mm TNT – Alta Precisão em Perfurações Metálicas A Serra Copo HSS 50mm da TNT é a escolha ideal para cortes precisos e rápidos em metais como aço, alumínio, inox e outras superfícies metálicas. Fabricada com aço rápido (High Speed Steel), oferece excelente resistência ao desgaste e maior durabilidade em aplicações profissionais ou hobby. 🔧 Características Técnicas: Diâmetro de corte: 50 mm Material: Aço Rápido (HSS) Encaixe: Padrão para adaptadores com haste cilíndrica Profundidade de corte: até 5 mm (dependendo do material) Aplicação: perfuração em chapas metálicas, alumínio, inox, PVC e plásticos rígidos Refrigeração: uso recomendado com fluido de corte 🔨 Destaques: Cortes limpos e rápidos com acabamento profissional Ideal para uso com furadeiras manuais e de bancada Excelente custo-benefício para quem busca qualidade e desempenho 📦 Produto novo, original, pronta entrega com envio rápido.', 73.19, 48.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbsbm0l38ofb95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064710210%2F22298716881', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
