INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22422562750', 'Livro 365 cruzadas diretas - nível fácil I', 'Fazer palavras cruzadas é uma MANEIRA criativa e divertida de desenvolver o raciocínio, deixar o pensamento ágil, além de se atualizar sobre diversos assuntos e enriquecer o vocabulário. Este livro contém 365 CRUZADAS DE NÍVEL FÁCIL PARA VÁRIAS HORAS DE ENTRETENIMENTO._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Ciranda Cultural_x000D_ Idioma: Português_x000D_ Páginas: 288_x000D_ Dimensões: L 15.60 x A 23.00 x E 1.60_x000D_ ISBN: 9786526105337_x000D_ Coleção: 365 atividades_x000D_ Linha Editorial: Ativamente_x000D_ Faixa Etária: + 12 anos_x000D_ Assuntos (tags): Atividades, Raciocínio, Aprendizado, Palavras-cruzadas, Diversão, Habilidades_x000D_ BISAC: Jogos & Atividades / Desafios Mentais e de Lógica_x000D_ Linha de Produto: 365 atividades_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 13.93, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-23020-vsbj0f1hm0mv26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22422562750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
