INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261097995', 'Anel Vedação Cilindro Fechadura Tampa Traseira Fiat Strada 2008 até 2020 - Cód. 51818451', 'O anel de vedação do cilindro da chave da tampa traseira da marca Fiat é um componente essencial para garantir a segurança e a eficiência do sistema de fechamento do seu veículo. Com o código 51818451, este anel é projetado para oferecer uma vedação perfeita, evitando a entrada de sujeira, água e outras impurezas que podem comprometer o funcionamento do cilindro da chave. Fabricado com materiais de alta qualidade, o anel oferece uma durabilidade superior, resistindo ao desgaste causado por condições climáticas adversas e uso constante. A instalação correta deste componente é vital para manter a integridade do sistema de abertura e fechamento da tampa traseira, garantindo que você tenha sempre acesso seguro ao compartimento de carga. Se você busca um produto que una qualidade e performance, o anel de vedação do cilindro da chave da tampa traseira Fiat é a escolha ideal para manter seu veículo em perfeito estado.', 38.9, 36.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-823q2-mohskocfg0ztf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675755316%2F58261097995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
