INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798285644', 'Ferro a Seco Antiaderente Arno FS31Preto e Terracota 220v 1200w', 'Conheça o Ferro de passar a Seco Arno Drygliss, seu aliado para cuidar das roupas! O ferro a seco equipado com uma base anti-aderente, ele não gruda nos tecidos e possui deslizamento agradável. Sinta a potência em suas mãos, com aquecimento rápido e eficiente para uma experiência de passar roupas sem estresse. Além disso, desfrute do máximo conforto com seu design leve de apenas 0.6 Kg, cabo de 1,8 m de comprimento e rotação em 360 graus, proporcionando liberdade total de movimento. Transforme a tarefa de passar roupas em um momento mais fácil com o Arno Drygliss! Características: Marca: Arno Modelo: FS31 Cabo: 1,8m Rotação: 360 graus Dimensões: Altura: 14 cm Largura: 27 cm Profundidade: 12,2 cm Peso: 0,6 kg Garantia do Fabricante: 12 Meses', 154.6, 139.14, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/br-11134207-820m9-moip5nivvbph67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F745165277%2F18798285644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
