INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23796095926', 'Bomba De Agua Ford original motor Zetec Rocam 1.0 Ou 1.6', 'Bomba de água Motores Ford Zetec Rocan 1.0 e 1.6 original Ford. Este anúncio contém: 01 - Bomba de água. Composto por: 01 - Bomba de água; 01 - Junta de vedação. Envio imediato!!! Aplicável nos seguintes veículos: Montadora: Ford; Veículo: Courier; Motor: 1.6 8v; Ano de fabricação: 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013. Montadora: Ford; Veículo: Ecosport; Motor: 1.0 Supercharger; Ano de fabricação: 2003, 2004, 2005, 2006. Montadora: Ford; Veículo: Ecosport; Motor: 1.6 8v; Ano de fabricação: 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012. Montadora: Ford; Veículo: Fiesta; Motor: 1.0 8v, 1.6 8v; Ano de fabricação: 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014. Montadora: Ford; Veículo: Focus; Motor: 1.6 8v; Ano de fabricação: 2003, 2004, 2005, 2006, 2007, 2008, 2009. Montadora: Ford; Veículo: Ka; Motor: 1.0 8v; Ano de fabricação: 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013. Montadora: Ford; Veículo: Ka; Motor: 1.6 8v; Ano de fabricação: 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013. Outras características: Material do corpo: Metal; Material do rotor: Plástico. A nossa empresa comercializa apenas produtos originais de fabricantes certificado pelo ISO 9001. Dúvidas frequentes: Nós trabalhamos apenas com produtos novos e com garantia. Nossos produtos são de qualidade original, respeitando todas as regras do fabricante. Produto a pronta entrega. Seus produtos serão enviados em até 24 horas úteis. Sobre o produto: As bombas de água são responsáveis pela circulação do fluido refrigerante nas galerias do motor. Ao percorrer as galerias, o fluido refrigerante remove o calor e o transporta até o radiador, onde é refrigerado para poder retornar ao sistema novamente. Dicas: -Limpe as superfícies de assentamento, no bloco e na bomba. Nunca use estopa, pois solta fiapos que podem obstruir o fluxo de água. -Antes de trocar a bomba, verifique o estado do ventilador e da correia. -Nunca utilize cola, adesivo ou silicone para melhorar a vedação, isso é desnecessário e perigoso. Só a junta e/ou anel de vedação são suficientes. Sobre nossa empresa: Estamos há mais de 30 anos no mercado de autopeças, buscando sempre a satisfação dos nossos clientes. Trabalhamos com as melhores marcas do ramo automotivo e aqui você encontrará as melhores peças para seu veículo, e contará com qualidade e o melhor atendimento. Nossos produtos são todos rigorosamente conferidos e embalados para que chegue até você da melhor maneira. Trabalhamos somente com peças novas, originais ou de marcas de primeira linha.', 229.26, 229.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjbdvgi2wz5t2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F615444977%2F23796095926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259721155', 'Pepsi Cola Refrigerante', 'Refrescante e perfeito para qualquer momento, o refrigerante Pepsi Cola é um clássico! Com seu sabor único e inconfundível de cola, é ideal para acompanhar suas refeições ou para matar a sede. Produzido com água gaseificada, açúcar, cafeína e extrato de noz-de-cola.', 1.79, 1.79, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-825a1-mqnekhz75s02cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554900%2F58259721155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098522130', 'Chaleira 1,5 Litros Esmaltada De Ferro Fundido Azul Com Coador Inox Cozinha MTA - 8182', 'As chaleiras de ferro MTA são modernas e sofisticadas. Peças inteiriças em ferro fundido com aquecimento uniforme e alta durabilidade. Seu acabamento é feito artesanalmente e é isso que a diferencia de todas as outras. Inigualáveis, as chaleiras de ferro MTA são benéficas devido à maneira como absorvem uniformemente o calor e isso fortalece o sabor dos chás. São perfeitas para chás infusão e possuem filtro interno em inox. Esmaltadas com cores vivas, garantem versatilidade e beleza para sua cozinha. Um charme! Características: Marca: MTA Modelo: 8182 *Imagens meramente ilustrativas. Especificações Gerais: - Absorvem uniformemente o calor. - Fortalece o sabor do chá. - Possuem filtro interno em inox. - Esmaltadas em cores vivas. - Versatilidade e praticidade para sua cozinha. Espeficiações técnicas: - Cor: Azul. - Material: Ferro e Aço Inox. - Tamanho (AxLxC): 27x38x26cm. - Peso: 3kg. Conteúdo da Embalagem: - 1 Chaleira Esmaltada De Ferro Fundido Azul 1,5 Litros Com Coador Inox MTA - 8182', 288.42, 264.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7qvf7-lgv1tejabu68b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F21098522130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
