INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898017317', 'Livro Sunny Days - De Colorir Ciranda Cultural', 'Inspirado no sucesso dos livros de colorir PARA RELAXAR no TikTok, este livro é ideal para quem busca transformar momentos simples em uma experiência verdadeiramente calmante. Explore sua criatividade com lápis de cor ou marcadores, mergulhando em momentos de tranquilidade. Perfeito para todas as idades, este livro oferece uma maneira leve e prazerosa de aliviar o estresse e de se desconectar da correria diária. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Deto Silva_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.06_x000D_ ISBN: 9788557584846_x000D_ Coleção: Comfy & cozy books_x000D_ Linha Editorial: Ciranda Cultural - Lab_x000D_ Faixa Etária: Sem definição_x000D_ Assuntos (tags): Colorir, Atividades, Relaxar_x000D_ BISAC: Jogos & Atividades / Livros de Colorir_x000D_ Linha de Produto: Comfy & cozy books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 24.9, 11.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra0v-m58lyaar3jku3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F19898017317', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
