INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14405211766', 'Farol Gol G7 2017 2018 2019 Friso Preto Foco Simples Máscara Negra', 'Código do produto: 96958 O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente em acrílico lisa, encaixe da lâmpada H4 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Volkswagen - Gol G7 2017 - Gol G7 2018 - Gol G7 2019 Especificações Técnicas: - Máscara Negra - Foco Simples - Regulagem Manual - Encaixe da lâmpada H4 - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado é referente a unidade. A Empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 362.88, 362.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/00382638d8e07805917fde7a84bc8f45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F14405211766', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993864900', 'Tênis Feminino Slip On Kolosh C3154', 'Conheça o Tênis Feminino Slip On Kolosh C3154: o modelo que combina conforto, estilo e praticidade em um único calçado. Versátil e moderno, ele é perfeito para usar em diversas ocasiões, proporcionando leveza e bem-estar aos seus pés. Disponível em diversas cores, é a opção ideal para compor looks variados e arrasar por onde passar. Não perca mais tempo e garanta já o seu!. MODELO: 0643154 REFERENCIA: C3154 MARCA: Kolosh MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: EVA MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado DETALHES: Sola EVA FIT - Tecnologia do solado que favorece a propulsão do movimento, dando mais aderência e estabilidade. GÊNERO: Female GRUPO DE IDADE: Adult MATERIAL DO SAPATO: Malha knit ESTILO DO TÊNIS: Urbano', 203.99, 203.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7req6-m847v5tozjbl94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F23993864900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798844940', 'Acquaflora 6.1 Loiro Escuro Acinzentado - Coloração Permanente 60g', 'Acquaflora Coloração Fria que Protege, Hidrata e Valoriza a Cor Natural Garante um tom sofisticado com reflexo frio que neutraliza os indesejáveis tons quentes. Com proteína da pérola e silício orgânico, sua fórmula trata os fios enquanto colore, garantindo brilho, cobertura uniforme e toque macio. Conselho de Aplicação Para a aplicação, siga atentamente os passos descritos na bula do produto. A aplicação deverá ser feita em cabelos secos, não lavados e sem produtos finalizadores. Separar os cabelos em pequenas mechas e aplicar com o pincel por todo o comprimento e pontas, exceto nos 2cm da raiz. Deixar agir por 20 minutos. Depois aplicar na raiz e deixar agir por mais 15 minutos. Enxaguar com água em abundância para a retirada dos resíduos.', 58.7, 34.9, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-824g0-mdxfqc9w88aqfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22798844940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693497597', 'Guarda-Sol em Bagum e Haste de Alumínio Listrado 2,00m Cores Sortidas Bel', 'Proteção, conforto e estilo para seus dias ao ar livre! O Guarda-Sol Bel é a escolha ideal para garantir sombra segura e resistente em qualquer ambiente — praia, piscina, camping ou parque. Com cobertura em bagum reforçado e FPS 100, ele oferece alta proteção contra os raios solares, enquanto a haste de alumínio frisado garante leveza, durabilidade e praticidade no uso diário. ✔️ Cobertura em bagum reforçado ✔️ Haste em alumínio frisado de alta qualidade ✔️ Sistema de extra ventilação, que reduz o aquecimento interno ✔️ FPS 100 real, proteção garantida contra os raios UV Medidas: • Altura total: 2,10 m • Envergadura: 2,00 m Aproveite seus momentos ao ar livre com muito mais segurança e estilo com o Guarda-Sol Bel!', 303.93, 303.93, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mjg6uuke718gbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F23693497597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
