INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194308387', 'Farol de Neblina Milha Led Chevrolet Vectra 1996 2005 20000lm', 'Lâmpada Led Force One Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - 2 Super Led H3 - Milha - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Aplicação: Chevrolet Vectra 1996 Aplicação: Chevrolet Vectra 1997 Aplicação: Chevrolet Vectra 1998 Aplicação: Chevrolet Vectra 1999 Aplicação: Chevrolet Vectra 2000 Aplicação: Chevrolet Vectra 2001 Aplicação: Chevrolet Vectra 2002 Aplicação: Chevrolet Vectra 2003 Aplicação: Chevrolet Vectra 2004 Aplicação: Chevrolet Vectra 2005 Lâmpadas Super Led ? 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED V10* Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 49.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mdnle9nxixmhec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F22194308387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256726206', 'Kit com 5 Pacotes Compressa De Gaze Macia E Absorvente Lunis 10 Un Cada', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Kit Compressa de Gaze Lunis 10un – Macia, Estéril e Absorvente total 50 unidades, sendo 10 unidades em cada pacote unitário. Características principais: Embalagem unitária com 10 unidades Kit contém 10 pacotes de 10 unidades cada, total 50 compressa de Gaze Lunis Esterilizada com gás óxido de etileno Alta absorção e suavidade Composição 100% algodão Uso único e seguro Ideal para curativos, primeiros socorros e remoção de esmaltes Descrição detalhada:A Compressa de Gaze Lunis Macia e Absorvente oferece alta performance em cuidados com a pele. Esterilizada, proporciona maior segurança no uso médico ou domiciliar. Feita com 100% algodão, é altamente absorvente, suave ao toque e confortável, ideal para curativos, higienização e remoção de esmaltes. É um produto versátil e descartável, indicado para primeiros socorros, procedimentos estéticos e rotinas de higiene. A embalagem prática facilita a retirada da quantidade exata para uso, mantendo a integridade do restante. Indicações de uso: Curativos e coberturas de feridas Primeiros socorros Limpeza de pele ou remoção de esmaltes Procedimentos médicos leves Especificações: Marca: Lunis Tipo: Compressa de gaze Quantidade: 10 unidades Esterilização: Óxido de etileno Material: 100% algodão Uso: Único (descartável) Validade: 3 anos após fabricação Armazenamento: Local limpo, seco e arejado Confie na proteção daCompressa de Gaze Lunis kit com 50un, perfeita para cuidados delicados com higiene, curativos e primeiros socorros, com maciez e segurança!', 19.95, 19.95, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/s