INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992244748', 'Gel Fixador Ny Looks Fator 1 Incolor 240g', 'O Gel Fixador Ny Looks Média Fixação tem fórmula especial sem álcool e com o PH neutro, que proporciona melhor fixação, mais volume e brilho aos cabelos. Modo de uso: Aplique nos cabelos úmidos ou secos e modele a seu gosto.', 23.98, 23.98, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rbng-lmgkvtv7mq8p7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22992244748', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23831897037', 'Lixeira Empilhável Seletiva 45 L Orgânico Cinza Plasútil', 'Lixeira Empilhável Seletiva 45 L Orgânico Cinza Plasútil Dimensao: (Comp x Larg x Alt): 39,8 x 29,5 x 66,2 cm Capacidade: 45 L - As lixeiras empilháveis são uma excelente opção para otimizar espaço e manter os ambientes limpos e organizados. Elas possuem tampa e sobre-tampa articulada que facilita o descarte mesmo quando empilhadas. Elas são compactas e ideais para coleta seletiva (separação em orgânico e reciclável). - ECO: produto fabricado com matéria-prima 100% reciclada. Feita de materiais plásticos descartados e cuidadosamente selecionados e higienizados. - Anúncio referente ao tamanho de 45 L. O comprimento e a largura (base) das litragens fabricadas são iguais, a variação está na altura. Você pode empilhar lixeiras de tamanhos iguais (20 L e 20L, 34 L e 34 L ou 45 L e 45 L) ou diferentes (20 L, 34 L e 45 L). - Cores neutras e atemporais..', 172.9, 172.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rbnb-ln8v02cprcxh61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F23831897037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
