INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394360527', 'ÓLEO HIDRATANTE DE ROSA MOSQUETA PURO COM 30ML', '• O Segredo Natural para uma Pele Renovada: O Óleo de Rosa Mosqueta 100% Puro é um poderoso regenerador celular, rico em ácidos graxos e vitaminas, que atenua os sinais do envelhecimento e melhora a aparência da pele. • Atenua Cicatrizes e Estrias: Conhecido por sua eficácia em atenuar cicatrizes, estrias, queloides e marcas de acne, pois estimula a regeneração do tecido cutâneo. • Ação Clareadora e Antissinais: Auxilia no clareamento de manchas na pele e na suavização de rugas e linhas de expressão, promovendo uma pele mais uniforme e com mais elasticidade. • Hidratação Profunda: Ideal para peles secas e descamadas. Pode ser usado no rosto, corpo e também para fortalecer unhas e hidratar cabelos. Produto 100% puro e natural. • Palavras-chave: Óleo de Rosa Mosqueta, Puro, Regenerador, Cicatrizes, Estrias, Clareador, Antissinais.', 44.73, 44.73, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-824ha-me5temastngjb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23394360527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397880622', 'Paixão Hidratante Corporal Irresistível Com 200Ml', '• Uma Fragrância Irresistível para uma Pele Aveludada: A Loção Hidratante Paixão Irresistível combina 24 horas de hidratação com uma fragrância floral amadeirada, que desperta a sensualidade e deixa um rastro marcante. • Fragrância Marcante e Sofisticada: Uma combinação de notas florais com um fundo amadeirado, para uma perfumação que dura o dia todo. • Hidratação com Óleo de Amêndoas: Sua fórmula com Óleo de Amêndoas nutre a pele, deixando-a com um toque macio, sedoso e visivelmente mais saudável. • Rápida Absorção: Textura leve e de rápida absorção, que hidrata intensamente sem deixar a pele pegajosa. • Palavras-chave: Hidratante Corporal, Paixão, Irresistível, Óleo de Amêndoas, Perfumado, Loção, 24h.', 31.66, 31.66, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-m0eydjxyxs02a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F19397880622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292995006', 'Par Lente Farol Dianteiro Astra 2003 2004 2005 2006 2007 2008 2009 A 2012 Fumê Lente Lisa Acrílico', 'Par Lente Farol Dianteiro Astra 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 Fumê Características: Produto novo de ótima qualidade; Alta resistência e durabilidade; Feito sob medida, encaixe perfeito. Especificações técnicas: Cor: fumê; Lente lisa em acrílico resistente. Compatível com o modelo: Astra 2003 a 2012. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 164.44, 148.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lutlrmbjkx8w15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F22292995006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399364240', 'Jibbitz™ Fones de Ouvido Holográficos Único', 'Os maravilhosos Jibbitz™ Charms são acessórios que você coloca nos seus Crocs. Eles são fáceis de colocar e retirar, para que você possa mudar seus estilo a qualquer momento. Adicione os encantos dos Jibbitz™ Charms aos seus Crocs para mostrar que seu estilo e criatividade são únicos! De personagens conhecidos a emojis populares. Tem algo a dizer? Diga! Se ama alienígenas e unicórnios? Mostre! Fácil de colocar e ser removido, combina com qualquer look, companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a menores de 3 anos de idade. As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 24.99, 24.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zty-miq5ot712ygw92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F22399364240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798039670', 'Pré Tratamento Metal Detox 500ml - L''Oréal', 'Pré Tratamento Metal Detox 500ml-L''oreal Professionnel Você está comprando em uma loja Autorizada L''oréal Professionnel. Sobre o Produto: O nível de metal no cabelo varia, dependendo da porosidade do cabelo e da qualidade da água onde vivemos. Esta tecnologia patenteada é concentrada com Glicoamina 10%, uma molécula pequena o suficiente para penetrar e neutralizar o metal DENTRO da fibra. Para resultados ideais, siga com Creme de limpeza anti-metal Metal Detox, shampoo para desintoxicar o cabelo. O serviço profissional de 3 etapas no salão de beleza pro garante seus serviços de cor, mechas ou descoloração com 87% menos risco de quebra * Resultado de cor 100% confiável** Gliocomina: Modo de uso: Comece borrifando no cabelo da raíz até as pontas. Nos cabelos curtos borrife de 8 a 10 pumps; Nos cabelos médios e longos borrife de 15 a 20 pumps. Espalhe bem e penteie o cabelo para distribuir o produto em todos os fios. Deixar secar de 3 a 5 minutos e siga com o processo de coloração ou descoloração. Resultado: • Neutralizador de metal. • 87% menos risco de quebra * • Resultado de cores 100% confiável ** • A cor é homogênea, dura mais e é intensamente brilhante. * Teste instrumental: Pré-tratamento Metal Detox + serviço técnico + shampoo + máscara. ** Sem impacto no clareamento e absorção de cores otimizada. Modo de uso: Comece borrifando no cabelo da raíz até as pontas. Nos cabelos curtos borrife de 8 a 10 pumps; Nos cabelos médios e longos borrife de 15 a 20 pumps. Espalhe bem e penteie o cabelo para distribuir o produto em todos os fios. Deixar secar de 3 a 5 minutos e siga com o processo de coloração ou descoloração. Fios soltos e leves, com aspecto saudável e macio.', 549.08, 266.36, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7repr-m2vbrcj3hhuv88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23798039670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499465511', 'Jibbitz™ Miffy De Pelúcia Único', 'Os maravilhosos Jibbitz™ Charms são acessórios que você coloca nos seus Crocs. Eles são fáceis de colocar e retirar, para que você possa mudar seus estilo a qualquer momento. Adicione os encantos dos Jibbitz™ Charms aos seus Crocs para mostrar que seu estilo e criatividade são únicos! De personagens conhecidos a emojis populares. Tem algo a dizer? Diga! Se ama alienígenas e unicórnios? Mostre! Fácil de colocar e ser removido, combina com qualquer look, companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a crianças menores de 3 anos de idade As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 34.99, 34.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-823oz-mooei81mn94w27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F23499465511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27239997400', 'Kit 2 Bíblias Sagrada Tamanho Grande Capa Dura Com Harpa Palavras de Jesus em Vermelho (Kit 65)', 'Bíblia Sagrada - LETRAS GIGANTES Fonte Reduzida - Harpa Cristã - Tamanho Grande - Versão Almeida - Índice Você que ama a palavra do Senhor tem hoje a grande oportunidade de adquirir esse modelo especial de capa dura, mais barata com Letras Gigantes de Fonte Reduzida, Harpa Cristã, Tamanho Grande e muito mais, ideal para Revenda, dar de presente, fazer ações de evangelismo ou para o seu dia a dia. Essa Bíblia além de ter preço muito acessível possui diversos atrativos, como: * Possui LETRAS GIGANTES; * As Palavras Ditas por Jesus são destacadas em Vermelho (Somente no novo testamento) * Harpa Cristã; * Versão Tradicional * Antigo e novo testamento * Traduzida por : João Ferreira de Almeida * Revista e corrigida (ARC) * Editora Kings Kross * Capa Dura * Medida 14 X 21 cm', 59.99, 53.4, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdgd3az9kgcxc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F27239997400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097911380', 'Bíblia Sagrada NVI tamanho grande Capa Flexível Folha Pink', 'Bíblia Sagrada, com a versão NVI (Nova Versão Internacional). Uma das mais modernas traduções que valoriza a clareza do texto, permanecendo fiel aos Escritos originais. Proporciona ao leitor uma linguagem mais atual e fluente. Incluindo panorama bíblico, mapas e também possuí índice. O projeto de tradução para a língua portuguesa começou em 2000, a partir de uma reunião da comissão da Sociedade Bíblica Internacional. Um grupo formado por respeitados estudiosos brasileiros e de outros países foi reunido para produzi-la. Este projeto durou quase uma década. Muitos acham que é apenas uma tradução da americana, porém erram ao pensar assim, pois a versão em português foi feita no Brasil. O propósito dos idealizadores da NVI foi fazer um texto que se definisse por quatro elementos: precisão, clareza, beleza de estilo e dignidade. Com uma linguagem clara e mais próxima da atualidade, sem perder a beleza do estilo da linguagem bíblica. Cercada de elogios por conta do compromisso que conseguiu manter com os Escritos originais, esta versão da Bíblia já vendeu milhões de exemplares nos últimos anos, e vem se popularizando cada vez mais.', 47.99, 43.2, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0snl8rcwwoxc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F651108134%2F22097911380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594456206', 'Conjunto Jogo Tapete Automotivo Bandeja Borracha Para Carro BYD Dolphin Cabine Porta Malas 3D Ekap', 'Conjunto Tapete Automotivo Ekap BYD Dolphin: Proteção Completa Tipo Bandeja! 🚗🛡️ Mantenha seu BYD Dolphin sempre limpo e protegido com este conjunto de tapetes bandeja. Desenvolvido com design tipo bandeja e bordas elevadas, este tapete Ekap oferece máxima resistência e praticidade. É a escolha ideal para quem busca comodidade na limpeza, conforto e usabilidade, sendo inclusive homologado pela BYD China. 💪 Principais Características - Proteção Total Tipo Bandeja: O design com bordas elevadas evita o acúmulo de sujeira, lama e líquidos diretamente no carpete original do seu carro. 💧 - Durabilidade Extrema: Fabricado em borracha TPO flexível e de alta qualidade, é resistente ao desgaste, à água e a variações climáticas. - Fácil Limpeza: Basta remover as peças e lavar com água e sabão para mantê-las sempre como novas, economizando seu tempo. 🧼 - Aderência e Segurança: A superfície texturizada proporciona mais segurança, evitando o deslizamento dos pés durante a direção. - Encaixe Perfeito: Projetado especificamente para o BYD Dolphin, garantindo um encaixe ideal no assoalho e no porta-malas. ✅ - Produto Homologado: Qualidade verificada e aprovada pela BYD China. Apresentação e Conteúdo 🎁 - O conjunto contém 4 peças para proteção completa: - 1 Tapete para o motorista - 1 Tapete para o passageiro - 1 Tapete para os bancos traseiros - 1 Tapete para o porta-malas Especificações Técnicas 📋 - Marca: Ekap - Veículo Indicado: BYD Dolphin (Todas as versões) - Material: Borracha TPO flexível e resistente - Formato: Bandeja com bordas altas - Instalação: Encaixe simples no assoalho, sem necessidade de ferramentas - Resistência: À água, poeira, lama e produtos químicos leves - Garantia: 3 meses Dimensões de Encaixe 📏 - Tapete Traseiro: 133 cm (C) x 53 cm (A) - Tapete Passageiro: 77 cm (C) x 58 cm (A) - Tapete Motorista: 66 cm (C) x 56 cm (A) - Tapete Porta-Malas: 100 cm (C) x 62 cm (A) Adicione agora a proteção Ekap que seu BYD Dolphin merece! 🛒 ⭐ Tags #BelaMagazine #Ekap #TapeteAutomotivo #BYDDolphin #TapeteBandeja #AcessorioAutomotivo #BorrachaTPO #TapetePortaMalas', 1299.9, 1234.91, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mf8j08o4ndhpf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F22594456206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098557081', 'Cubo Roda Traseira C/ ABS Toyota Corolla Freio À Tambor (1997 - 2002) - IR18589', 'Especificações Técnicas: • Marca: IRB Automotive • Cód. OEM: 4245012030 • Posição: Roda Traseira • Para veículo com ABS: Sim • Furação: 4x100 • Dentes / Estrias: • Cód. de similares: AL-789 / C11T030 / FWB0783 / NFK8149 / VKBA 7555 Medidas: • Furo Rolamento (mm): 30 • Diâmetro Cubo (mm): 140 • Largura (mm): 108,2 Aplicações: - Toyota Corolla Freio à tambor (1997 – 2002) O Cubo de Roda IRB é fabricado em aço forjado, o que significa alta capacidade de suportar cargas pesadas em condições ambientais diversificadas. E desenvolvidos para ter uma ótima performance em qualquer território nacional! IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! A IRB projeta cubos garantindo: - Uma instalação fácil e precisa; - Maior resistência; - Melhor integridade estrutural. Não esqueça de verificar ano, modelo, as quantidades de furos, medidas e se é aplicável em veículos com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 274.9, 259.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mqbglq64dpts13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F22098557081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253957812', 'Disco E Pastilha Freio Dianteiro Corolla 2009 A 2014.', 'Caso precise confirmar se essa peça se aplica ao seu veículo, faça-nos uma pergunta abaixo mencionando o modelo, ano e motor do seu carro, se possível nos informar a placa ou chassi também para facilitar e ser mais assertivo. Peça nova a pronta entrega, com garantia e nota fiscal. Este anúncio contém: 1 (Um) Jogo de Discos de Freio Dianteiro Ventilado 1 (Um) Jogo de Pastilhas de Freio Dianteira Composto por: 2 (dois) Discos de Freio Dianteiro Ventilado 4 (Quatro) Pastilhas de freio Dianteira Aplicável nos seguintes veículos: Montadora: Toyota; Veículo: Corolla; Ano de fabricação: 2009, 2010, 2011, 2012, 2013, 2014. A nossa auto peças comercializa apenas produtos originais de fabricantes certificado pelo ISO 9001. Sobre o Produto: O disco de freio é uma peça de formato circular e achatado, que fica presa ao cubo de roda e acompanha seu movimento. Ele é responsável por promover a desaceleração e a parada do veículo por meio do atrito das pastilhas em sua superfície. Sinais que as peças estão com defeito: Procure frear sempre suave. Reduza a velocidade, por exemplo, em uma distância maior antes de chegar próximo a um obstáculo. Em descidas, deixe o carro engrenado em uma marcha adequada para manter uma velocidade constante e usar menos o sistema de freio. Sobre a Empresa: Desde 1984 buscando a satisfação de nossos clientes. Nossa autopeças trabalha com as melhores marcas do setor automotivo, e aqui você encontrará as melhores peças para seu carro, sempre visando a qualidade e o melhor atendimento, todos nossos produtos são testados e embalados de forma com que chegue até você da melhor maneira, só trabalhamos com peças novas, originais ou importadas de 1ª linha, nossas peças contam com 3 meses de garantia por defeito de fabricação seguindo nossa política de trocas, garantia e devoluções. Dúvidas frequentes: O Produto é novo? Sim. Nós trabalhamos apenas com produtos novos, e com garantia. O Produto é original? Sim. Nós só trabalhamos com distribuidores homologados pelo fabricante. Tem garantia? Sim. Todos nossos produtos têm 90 dias de garantia de fabrica contra defeitos de fabricação, exceto os amortecedores que possuem 2 anos de garantia total e embreagens 6 meses. O produto é igual ao da foto? Sim. Todas as fotos são fiéis ao que você receberá, e para facilitar a sua compra, ilustramos também o veículo em que se aplica o produto. Em quanto tempo recebo minha compra? É muito simples, basta colocar seu CEP no calculador de frete do anúncio. Envia ainda hoje? Sim. Comprando até as 12:00 postaremos no mesmo dia. IMPORTANTE: No ato da compra, caso necessário, enviaremos uma mensagem confirmando algumas informações, como: ano, modelo e motor, para evitar enganos no envio e transtornos posteriores, caso não haja a confirmação, enviaremos conforme o anúncio que a compra foi feita. Os envios são realizados de segunda a sexta-feira. Como faço para saber se o produto deste anúncio se aplica ao meu veículo? Na descrição do anúncio você encontra todas as informações das aplicações corretas, se a informação que precisa não está na descrição do anúncio, deixe sua pergunta que nossa equipe é treinada e está preparada para solucionar qualquer dúvida. Tem alguma dúvida sobre o produto ou sobre a compra? Deixe sua pergunta abaixo, que responderemos prontamente.', 544.53, 544.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mjudolotz7yead', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1485061264%2F58253957812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693731427', 'Palheta Limpador Parabrisa Original Bosch BMW Serie 3 Compact 1994 A 2000', 'Palheta Limpador Parabrisa Original Bosch BMW Serie 3 Compact 1994 A 2000 A alta performance ficou ainda melhor. Palhetas que garantem mais Eficiência, Segurança, Durabilidade e Qualidade. Se é BOSCH, pode confiar. Enxergue o que vem pela frente. Kit composto por: - 1 Palheta lado direito BOSCH Aerofit Original - 1 Palheta lado esquerdo BOSCH Aerofit Original Medidas: - Palheta motorista: 20" (50 cm) - Palheta Passageiro: 20" (50 cm) Compatível com: - BMW Serie 3 Compact 1994 A 2000 Características: - Palheta BOSCH Aerofit Original - Instalação mais fácil e segura. - Maior durabilidade e eficiência comprovadas. - Sem partes metálicas expostas. Livre de desgastes de pintura e corrosão. - Spoiler aerodinâmico para ter uma distribuição uniforme de força, mantendo a varredura eficiente mesmo em altas velocidades. - Maior estabilidade em todas as situações de uso. - Funcionamento ultra suave, devido ao seu tratamento de grafite, para um movimento sem ruídos ou trepidações. - Nova embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? - A troca deve ser realizada aos primeiros sinais de desgaste nas Palhetas. Isso porque o componente com desgaste tem a eficiência comprometida e atrapalha a visibilidade. Quais os sinais de desgaste da palheta? - Os sinais de uma Palheta com desgaste são: a Palheta não retira todo o excesso de água, faz barulho durante o funcionamento, risca o parabrisa do carro, lâmina de borracha torta, quebrada ou ressecada. Qual o prazo para a substituição das Palhetas? - Substitua as Palhetas pelo menos uma vez por ano. As Palhetas são originais? - Sim. Somos fornecedores autorizados BOSCH. Todos os produtos são originais e acompanham Nota Fiscal. Observação: - Em caso dúvidas sobre o modelo correto da Palheta para o seu carro, faça uma pergunta na parte inferior do anúncio. Temos uma equipe especializada para tirar as suas dúvidas. - O limpador de parabrisa é um acessório obrigatório por lei (artigo 230, XIX, do CTB). O não funcionamento perfeito ou mau uso do mesmo, é caracterizado como infração grave, com direito a multa e retenção do veículo. Mantenha a sua família segura. Compre Palhetas Originais BOSCH Aerofit.', 78.97, 78.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rccv-m6mythdgsj2ye9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F22693731427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993247238', 'Palheta Limpa Parabrisa Bosch Tracker 1.2 Flex 2020 A 2024', 'JOGO DE PALHETA AEROFIT MULTICLIP BOSCH 01 - Palheta Bosch lado motorista 24"/ 60CM 01 - Palheta Bosch lado passageiro 14"/ 35CM Alta Performance e Segurança Garantidas com Palhetas BOSCH Compatível com os seguintes modelos: -CHEVROLET TRACKER 1.2 FLEX 2020 A 2024 Experimente o melhor em eficiência, segurança e durabilidade com as palhetas BOSCH Aerofit Multiclip. Projetadas para proporcionar uma visibilidade clara em todas as condições climáticas, estas palhetas oferecem um desempenho superior que você pode confiar. Especificações: -Kit composto por 1 Palheta Multiclip lado direito e 1 Palheta Multiclip lado esquerdo BOSCH Aerofit Original. -Até 5 adaptadores inclusos para fácil instalação em diversos modelos de veículos. -Livre de partes metálicas expostas, evitando desgaste de pintura e corrosão. -Spoiler aerodinâmico para distribuição uniforme de força e estabilidade em altas velocidades. -Funcionamento ultra suave com tratamento de grafite, sem ruídos ou trepidações. -Embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? Troque ao primeiro sinal de desgaste para manter a visibilidade ideal. Quais os sinais de desgaste da palheta? Barulhos durante o uso, falhas na limpeza do para-brisa, entre outros. Qual o prazo para a substituição das Palhetas? Recomenda-se trocar anualmente para garantir a eficiência. Nota: As Palhetas BOSCH são originais, adquira com confiança e acompanhe com Nota Fiscal. Em caso de dúvidas sobre o modelo correto, pergunte abaixo. Garanta a segurança da sua família. Compre Palhetas Originais BOSCH Aerofit. Esse anúncio revisado foca em destacar os benefícios do produto, fornece informações claras sobre a compatibilidade com diferentes modelos de veículos e responde às perguntas frequentes dos potenciais compradores.', 138.39, 138.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-lzqd49r124vc6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F23993247238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50957324583', 'Ração Origens Raças Específicas para Cachorros Filhotes Shih Tzu e Lhasa Apso 1 kg', 'Ração Origens Raças Específicas - Shih Tzu e Lhasa Apso Filhotes (1 kg) A embalagem de 1 kg da Origens Raças Específicas para Shih Tzu e Lhasa Apso Filhotes é a escolha de alta precisão para a fase mais importante da vida do seu pet. Estes filhotes possuem um crescimento acelerado e exigem cuidados específicos com a pelagem longa e a saúde intestinal desde cedo. O formato de 1 kg garante o frescor máximo e a preservação dos nutrientes essenciais para o desenvolvimento. Este tamanho é ideal para garantir que cada grão mantenha o aroma e a crocância, facilitando a aceitação do alimento durante o período de transição e crescimento. Por que a Origens Raças Específicas Shih Tzu e Lhasa Filhotes é a escolha inteligente? Desenvolvimento Cerebral (DHA): Enriquecida com DHA, um ácido graxo essencial que auxilia na formação do cérebro e da visão, otimizando a capacidade de aprendizado do filhote. Grão Adaptado: O tamanho reduzido do grão foi desenhado para a anatomia das mandíbulas pequenas e braquicefálicas, facilitando a mastigação e promovendo a saúde oral desde os primeiros meses. Cuidado com a Pelagem e Pele: Com altos níveis de Ômegas 3 e 6, Biotina e Zinco, prepara o filhote para desenvolver uma pelagem longa, sedosa e brilhante, além de fortalecer a barreira cutânea. Suporte Imunológico: Contém um complexo de vitaminas e minerais que reforça as defesas naturais do organismo em formação, protegendo o filhote durante os primeiros meses de vida. Equilíbrio Intestinal e Redução de Odor: A combinação de prebióticos e extrato de Yucca favorece a flora intestinal benéfica, resultando em fezes mais firmes e com odor reduzido, ideal para pets que vivem em ambientes internos. Sem Corantes e Aromas Artificiais: Uma nutrição pura e focada em ingredientes de alta qualidade para garantir um crescimento saudável e natural. Dica de Conservação para 1 kg: Para preservar o DHA e o sabor que os filhotes adoram: Vedação Imediata: Após servir o filhote, retire o excesso de ar da embalagem original e feche-a com um prendedor para evitar a oxidação dos nutrientes sensíveis. Pote Hermético: Guardar o saco de 1 kg dentro de um recipiente com vedação de borracha oferece uma proteção extra contra a umidade, mantendo a crocância dos grãos. Local Fresco: Mantenha a ração em local seco e protegido da luz solar direta, garantindo que as vitaminas permaneçam 100% preservadas. Clique no botão de compra e proporcione o suporte especializado e o brilho que o seu pequeno Shih Tzu ou Lhasa Apso merece para crescer com saúde!', 38.94, 30.32, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-82632-mlxy7o1mefid82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F50957324583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593824790', 'Panela de Pressão 3 Litros Magnific Grafite Antiaderente Panelux', 'Se você procura praticidade, agilidade e facilidade está no lugar certo! Com a Panela de Pressão da Panelux sua vida vai mudar para melhor e seus alimentos vão ficar ainda mais saborosos. Feita em Alumínio Antiaderente, o que faz com que seus alimentos não grudem na panela, facilita muito mais na hora de lavar. E também oferece a vantagem de não deixar resíduos nos alimentos, pois a camada de antiaderente se sobrepõe a de alumínio. Para sua vida ficar mais fácil, você merece ter em sua casa a linha de panelas Panelux. Especificações Marca: PaneluxComposição/Material: Alumínio AntiaderenteCapacidade (l): 3LAltura aproximado (cm): 16cmCor/Acabamento: PretoUtilidade: Cozer alimentosPode ser levado(a) ao micro-ondas: SimPode ser lavado(a) na máquina de lava-louças: Sim Conteúdo da embalagem 1 Panela de Pressão 34,7x19,5cm', 130.8, 97.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-m79t2vg8y4kp50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826682830%2F22593824790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
