INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48258767571', 'Moto De Ferro Colecionável 1:64 Com 3 Tgcz007', 'A Moto de Ferro Colecionável 1:64 da Tag Toys é uma peça indispensável para os amantes de veículos em miniatura. Com um design detalhado e robusto, esta moto é feita de ferro, garantindo durabilidade e um acabamento de alta qualidade. Na escala 1:64, ela é perfeita para exibição em prateleiras ou para complementar coleções. A marca Crazy Cars traz um toque especial, tornando este modelo uma adição valiosa para qualquer entusiasta. Recomendada para crianças a partir de 3 anos, esta moto não apenas encanta os pequenos, mas também atrai colecionadores de todas as idades. A ausência de abertura de portas não diminui seu charme, pois cada detalhe foi pensado para proporcionar uma experiência visual única. Adquira a Moto de Ferro Colecionável e leve para casa um pedaço da paixão por veículos em miniatura. Ideal para presentear ou para enriquecer sua própria coleção, este modelo é uma verdadeira obra de arte sobre duas rodas.', 30.99, 30.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820lm-mn0620rvrpc081', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F48258767571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
