INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698210178', 'Chumbinho Bolt Destruição 5.5mm 125 Unidades – Technogun', 'Chumbinho Bolt Destruição 5.5mm 125 Unidades - Technogun Pensando em um bom desempenho e alto qualidade, a marca brasileira Technogun desenvolveu os Chumbinhos Bolt, que vêm se tornando referência em munição com grande poder de destruição em um único disparo. Projetado em um design diferenciado com exclusivas linhas dinâmicas para que o tiro ganhe mais poder de impacto. Fabricados para agregarem inúmeras características em uma única munição com um design inovador, os chumbinhos têm como diferencial um balanceamento centrífugo e exclusivas aerodinâmicas, dando a munição mais potência e melhor estabilidade durante a trajetória do tiro. Ele tem a ponta pontiaguda com formato aerodinâmico, ideal para quem deseja atingir com máxima precisão alvos que estão a longa distância. Especificações Fabricante: Technogun Modelo: Bolt Calibre: 5.5mm Peso: 1,11 Gramas ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 47.9, 47.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/e81d2e5a8124ba65dd6041785d81497a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F22698210178', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
