INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498692888', 'Trena Lufkin em Fibra de Vidro 20 Metros – Y1720CM', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL TRENA LUFKIN FIBRA DE VIDRO 20M Y1720CM Próprio para trabalhos de agrimensura, topografia, perícia e similares, foi desenvolvida para serviços de medição em ambientes costumeiramente adversos ao uso de fitas metálicas. Características: Design com empunhadura emborrachada em formato anatômico: facilita a locomoção e oferece maior conforto e segurança ao usuário. Acabamento HI-VIZ: fácil visualização da ferramenta no local de trabalho evitando possíveis perdas. Manivela articulada possibilita rebobinamento rápido e suave. Estojo plástico aberto: permite a lavagem e limpeza geral da fita, evitando o acúmulo de sujeira e detritos no interior do estojo. Maior durabilidade. Não condutora de eletricidade: a característica de não-condutibilidade elétrica da fita de fibra de vidro permite a utilização segura em quaisquer trabalhos em que eventuais riscos desta natureza possam existir. Estojo com ponta para maior precisão: permite o apoio da trena no local de início da medição. Gancho de fixação: medições com precisão absoluta da fita. Trenas longas são equipadas com ganchos tipo anel. Marcação em centímetros: com destaque em cada metro. Perfeita legibilidade. Especificações técnicas: Comprimento: 20 metros Largura da fita: 1/2" (13 mm) Graduação: mm Trava: não Imagens Meramente Ilustrativas - PERGUNTAS FREQUENTES - 1. O produto acompanha Nota Fiscal? R: Todos os produtos vendidos pela COMASP FERRAMENTAS acompanham Nota Fiscal. Verifique seu cadastro e endereço de entrega, antes de efetuar a compra. 2. Emitimos nota fiscal para CNPJ? R: Emitimos nota fiscal para Contribuinte e Não Contribuinte. 3. Os produtos são Novos e possuem Garantia? R: Todos os produtos são novos e possuem garantia por parte do Fabricante.', 119.0, 105.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyg-mbqo1lw1y5gab5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F22498692888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998268069', 'BOMBA DE GRAXA PNEUMÁTICA BREMEN 8971 - 200KG | 10M DE MANGUEIRA | ALTA PRESSÃO', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL 🚀 BOMBA DE GRAXA PNEUMÁTICA BREMEN 8971 - 200KG | 10M DE MANGUEIRA | ALTA PRESSÃO 400 BAR 🔥 IDEAL PARA OFICINAS, INDÚSTRIAS E AGRICULTURA! ✅ DESEMPENHO PROFISSIONAL: ✔ Vazão ultrarrápida: 850 g/min – lubrifique com agilidade! ✔ Pressão poderosa: 400 bar (5800 psi) para sistemas exigentes. ✔ Mangueira longa: 10 metros de alcance – maior praticidade! ✔ Tambor compatível: Projetada para tambores de 200 kg – economia em larga escala. ✔ Consumo eficiente: Apenas 7 pcm de ar comprimido – reduz custos operacionais! 📦 KIT COMPLETO (TUDO QUE VOCÊ RECEBE): 1 Bomba de Graxa Pneumática Bremen 8971 Mangueira reforçada de 10 metros (1/4” NPT) Conexões rápidas de 1/4” para ar e graxa **⚙️ ONDE USAR? ✔ Oficinas mecânicas ✔ Frotas de caminhões ✔ Máquinas agrícolas ✔ Indústrias pesadas **💡 POR QUE ESSA BOMBA É PERFEITA PARA VOCÊ? Durabilidade extrema: Resistente ao uso intensivo! Precisão alemã: Razão de compressão 50:1 para aplicações impecáveis. Facilidade de uso: Conexões rápidas e design intuitivo. ⏳ NÃO PERCA TEMPO! Garanta já a sua e evite desperdícios com bombas de baixa qualidade! **🛒 COMPRE AGORA E TENHA: Nota fiscal inclusa (todo legalizado!) Frete rápido para todo o Brasil Pagamento seguro: À vista, PIX, cartão (até 12x) ou boleto! 🔧 Sua lubrificação nunca mais será a mesma! Clique em “COMPRAR” e leve eficiência profissional para seu negócio! 🏆 VENDIDO POR COMASP FERRAMENTAS – Qualidade garantida, satisfação ou seu dinheiro de volta! ✋ ESTOQUE LIMITADO! Não deixe seu equipamento parado – adquira já a sua Bremen 8971! 🚛💨', 3398.0, 2200.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134