INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498736470', 'Kit Babador Papi Felpudo Estampa Menina - 03 Peças', 'Kit Babador Papi Felpudo Estampado – 03 Peças O Kit Babador Papi Felpudo é ideal para proteger a roupinha do bebê com muito mais charme e praticidade nas refeições. Confeccionado em tecido 100% algodão, ele é super macio e confortável, perfeito para a pele delicada do bebê. Com estampas divertidas e delicadas, este kit é indispensável no dia a dia dos pequenos, ajudando a manter tudo limpo e organizado. Principais Características: • Contém 03 babadores felpudos estampados • Tamanho aproximado: 25 cm x 19 cm • Tecido 100% algodão – toque suave e confortável • Estampas sortidas para meninas– fofas e divertidas • Alta absorção – ideal para proteger durante mamadas e refeições • Prático e fácil de lavar • Perfeito para uso diário – em casa, passeios ou creche Informações Adicionais: Cores: Sortidas Referência:938-143 Marca:Papi', 19.9, 19.9, NULL, 'Mom & Baby > Feeding Essentials > Bibs', 'https://cf.shopee.com.br/file/br-11134201-820ma-mqxv3uhwd62s4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23498736470', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198260990', 'Casaco Bebê Din Don Em Pelo Fleece Com Botões', 'Casaco Bebê Din Don Em Pelo Fleece Com Botões O Casaco Din Don é ideal para aquecer as meninas de 3 a 12 meses com muito conforto e estilo. Confeccionado em pelo fleece de alta qualidade, o casaco é supermacio e proporciona o aconchego necessário para os dias mais frios. Com um design prático, possui fechamento por botões que facilita na hora de vestir, proporcionando mais segurança e agilidade no dia a dia. Este casaco combina proteção e delicadeza, tornando-o perfeito para manter a bebê aquecida enquanto explora o mundo com estilo e charme. Para criar um look completo, combine o casaco com uma calça de moletom e um body de manga longa, criando uma camada extra de proteção contra o frio. Meias quentinhas e um gorro em tons combinando são ideais para dar um toque especial ao visual, deixando a bebê pronta para qualquer passeio. Este casaco Din Don é a peça essencial para o guarda-roupa de inverno, garantindo que sua pequena esteja confortável e protegida sem abrir mão do estilo. Informações Adicionais: Tamanho: P ao G Cores: Bege/Rosa Referência: 8520000095 Marca: Din Don', 71.8, 71.8, NULL, 'Baby & Kids Fashion > Baby Clothes > Winter Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-7rau7-mb2qxxcy0vvm45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F19198260990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
