INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899840653', 'Alicate Para Anéis Jogo 4 Peças 165mm E 178mm Vonder', 'O jogo de alicates para anéis com 4 peças da VONDER é indicado para uso profissional na instalação e remoção de anéis de retenção internos e externos com diâmetro de 18 mm a 63 mm. Ideal para oficinas mecânicas, manutenção industrial e reparos automotivos, garante precisão e praticidade no manuseio. Fabricados em aço cromo vanádio com acabamento niquelado, os alicates oferecem alta resistência e durabilidade. O kit conta com modelos retos e curvos, com cabos plastificados que proporcionam conforto e segurança durante o uso prolongado. Características: Modelo: 3662004007 Referência: 3662004007 Massa aproximada (peso): 0,75 kg Tipo do cabo do alicate.: Cabo plastificado Material do corpo do alicate: Aço cromo vanádio Acabamento: Niquelado Tamanho: 6.1/2" Benefícios: Jogo completo com 4 modelos para aplicações variadas Aço cromo vanádio de alta resistência e longa vida útil Cabos plastificados que oferecem mais conforto e firmeza Modelos retos e curvos para anéis internos e externos Ideal para uso profissional com precisão e segurança Conteúdo da embalagem: Contém 1 jogo com 4 peças, sendo: 1 alicate para anéis internos, reto, 7" - 178 mm, diâmetro de aplicação: 18 mm a 63 mm; 1 alicate para anéis internos, curvo, 6.1/2" - 165 mm, diâmetro de aplicação: 18 mm a 63 mm; 1 alicate para anéis externos, reto, 7" - 178 mm, diâmetro de aplicação: 18 mm 63 mm; 1 alicate para anéis externos, curvo, 6.1/2" - 165 mm, diâmetro de aplicação: 18 mm a 63 mm', 177.92, 130.57, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-md1vqwkldc6e90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F21899840653', NULL, NULL, '2026-07-28T