INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43678024351', 'Registro de Pressão para Chuveiro 3/4 + Acabamento em Metal', 'O KIT COMPLETO QUE SEU BANHEIRO MERECE: BASE + ACABAMENTO EM METAL 🛁 Chega de comprar peças separadas! Leve a solução definitiva para o seu chuveiro com máxima qualidade e preço justo. Este kit une a robustez do nosso Registro de Pressão 3/4" com a sofisticação do Acabamento em Metal Cromado. POR QUE ESTE É O MELHOR KIT DO MERCADO? 💎 Acabamento 100% Metal: Diferente das opções de plástico (ABS) do mercado, nosso acabamento é feito em metal de alta qualidade. Não descasca com o tempo. Não oxida/enferruja. Mantém o brilho espelhado por anos. 🛠️ Registro de Pressão Robusto (3/4"): Segurança: Fabricado em Ligas de Cobre (Bronze e Latão), suporta altas temperaturas e pressão sem vazar. Controle Preciso: Mecanismo projetado para um ajuste fino da vazão, garantindo o banho perfeito. Versatilidade: Funciona perfeitamente em baixa pressão (casas térreas) ou alta pressão (prédios), de 2 a 40 MCA. FICHA TÉCNICA: Bitola: 3/4" (Padrão para chuveiros). Material do Registro: Liga de Cobre e Elastômeros. Material do Acabamento: Metal Cromado de Alta Resistência. Instalação: Embutida (Parede). Padrão: Deca 16 estrias. O QUE VEM NA CAIXA? 01 Registro de Pressão 3/4". 01 Acabamento em Metal Completo (Canopla Abs + Volante/Alavanca Metal). Parafusos e acessórios de fixação. Invista na segurança da sua obra e na beleza do seu banheiro.', 159.98, 99.99, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-820l4-mmungevmoi681d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450610050%2F43678024351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093724907', 'Volante Caminhão Worker Direção 13180 15180', 'Oferecemos durabilidade e resistência incomparáveis. Nossos volantes foram projetaods para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Volkswagen Delivery 5.140/8.150/9.150/6.90 • Volkswagen Titan 18.310/Tractor/17.180 • Volkswagen Worker 8.120/10.160/13.180/15.180/16.200/24.220 EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 243.71, 197.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-820m1-mpautn5ewr9cf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F23093724907', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499299114', 'Kit 10 Cuecas Zorba Boxer Algodão Max 702', 'DESCRIÇÃO: Kit com 10 Cuecas Zorba Boxer Algodão Max. 100% Algodão. Possui a tecnologia Go Tagless, sem etiquetas costuradas, não arranha e não irrita a pele. Veste do P ao XGG. Cueca com a tecnologia Maxfresh: Regula a sensação térmica. Protege contra odores e bactérias. Tecnologia Seamless: Sem costura nas laterais. Ajuste perfeito ao corpo. COMPOSIÇÃO: 100% algodão. | Mescla: 88% Algodão, 12% Poliéster PAÍS DE ORIGEM: Brasil. INSTRUÇÕES DE LAVAGEM: Temperatura máxima de lavagem 30ºC; processo suave; não alvejar; não secar em tambor; secagem em varal por gotejamento a sombra; temperatura máxima da base do ferro a 110ºC sem vapor; não limpar a seco. INDICAÇÃO: Dia a dia. CONTÉM: 01 kit com 10 unidades. TABELA DE MEDIDAS: P – 38 ao 40 - Cintura entre 76 e 80 cm M – 42 ao 44 - Cintura entre 84 e 88 cm G – 46 ao 48 - Cintura entre 92 e 96 cm GG – 50 ao 52 - Cintura entre 100 e 104 cm XG – 54 ao 56 - Cintura entre 108 e 112 cm XGG – 58 ao 60 - Cintura entre 116 e 120 cm Caso sua medida esteja no intervalo das medidas entre um tamanho e outro, considerar o tamanho maior.', 294.9, 294.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mg6oxhc70vtaef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733918049%2F19499299114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
