INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19936467278', 'Garrafão Térmico 5 Litros Camping Pesca Obras Construção Mantém Quente Gelado Profissional Termolar', 'COMERCIAL VIPASA DISTRIBUIDORA ATENÇÃO MODELOS DIFERENTE DAS GARRAFAS, ESTÁ ESPECIFICADA NAS VARIAÇÃO. GARRAFA: PRETA MARCA SOPRANO. GARRAFAS: CINZA, VERMELHO,AZUL. MARCA: TREMOLAR Garrafão Térmico 5 Litros Camping Pesca Obras Construção Mantém Quente Gelado Profissional Termolar Garrafão Térmico 5L Camping Pesca Obras Construção Mantém Quente Ou Gelado Profissional Termolar Garrafão Térmico 5 Litros Camping Pesca Obras Construção Mantém Quente Ou Gelado Garrafao Termico 5 Litros Termolar Quente Frio Alta Conservacao Com Alca E Tampa Copo O garrafão térmico 5 litros Termolar e ideal para quem precisa armazenar líquidos quentes ou frios por longos períodos, oferecendo praticidade, resistência e excelente desempenho térmico. Indicado para uso domestico, comercial ou em atividades externas, ele combina grande capacidade com um design funcional e fácil de transportar. Fabricado com material externo em polipropileno de alta resistência, o produto garante durabilidade e maior vida util. Seu acabamento fosco ajuda a evitar marcas e facilita a limpeza no dia a dia. Internamente, conta com ampola de vidro que proporciona maior eficiência na conservação térmica, mantendo bebidas quentes por ate 6 horas e frias por ate 12 horas. O sistema de isolamento térmico foi desenvolvido para manter a temperatura interna por mais tempo, sendo ideal para café, chá, agua, sucos e outras bebidas. Possui tampa com vedação segura que evita vazamentos, além de funcionar como copo, trazendo mais praticidade no uso. Conta ainda com bico dosador que facilita o controle do fluxo ao servir, evitando desperdícios e respingos. A alça integrada e ergonômica proporciona conforto no transporte, mesmo com o garrafão cheio. Características do produto Capacidade de 5 litros ideal para grandes volumes Material externo em polipropileno resistente Ampola interna de vidro com alta eficiência térmica Mantem líquidos quentes por ate 6 horas Mantem líquidos frios por ate 12 horas Tampa rosque Avel com vedação e função copo Bico dosador pratico e funcional Alca resistente para transporte fácil Design compacto e fácil de armazenar Dimensões e peso Altura aproximada 43 cm Diâmetro aproximado 21 cm Peso aproximado 1,5 kg vazio COMERCIAL VIPASA DISTRIBUIDORA.', 59.99, 57.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-820ls-mozkoxs7hptv40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F19936467278', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
