INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899761273', 'Cabo USB-C 1,2m PVC Preto Intelbras EUCC 12PP', 'O cabo USB tipo C EUCC 12PP permite a conexão de seus dispositivos para alimentação de energia e transferência de dados. Projetado e testado para garantir o melhor desempenho e durabilidade, tem 1,2 m de comprimento para oferecer maior comodidade no uso com smartphones, tablets, computadores, fones de ouvido sem fio, controles de videogame e outros dispositivos compatíveis. Principais Funcionalidades • Conexão para Carregamento e Transferência de Dados - O cabo USB tipo C EUCC 12PP permite carregar seus dispositivos e sincronizar dados com eficiência, sendo compatível com uma ampla gama de eletrônicos modernos. • Transferência de Dados Eficiente - Com taxa de transferência de até 480 Mbps, o cabo assegura movimentação ágil de arquivos como fotos, vídeos e documentos entre dispositivos compatíveis. • Comprimento Ideal para o Dia a Dia - Com 1,2 metro de comprimento, proporciona mais liberdade de uso, seja na mesa, no sofá ou no carro — sem limitar o alcance entre o dispositivo e a fonte de energia. • Durabilidade com Revestimento Emborrachado - Possui revestimento emborrachado, que oferece maior resistência e vida útil prolongada, suportando o uso contínuo e o desgaste diário.', 31.9, 28.71, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/sg-11134201-82586-mqricec0g3yad4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859766415%2F20899761273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
