INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594529461', 'Melatonina Fast Gotas - 30ml Menta - Equaliv', 'Melatonina Fast Equaliv é um suplemento alimentar formulado com melatonina semelhante à produzida naturalmente pelo organismo. Sua apresentação sublingual permite absorção imediata e ação mais eficiente do que cápsulas tradicionais. Essa tecnologia garante atuação rápida, promovendo um sono mais profundo, contínuo e reparador, além de proporcionar bem-estar e disposição ao acordar. Ideal para quem sofre de insônia, sono leve, alterações no relógio biológico ou dificuldade para adormecer, a Melatonina Fast Equaliv contribui para noites tranquilas e despertares revigorantes. Como Tomar Ingerir uma gota por dia, na hora de dormir, ou conforme orientação médica. USO ADULTO. Ingredientes Melatonina, agente de massa (glicerina), aromatizante (aroma natural de menta) e acidulante (ácido cítrico). Não contém glúten. Não contém alergênicos. ...', 39.7, 39.7, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mfx2cx4324un9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F23594529461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
