INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29639474837', 'Chinelo Rider R1 Prime Masculino - Verde e Preto', 'Conforto para as horas livres e de lazer. O Chinelo Rider R1 Prime Masculino é aliado do seu bem-estar no dia a dia. Em modelagem macia e resistente, este chinelo de dedo masculino conta com tiras largas para proporcionar maior comodidade. O mix de cores garante um visual estiloso para acompanhar suas combinações. ÓTima pedida para usar com camiseta estampada ou regata e bermuda masculina. Peça o seu!', 69.9, 59.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-md0a8kt7p0jk4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F29639474837', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898083032', 'Tênis Olympikus Volcan 2 Masculino - Preto e Dourado', 'Prepare-se para elevar sua performance com o Tênis Olympikus Volcan 2 Masculino! Com design moderno e tecnologia de ponta, este tênis masculino oferece conforto e amortecimento médio, ideal para corrida e academia. Desenvolvido com materiais sustentáveis, ele pesa apenas 250g, garantindo leveza e respirabilidade. A espuma EVASense proporciona flexibilidade, enquanto a placa de estabilização oferece suporte em corridas de curta e média distância. Invista no seu desempenho com Olympikus Volcan 2! Garanta já o seu!', 289.9, 249.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rfgy-m3weoyvn7ug720', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F22898083032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999596652', 'Kit C/2 Hidratante Facial Antiacne + Antissinais Garnier', 'Hidratante Facial Antiacne Garnier Salicílico Toque Seco O Hidratante Facial Antiacne Garnier Salicílico Toque Seco é um hidratante facial com textura diferenciada, idealizado para atender às necessidades específicas das peles mistas e oleosas. Seu objetivo principal é hidratar profundamente enquanto reduz significativamente a produção excessiva de óleo na pele. Além disso, atua como um agente antiacne eficaz ao minimizar a aparência dos poros obstruídos, prevenindo o surgimento de cravos e espinhas. Quais os Benefícios do Salicílico Toque Seco? - Controle da Oleosidade; - Combate à Acne; - Uniformização da Pele; - Hidratação leve de até 8 horas de toque seco sem deixar resíduo ou sensação pegajosa; - Textura Inovadora: Não é gel nem creme; - Proporciona uma experiência sensorial única elogiada por 90% das usuárias que afirmaram ser a melhor textura já experimentada. Ativos: Com fórmula enriquecida em Ácido Salicílico, ajuda a regular a produção sebácea. Reduz visivelmente as imperfeições causadas pela acne graças à ação combinada do Ácido Salicílico com Niacinamida. A presença da Vitamina C contribui para um tom mais homogêneo, suavizando manchas escuras. Modo de Uso: 1. Limpe bem o rosto antes da aplicação. 2. Aplique uma quantidade adequada do produto sobre toda a face evitando região dos olhos. 3. Utilize diariamente preferencialmente duas vezes ao dia (manhã e noite) após lavar o rosto ou conforme orientação dermatológica. 4. Experimente usá-lo sob maquiagem - ele age também como primer devido seu efeito matificante prolongado. Hidratante Facial Antissinais Garnier Colágeno Toque Seco O Garnier Hidratante Colágeno Toque Seco Antissinais foi desenvolvido especialmente para quem busca uma solução eficaz na rotina de cuidados com a pele. Este hidratante facial possui uma textura revolucionária, ideal para peles mistas e oleosas, proporcionando hidratação intensa sem deixar a sensação de peso ou brilho excessivo. Formulado com poderosos ativos como Colágeno, Niacinamida e Vitamina C, ele atua diretamente no aumento da firmeza e elasticidade da pele enquanto uniformiza o tom e controla a oleosidade ao longo do dia. Quais os Benefícios do Hidratante Facial Antissinais Garnier Colágeno Toque Seco? - Fórmula enriquecida proporciona até 8 horas de toque seco; - Garante uma pele livre de oleosidade indesejada durante todo o dia; - Auxilia na redução das linhas finas de expressão graças à sua capacidade antissinais extraordinária; - 90% das usuárias consideraram essa textura como a melhor já experimentada; - 85% sentiram maior firmeza em suas peles após o uso contínuo; - 83% notaram uma visível minimização nas linhas faciais. Modo de Uso: 1. Aplique o Garnier Hidratante Colágeno Toque Seco Antissinais sobre o rosto limpo pela manhã ou noite — conforme preferir! 2. Espalhe gentilmente pelo rosto inteiro até completa absorção, sempre em movimentos ascendentes suaves (de baixo para cima). 3. A aplicação pode ser feita antes da maquiagem ou protetor solar.', 79.99, 79.99, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rbmj-m5ek0bnkcnl757', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F21999596652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
