INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997812729', 'Copo Patrulha Canina 280 ml Sortido 1 Peça Plasútil', 'Copo Patrulha Canina 280 ml Sortido 1 Peça Plasútil Dimensao: (Diâmetro x Alt): 7,8x10,3 cm Capacidade: 280,0 ml - *ATENÇÃO* - Esse anúncio corresponde ao envio de uma unidade. Esse copo possui 4 decorações diferentes (como mostra a foto principal). Não é possível escolher a arte. O envio é feito de forma aleatória. - Se a Patrulha Canina está no caso, podemos ficar tranquilos: o problema será resolvido! Ryder, Chase, Rubble, Rocky, Marshall, Zuma e Skye estão aqui para trazer muita diversão aos momentos com a criançada. - Os copos de 280 ml são decorados com os personagens preferidos da criançada e com isso, são ótimos aliados na hora da hidratação nas refeições. - Ótima opção para lembrancinha de aniversário ou festas temáticas. - Fabricado em plástico polipropileno (PP). Atóxico e livre de bisfenol-A (BPA FREE). - Pode ser levado ao micro-ondas e freezer. - Decoração injetada no plástico, não adesivada: segurança aos pequenos..', 16.9, 16.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rdy1-m0bsa5xyx94q86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F19997812729', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
