INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693085461', 'MACARRÃO LA MOLISANA 66 FARFALLE RIGATE 500G', 'VOCÊ ESTÁ COMPRANDO: MACARRÃO LA MOLISANA 66 FARFALLE RIGATE 500G PAIS DE ORIGEM: ITÁLIA SOBRE O PRODUTO: O Macarrão Farfalle Rigate da La Molisana é de tamanho robusto, com asas grandes e proporcionais e um pequeno sulco que torna não só bonito de se olhar, mas também extraordinariamente saboroso. O clássico Borboleta foi remodelado para ser ainda mais bonito de ver e bom de provar. Reduziu-se seu tamanho para torná-lo delicioso no prato e, graças ao desenho de bronze, adquiriu uma textura áspera e porosa. Para prepará-los da melhor forma, pode-se fazer uma receita com banha de colonnata, creme de couve preta com sabor de laranja ou creme de nabo e sementes de gergelim torradas e crocantes.', 37.9, 37.9, NULL, 'Food & Beverages > Food Staples > Pasta', 'https://cf.shopee.com.br/file/sg-11134201-7rd4t-lw7jcgr2pxdy5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F23693085461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
