INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898037252', 'Filtro de Ar Nc 750 Xa / Nc 750 Dx 2021-2022 / X-Adv 750 Hiflo', 'Filtro de Ar Hiflo Filtro de Ar Hiflo filtro de alto padrão, desenvolvido com elementos filtrantes que superam características técnicas exigidas pelos fabricantes de motocicletas. Elementos com multifibras, microfibra, papel e algodão cirúrgico em estrutura de ABS com reforço metálico contra sucção e controle de fluxo. Compatível com HONDA: NC750 XA-M,N 2021 NC750 XA-M,N 2022 NC750 XD-M,N DCT 2023 NC750 XD-M,N DCT 2021 NC750 XD-M,N DCT 2022 NC750 XD-P DCT 2023 NSS750 M Forza DCT 2021 NSS750 M Forza DCT 2022 NSS750 P Forza DCT 2023 X-ADV 750 ADV750 M 2021 X-ADV 750 ADV750 M 2022 X-ADV 750 ADV750 P 2023 X-ADV 750 ADV750 R 2024 X-ADV 750 ADV750 R 2025 Conteúdo da Embalagem: 01 Filtro de Ar Hiflo *HFA1717 Código Original (OEM) Honda: 17210-MKT-D00 Especificações Técnicas: - Filtro Seco - Rígido - Proporciona Melhor Queima de Combustível e Ajuda a Diminuir a Emissão de Gases Poluentes - Oferece Menor Desgaste dos Componentes Internos do Motor - Maior Durabilidade e Qualidade de Filtração - Filtro de alto padrão desenvolvido com elementos filtrantes que equivalem as características técnicas exigidas pelos fabricantes de motocicletas - Fluxo de ar: Compatível com a especificação do fabricante - Não Lavável Os filtros de ar Hiflofiltro são fabricados para se adaptarem à caixa de ar de fábrica e são uma substituição direta para filtros de equipamento original. Filtrante de fluxo de energia de alta qualidade, desenvolvido para motores modernos de alto desempenho. Importante !! Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 354.9, 219.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-m6soe8kiw4dd36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F19898037252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41820141180', 'Kit Pastilhas de Freio P/ Triumph Tiger 800 (Pinça Brembo) + Pastilhas Diafrag', 'Kit Pastilhas de Freio Dianteiras - Diafrag Dura Tech ( Semimetálica ) Pastilha da melhor qualidade para frenagem da sua moto, testado e aprovado por laboratórios de qualidade! Não vai te deixar sem freio! ** Pastilhas Chanfradas A função do chanfro e corte nas pastilhas de freios são uma maneira de evitar superaquecimento deste componente, proporcionando uma melhor refrigeração e saída do pó da pastilha, assim evitando ruídos e vedrificamento da pastilha. Aplicação Dianteira TRIUMPH: TIGER 800 2018 TIGER 800 2019 TIGER 800 2020 TIGER 800 2021 ** NÃO SERVE EM PINÇAS NISSIN ** P/ PINÇAS BREMBO (COM OU SEM ABS) SERVE EM TODOS OS MODELOS! XC / XR / XRX / XCX / XCA Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Dianteira (Lado Direito) Diafrag Dura Tech (Semimetálica) 01 Par de Pastilhas de Freio Dianteira (Lado Esquerdo) Diafrag Dura Tech (Semimetálica) 01 Par de Pastilhas de Freio Traseira Diafrag Dura Tech (Semimetálica) Especificações Técnicas: - Modelo: DURA TECH SEMIMETÁLICA - Material: ferro / lona - Produzido com melhores equipamentos garantindo segurança e durabilidade. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. - Possui medidas originais - Melhor dissipação de calor e atrito com o disco de freio - Ideal Para Reposição - Maior segurança ao motociclista - Alta Qualidade E Resistência A Dia-Frag possui ampla know-how na fabricação de alumínio, materiais de fricção e borracha, e se destaca entre a tecnologia de ponta e as modernas instalações fabris com máquinas de precisão, laboratórios de ensaios, metrologia e equipamentos de precisão. Possui certificados de qualidade nacionais e internacionais. Isso mostra que todos os produtos são produzidos de acordo com as mais rígidas normas técnicas de fabricação e controle de qualidade. Especialmente projetada para motocicletas a partir de 500 CC, que exigem um melhor poder de frenagem devido as altas temperaturas, com menor desgaste das pastilhas e dos discos de freios Importante !! Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto. Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 149.9, 119.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-825b9-meufjatmzev94b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F41820141180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
