INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393587831', 'Porta Acessórios Multiuso - Jacki Design', 'Porta Escova de Dentes Jacki Design – Praticidade e Higiene em Qualquer Lugar! Mantenha sua escova e pasta de dentes sempre protegidas com o Porta Escova de Dentes Jacki Design! Feito com material resistente e design moderno, ele é ideal para organizar seus itens de higiene pessoal com praticidade e estilo. Perfeito para levar em viagens, passeios ou para a escola, o estojo protege sua escova contra sujeira e umidade, aumentando sua durabilidade e mantendo tudo limpo e seguro. Além disso, há espaço ideal para escova, pasta e até uma pequena toalha, garantindo tudo o que você precisa em um só lugar! ✨ Dica: Conheça também os outros produtos da Coleção JÚNIOR e monte seu kit completo de higiene! 📏 Medidas: Comprimento: 6 cm | Largura: 6 cm | Altura: 19 cm', 27.9, 19.8, NULL, 'Home & Living > Bathrooms > Toothbrush Holders & Toothpaste Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-7rfgj-m3qql4o3edqzeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F23393587831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20798103739', 'Kit Teclado Mouse sem Fio Membrana Knup KP-TE137', 'Teclado e Mouse sem Fio – Conforto e Tecnologia em um Só Conjunto O teclado sem fio Knup KP-TE137 une praticidade, desempenho e design moderno para tornar sua experiência no dia a dia muito mais eficiente. Conta com 12 teclas multimídia e 6 teclas com tecnologia anti-ghosting, garantindo respostas rápidas e precisas em todas as suas tarefas. Com padrão brasileiro ABNT e conexão sem fio de 2.4GHz, oferece liberdade total de movimento, além de um toque silencioso para maior conforto durante o uso. O mouse, equipado com o sensor Pixart 3065, possui design ambidestro – ideal para destros e canhotos – e um estilo minimalista com tampa superior magnética. Além disso, oferece DPI ajustável (800/1.200/1.600) para você adaptar a sensibilidade conforme sua necessidade. Alimentação por Pilhas Tanto o teclado quanto o mouse funcionam com pilhas (não recarregáveis). Para sua comodidade, o conjunto já acompanha as pilhas necessárias para começar a usar imediatamente após a compra. Especificações Técnicas Teclado: - Modelo: KP-TE137 - Conexão sem fio 2.4GHz - Padrão Brasileiro ABNT - Teclas silenciosas - 12 teclas multimídia - 6 teclas com tecnologia anti-ghosting - Alimentação: Pilhas (inclusas) Mouse: - Sensor Pixart 3065 - Conexão sem fio 2.4GHz - Design ambidestro - DPI ajustável: 800 / 1.200 / 1.600 - Tampa superior magnética - Silencioso e minimalista - Alimentação: Pilhas (inclusas) Conteúdo da Embalagem - 1 Teclado sem fio Knup KP-TE137 - 1 Mouse sem fio Knup KP-TE137 - Pilhas para teclado e mouse (não recarregáveis)', 175.56, 133.09, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-m7w7nykdl9kw01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F20798103739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498709781', 'Jogo Stop Tapple Caça Palavras Responda Rápido em Português Grande', 'Em 10s grite UHHH STOP! Descubra o Jogo Stop Tapple Caça Palavras, uma experiência divertida e envolvente para toda a família. Este jogo de tabuleiro clássico é ideal para estimular a mente e promover a interação entre os jogadores. Com um formato físico, ele é perfeito para reunir amigos e familiares em momentos de descontração. Com capacidade para até 5 jogadores, o Jogo Stop Tapple é acessível para grupos pequenos ou grandes. É recomendado para crianças a partir de 4 anos, tornando-se uma excelente opção para festas de aniversário ou encontros familiares. A dinâmica do jogo incentiva a rapidez e a estratégia, desafiando os participantes a pensar de forma criativa. Os componentes do jogo incluem um tabuleiro que facilita a jogabilidade e torna a experiência ainda mais envolvente. O jogo é apresentado em português. Prepare-se para horas de entretenimento e risadas com o Jogo Stop Tapple Caça Palavras.', 159.9, 49.9, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/br-11134207-820md-mmgv9c9yduysf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438068303%2F22498709781', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
