INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29684639240', 'Coleira Antipulgas e Carrapatos Para Cães Dug’s World 56cm', '- Indicado para cães; - Combate e controle da infestação de pulgas e carrapatos; - Proteção por até 3 meses. A Coleira Antipulgas e Carrapatos Dug''s World é um antiparasitário eficaz para cães, indicada para o combate e controle de infestações por pulgas (Ctenocephalides felis) e carrapatos (Rhipicephalus sanguineus). Ela utiliza DDVP (Diclorvós) como princípio ativo, que é misturado durante a produção, garantindo uma coleira homogênea, sem odor e que não tem textura pegajosa. A duração da proteção é de até 3 meses. Medidas aproximadas Comprimento: 56cm Modo de usar Aplicar ao redor do pescoço do animal, deixando dois dedos de folga; cortar o excesso; retirar antes do banho e recolocar após. Dica: evitar contato com olhos, mucosas e ferimentos; lavar as mãos após manuseio. Composição Cada 100g contém DDVP Diclóvos ...................................... 10g Excipiente q.s.p .................................... 100g', 27.5, 16.89, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7renp-m8xn891whuhd25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F29684639240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52756793773', 'Petisco Cachorro Traqueia Bovina para Cães Mordedor para Cachorro Premium 2 Unidades 13cm Brupet', 'A Traqueia Bovina 5 polegadas aproximadamente 13 cm Brupet Super Premium com 2 Unidades é um petisco natural ideal para recompensas mais controladas e práticas no dia a dia. Desidratada e altamente atrativa, oferece sabor intenso e textura firme, estimulando a mastigação e mantendo o seu cão entretido de forma saudável. Com tamanho aproximado de 13 cm, é uma excelente opção para cães de pequeno e médio porte, podendo também ser oferecida para portes maiores como recompensa rápida. A embalagem com 2 unidades garante praticidade e melhor controle de consumo, sempre devendo ser oferecida sob supervisão do tutor. Produto natural e super premium, desenvolvido para complementar a alimentação do seu cão com responsabilidade. Não substitui a ração, mas agrega variedade, estímulo e prazer à rotina alimentar, mantendo o padrão de qualidade Brupet. Perguntas Frequentes É um produto natural? Sim, é uma traqueia bovina desidratada, mantendo características naturais que aumentam a atratividade. Serve para cães pequenos? Sim, o tamanho aproximado de 13 cm é ideal para cães de pequeno e médio porte. Pode oferecer todos os dias? Pode ser oferecida como complemento alimentar, sempre sob supervisão e respeitando a quantidade adequada para o porte do seu cão.', 20.08, 14.9, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mli4kidqcykgec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1194006916%2F52756793773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
