INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197925191', 'Sofá 3 Lugares Living com Chaise Esquerdo Pé Palito Linho Cotton Bege', 'Que tal o Sofá com Chaise Living?O Sofá com Chaise Living te oferece aquilo que tanto procurando: sofisticação, qualidade e beleza em um único produto. Confeccionado com materiais de ótima qualidade, ele possui sua estrutura em Eucalipto, com percintas elásticas italianas, camadas de espuma D-28, D28 Soft e manta acrílica, o que tornará o seu descanso muito mais prazeroso. Tudo isso revestido pelo tecido Linho rústico, de textura macia, resistente e maleável. Os pés palito remetem aos móveis retrôs, estilo que está super na moda. Espaçoso, comporta até 2 pessoas e ele ainda conta com chaise, para você esticar as pernas e descansar. Charmoso, não é mesmo? Perfeito para você que gosta de decorar o lar com muita elegância e conforto. Aproveite! Cor: Bege Garantia em Meses: 3 Cores do Produto: Marrom Claro Conteúdo da Embalagem: 1 Sofá - Entregue em: 2 Volumes. Modelo: Com Chaise Número de Volumes: 2 Material: Estrutura em madeira de reflorestamento, assentos com percintas elásticas e molas bonnel. Espumação do assento com espuma D28. Espumação do encosto com espuma D26.Acabamento em Linho Cotton. Material para Filtro: Algodão Descrição do Tamanho: Altura: 76 cm | Largura: 200 cm | Profundidade: 82 cm/Chaise Profundidade 160 cm Altura do Produto (cm): 76 Largura do Produto (cm): 200 Comprimento do Produto (cm): 160 Peso do Produto (Kg): 47 Produto precisa de Montagem?: Sim, instalação dos pés Sofá-Cama: 0 Número de Lugares: 3 lugares Tipo de Encosto: Fixo Controle Remoto: 0 Desmontável: 0 Quantidade de Peças: 1 Tipo de pé: Fixo Altura do assento até o chão (cm): 43 Linha de produtos: Living Acompanha banco/puff: Não É giratório: Não Material da estrutura: Madeira de Reflorestamento Material do enchimento do assento: Espuma D28 Material do enchimento do encosto: Espuma D26 Material do Revestimento: Linho Possui Baú?: Não Tipo de assento: Fixo Material dos pés: Madeira PROFUNDIDADE x LARGURA x ALTURA: 160 x 200 x 76 Fornecedor: Lidiane M. T. A. Batista - ME É sofá-cama: Não É com chaise: Não Tipo de produto: Sofá É de canto: Não Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Is Fragile: Não Número da peça: Não Produto: Sofá Quantidade de lugares: 3 Tipo do Sofá: null Inclui manual de montagem: Não', 2229.96, 1705.47, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rcct-m6e7zbd9evfe0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F20197925191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256153607', 'KIT REPARO ALTO FALANTE TARAMPS 7DRIVER MH 380 8 POLEGADAS ORIGINAL', 'Utilizados na manutenção de alto falantes danificados, os kits de reparo são procurados quando ocorre queima da bobina ou algum tipo de dano no cone do alto falante. O kit reparo possibilita efetuar o reparo do alto, evitando assim a necessidade de compra de um novo alto falante. Especificações do Kit Reparo Alto Falante Taramps 7Driver MH 380 8 polegadas Original: Produto original Taramps 7Driver; Reparo para woofer com bobina queimada ou cone danificado; Fácil substituição; Acompanha cola; Acabamento central original; Encaixe perfeito; Kit Reparo Alto Falante Taramps 7Driver MH 380 8 polegadas Original Composto por: - 1 Cone com bobina; - 1 Acabamento central; - 1 Jogo de guarnição; - 1 Cola; *Por se tratar de um reparo, o mesmo só terá garantia caso a substituição seja realizada em uma autorizada da marca; *Somente a autorizada que fez a substituição poderá acionar garantia do fabricante caso o mesmo apresente defeito; *Não será aceita a devolução de reparo já instalado no alto falante; *A resistência da bobina deve ser aferida antes da instalação; *Não se responsabilizamos por instalação mal realizada; *A impedância do reparo deve ser a mesma do alto falante, caso contrário não será compatível; *Este reparo é específico para o modelo anunciado, não é compatível com outro alto falante; *É de responsabilidade do profissional que fará a substituição garantir que a bobina fique centralizada livre de contato com o GAP; *Não se responsabilizamos por mau uso do produto (Ex: Queima da bobina ou cordoalha, centragem ou borda cortada, cone dobrado ou cortado na base da bobina); *Só aceite receber a mercadoria após verificar se a mesma coincide com a que consta no pedido e se está em perfeito estado; *Em caso de duvidas utilize o campo de perguntas antes de fazer o pedido;', 229.99, 229.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mldmqw7luoen52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F58256153607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
