INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200719205', 'CAPACETE MOTO NORISK ORION SV FREE WHT / ORANGE', 'Agora com óculos internos e um novo design mais aerodinâmico, o ORION SV é inspirado nos modelos italianos, apresentando linhas limpas e modernas. Seu casco é injetado em resina termoplástica ABS sob alta pressão, garantindo leveza e resistência. A ventilação é um dos pontos fortes do capacete, com entradas que proporcionam conforto durante o uso. Além disso, o ORION SV conta com tecido respirável, e sua forração é hipoalergênica, removível e lavável. •Descrição Técnica: •Óculos solar interno •Casco em resina termoplástica ABS •Viseira de 2mm com proteção UV, resistente a riscos •Forração em tecido tecnológico, hipoalérgico, removível e lavável •Peso: 1210g (+- 50g) •Cinta jugular com sistema de engate micrométrico •Um excelente equilíbrio entre estilo e funcionalidade! Ideal para quem busca conforto e segurança para o dia a dia!', 659.9, 659.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-821fp-mh7xyzb249osbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F58200719205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
