INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44324148671', 'Cafeteira Elétrica 0,6 L 15 Xícaras Compacta Premiun 220V', 'Desfrute de um café fresco, saboroso e pronto em minutos com a Cafeteira Elétrica Unitermi 0,6L. Compacta, moderna e funcional, é perfeita para quem busca praticidade no dia a dia sem abrir mão do sabor. Com potência de 750W e tensão de 220V, garante aquecimento rápido e preparo eficiente. Seu design elegante na cor preta combina com qualquer ambiente, enquanto o jarro de vidro resistente permite acompanhar o preparo e manter o café sempre na temperatura ideal. O sistema corta-pingo permite servir o café mesmo durante o preparo, e a base com aquecimento contínuo mantém a bebida quente por mais tempo — ideal para o uso em casa ou no escritório. Características Principais Modelo: CAE-UNI-P-B-0,6L-220 Capacidade: 0,6 Litros (15 xícaras de 40ml) Potência: 750W Tensão: 220V | Frequência: 50~60Hz | Corrente: 2.72A Material: Aço inoxidável, vidro e plástico injetado (PP) Peso: 1,11 kg Dimensões: 21,9 x 16,7 x 27 cm (A x L x P) Destaques do Produto Sistema corta-pingo: sirva o café mesmo durante o preparo. Base aquecedora: mantém o café quente por mais tempo. Design compacto e moderno: ideal para qualquer ambiente. Jarro de vidro resistente: praticidade e durabilidade no dia a dia. Leve a Cafeteira Elétrica Unitermi 0,6L para a sua rotina e tenha sempre um café quente, saboroso e na medida certa!', 139.9, 109.9, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mftspajb8hz46b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323288678%2F44324148671', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
