INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598856392', 'Tapete Onix Emborrachado 2013 2014 2015 2016 2017 2018', 'Nossos tapetes automotivos foram desenvolvidos para oferecer máxima proteção e durabilidade ao interior do seu veículo. Fabricados em borracha de alta qualidade, são impermeáveis, resistentes e de fácil limpeza, garantindo conforto, segurança e um visual renovado para quem deseja transformar cada viagem em um momento especial — sem preocupações com sujeira ou desgaste. CONTEÚDO DA EMBALAGEM: • Jogo com 4 tapetes automotivos emborrachados; • Tapetes dianteiros antiderrapantes; • Tapetes traseiros projetados para encaixe perfeito; • Design exclusivo com acabamento reforçado. COMPATIBILIDADES: • Modelos universais compatíveis com a maioria dos veículos populares e utilitários; • Para dúvidas sobre encaixe, consulte nossa equipe de atendimento. EXCLUSIVIDADE • Produzidos em borracha de alta resistência, garantindo proteção contra água, lama, poeira e líquidos; • Fácil higienização: basta lavar com água e sabão, sem perda de qualidade; • Superfície antiderrapante para maior segurança durante a condução; • Design moderno que valoriza o interior do veículo. IMPORTANTE • Entrega rápida: comprando hoje, seu produto será enviado no próximo dia útil; • Instalação simples, sem necessidade de ferramentas ou adaptações. Confiar em nossos tapetes automotivos é garantir proteção, praticidade e estilo em cada viagem.', 112.49, 89.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-824i7-me4dbrdl5nnk7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F23598856392', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699090439', 'Coleção Minha Primeira Biblioteca Trilíngue - Números', 'Desperte a curiosidade dos pequenos exploradores com a coleção "Minha Primeira Biblioteca". Neste livro, eles mergulharão em uma divertida jornada trilíngue, explorando o mundo das frutas e vegetais em português, inglês e espanhol. Uma experiência educativa que não só enriquece o vocabulário, mas também nutre o amor pela leitura desde os primeiros passos.', 19.9, 14.95, NULL, 'Books & Magazines > Books > Language Learning & Dictionaries', 'https://cf.shopee.com.br/file/sg-11134201-7rbmu-locuywgsrlj5e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F20699090439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
