INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397988940', 'Jogo 2 Pneus Michelin Aro 17 Primacy 4+ 225/50R17 98Y XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Michelin A marca Michelin foi fundada em 1889 em Clermont-Ferrand, França e com o passar dos anos tornou-se uma referência em pneus. Produz atualmente pneus para carros, motos, suvs, caminhonetes e muito mais. Os pneus Michelin se consagraram no mercado graças à excelente aderência, durabilidade e conforto. Hoje são utilizados como pneu original de fábrica por diversas montadoras de automóveis, desde carros compactos até superesportivos de alta potência, que precisam de toda a tecnologia dos pneus Michelin para obter os melhores resultados nas pistas.', 1865.22, 1865.22, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfhr-m32a3x66dhkpa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F19397988940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
