INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797984152', 'Shake Proteico para Emagrecer Sabor Chocolate ao Leite HND 450g', 'Descubra o Sabor e os Benefícios do Shake H-Control Sabor Chocolate ao Leite HND 450g Introduzindo o Shake H-Control Sabor Chocolate ao Leite HND, sua nova escolha inteligente para gerenciar o peso de forma deliciosa e saudável. Com 450g, este produto da renomada linha Hinode é perfeito para quem busca não apenas uma alternativa prática para refeições rápidas, mas também uma forma eficaz de manter ou reduzir o peso sem sacrificar o sabor. Enriquecido com uma rica composição de vitaminas e minerais, e formulado com baixo teor de gorduras, proteínas e fibras, este shake é a combinação ideal de nutrição e sabor. Cada porção foi cuidadosamente balanceada para oferecer os nutrientes essenciais que seu corpo precisa, com a vantagem de ter baixas calorias. Desfrute de uma experiência gastronômica deliciosa enquanto alcança seus objetivos de saúde e bem-estar. Características Sabor: Chocolate ao Leite Peso: 450g, projetado para oferecer 15 porções Composição: Rico em vitaminas, minerais, proteínas, fibras e baixo teor de gorduras Benefícios Controle de Peso: Ideal para a perda ou manutenção de peso como substituto de refeições Nutrição: Equilibra nutrientes essenciais, melhorando a saúde e energia Praticidade: Solução rápida e fácil para refeições nutritivas em estilos de vida agitados Diferenciais Baixas Calorias: Formulado para ser uma refeição nutritiva com menos calorias Versatilidade: Perfeito para qualquer refeição, fácil de preparar e personalizar com outros ingredientes saudáveis Complemento: Enriqueça seu shake com frutas e outros ingredientes para uma refeição mais completa Recomendações Para resultados otimizados no controle de peso, combine o uso do Shake H-Control com uma dieta equilibrada e exercícios regulares. Consulte um profissional de saúde antes de iniciar qualquer novo plano alimentar. Experimente o Shake H-Control Sabor Chocolate ao Leite HND e transforme sua dieta com saúde e sabor!', 149.9, 149.9, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/sg-11134201-7repa-m2gqlbk01rh24c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F876865394%2F21797984152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093675501', 'Ômega 3 Epa 660mg Dha 440mg + Vitamina E 60 Caps Bodyaction', 'ÔMEGA 3 INGREDIENTES: Óleo de peixe e Vitamina E (acetato de DL-Alfa-Tocoferol). INGREDIENTES DA CÁPSULA: Gelatina, água purificada e umectante glicerina. NÃO CONTÉM GLÚTEN. ALÉRGICOS: CONTÊM PEIXES. SUGESTÃO DE USO: Ingerir 02 (duas) cápsulas por via oral ao dia do suplemento alimentar. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: "ESTE PRODUTO NÃO É UM MEDICAMENTO." "NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM." "MANTENHA FORA DO ALCANCE DE CRIANÇAS." CONSERVAÇÃO: Manter em sua embalagem original, em temperatura ambiente. Proteger da luz e manter em lugar seco. Preservar a integridade da embalagem. Depois de aberto, consumir preferencialmente em 60 dias.', 124.88, 79.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5d1dmn56coi3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024736570%2F22093675501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
