INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097085690', 'CAPACETE MOTO FW3 GTX FOX AMARELO AZUL (C/ OCULOS) N 60', 'Capacete com Viseira Modelo GTX FOX - FW3 Com design esportivo e diferenciado, o capacete FW3 é perfeito para todos os motociclistas. Leve, estiloso e confortável, este moderno capacete vem com entrada e saída de ar, é fabricado em ABS super resistente e possui certificado de segurança. O melhor para você motociclista andar por aí com muita segurança, conforto e estilo! Capacetes da FW3 são projetados para lhe oferecer uma experiência inesquecível em cada um dos seus trajetos. Seus capacetes possuem uma estrutura compacta e se adapta perfeitamente ao condutor, preservando ao máximo sua segurança e garantindo trajetos confortáveis e divertidos. Maior conforto e segurança no seu andar! *ANTES DE EFETUAR SUA COMPRA, SELECIONE COR E TAMANHO DESEJADO.* Cores Disponíveis: - Amarelo com Azul; - Rosa; - Azul Tifanny com Rosa; - Grafite; - Dourado; - Laranja. Tamanhos Disponíveis: - 56 (Medidas da cabeça entre 55-56 cm); - 58 (Medidas da cabeça entre 57-58 cm); - 60 (Medidas da cabeça entre 59-60 cm); Características: - Modelo GTX FOX; - Casco em ABS; - Viseira transparente de policarbonato 2,0 mm, podendo ser removida; - Forração em camurça Jet Black 6 mm (Removível); - Entrada e saída de ar; - Narigueira; - Reparo com trava de viseira; - Selo Inmetro; Conteúdo da Embalagem: - 01 Capacete Modelo GTX FOX - FW3. IMPORTANTE: * Postagem em até 24h * Entrega Garantida * Produtos Originais e Certificados * COMPRE COM SEGURANÇA * Tire suas dúvidas via chat com nossos especialistas. AMARELO/AZUL (C/ OCULOS) N 56', 556.19, 556.19, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugsu78e4fxe94', 'https://shope.ee/an_redir?origin_li