INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13783572048', 'Livro Aquabook Patrulha Canina - Diversão com os filhotes', 'Entre um resgate e outro, os filhotes da Patrulha Canina sempre encontram tempo para se divertir. Neste livro, você vai descobrir os passatempos dessa turma ao pintar cada cena com a caneta especial e responder desafios animais!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2019_x000D_ Autor: Ciranda Cultural_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 13.80 x A 24.00 x E 2.00_x000D_ ISBN: 9788538077817_x000D_ Coleção: Colorindo com água_x000D_ Linha Editorial: Ciranda Cultural - Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Cores, Pintura, Água, Diversão, Cachorro, Patrulha Canina, Colorir, Criatividade_x000D_ BISAC: Não Ficção Infantil / Mídia Tie-in_x000D_ Linha de Produto: Aquabook_x000D_ Encadernação: Espiral_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 29.9, 29.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rccy-lstxv1daamun8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F13783572048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697608800', 'Livro O Pequeno Príncipe - Diversão Colorida', 'Este kit de atividades com livro, lápis de cor, borracha, apontador e adesivos é incrível para vocês e divertir. Pinte os desenhos, brinque e aprenda com diversas atividades de O Pequeno Príncipe e deixe sua criatividade despertar!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Ciranda Cultural_x000D_ Idioma: Português_x000D_ Páginas: 24_x000D_ Dimensões: L 27.00 x A 22.00 x E 1.90_x000D_ ISBN: 9788538095750_x000D_ Coleção: Diversão colorida_x000D_ Linha Editorial: Ciranda Cultural - Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Colorir, Atividades, Desenho animado, Príncipe_x000D_ BISAC: Não Ficção Infantil / Mídia Tie-in_x000D_ Linha de Produto: Kit escolar - apontador_x000D_ Encadernação: Brochura_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Papel', 29.9, 29.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmf-lq96884k0i7af8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F18697608800', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899660944', 'Amend Expertise KIT Complete Repair Shampoo e Condicionador 250ml + Fluído Multi-Benefícios 180ml', 'KIT Amend Expertise Complete Repair – Shampoo 250ml + Condicionador 250ml + Fluído Multibenefícios 180ml Reconstrua e proteja seus cabelos com este kit completo da linha Amend Expertise Complete Repair! Este kit exclusivo oferece um tratamento profundo para cabelos danificados, promovendo reconstrução capilar, hidratação intensa e proteção contra danos futuros. Composto por: - Shampoo Reconstrutor 250ml – Limpa suavemente enquanto repara e fortalece os fios com Bio-Amino Reconstrutores. - Condicionador Reconstrutor 250ml – Hidrata, desembaraça e reduz o frizz, garantindo cabelos sedosos e protegidos. - Fluído Multibenefícios 180ml – Finalizador poderoso que repara pontas duplas, protege do calor, reduz o frizz e prolonga a cor dos cabelos. Benefícios principais: - Reconstrução capilar profunda - Hidratação intensa e ação antifrizz - Proteção térmica contra secador/chapinha - Recuperação da elasticidade e brilho natural - Facilidade no pentear e secagem rápida Modo de Uso: - Lave os cabelos com o Shampoo Reconstrutor e enxágue. - Aplique o Condicionador nos fios úmidos, evitando a raiz, e enxágue bem. - Com os fios úmidos ou secos, aplique o Fluído Multibenefícios no comprimento e pontas. Não é necessário enxaguar. Garanta já o seu KIT Amend Expertise Complete Repair e conquiste cabelos mais fortes, brilhantes e protegidos!', 195.8, 155.65, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7jgmfozlcne22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1077804858%2F18899660944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097788355', 'Kit Perfurador de solo a gasolina 52cc com 3 brocas 80x10cm, 80x15cm, 80x20cm e 2 extensor 80cm Marca Tssaper', 'NESTE KIT VOCÊ ESTARÁ ADQUIRINDO: 1 MOTOR PERFURADOR DE SOLO A GASOLINA 52CC TSSAPER 1 BROCA 80X10CM 1 BROCA 80X15 CM 1 BROCA 80X20CM 2 EXTENSOR 80cm DE BRINDE Perfurador de Solo a Gasolina 52CC 80cm 1,57kw com Alça Dupla modelo PS52CC da Tssaper O Perfurador de Solo a Gasolina 52cc da Tssaper é uma máquina compacta e de fácil manuseio. Utilizada para estaqueamentos na construção civil, em piezometrias, amostragem de solo, construção de cercas e reflorestamento, pode realizar perfurações na vertical, horizontal e em ângulos para casos especiais. Permite furar qualquer tipo de solo, menos uma camada contínua de pedra; O perfurador de solo PS52CC da Tssaper tem uma broca de 80cm altura por 20cm de largura e amortecedor para dar total conforto e segurança durante sua utilização. O uso deste equipamento em comparação com perfuradores manuais e cavadeiras articuladas garante muita economia de tempo, eficiência no resultado do trabalho e mais segurança e comodidade para o profissional, sem contar com a diminuição de danos à saúde causados pelo esforço repetitivo, manuseando o aparelho. A produtividade e o ganho de tempo obtido com a aquisição desse equipamento também são celebrados com um ótimo investimento financeiro. Ao contrário do que muitos imaginam, o Perfurador de Solo da Tssaper tem outras importantes utilidades além da perfuração para colocação de estacas em cercas, já que o uso também é indicado para ajudar no plantio e replantio de mudas de reflorestamento de pinus e eucaliptos, em trabalhos e prestações de serviço na construção civil, e ainda na silvicultura (como coleta de materiais para análise de solo). Muito duráveis e potentes, os perfuradores desenvolvidos pela Tssaper ganham destaque através de suas brocas resistentes, portabilidade e facilidade de uso. Assim como outros produtos da empresa, é um equipamento simples de usar, fácil de carregar e muito eficiente. Características: - Fácil manuseio; - Perfeita para utilização construção civil; - Realiza perfurações na vertical e horizontal, e em alguns casos, outros ângulos específicos; - Perfura qualquer tipo de solo; - Manejo duplo. Especificações: - Peso total aproximado: 13,6kg; - Peso aproximado do motor: 9,73kg; - Peso aproximado da broca: 3,87kg; - Dimensões aproximadas da broca: 80cm x 20 cm; - Dimensões aproximadas da broca: 80cm x 10 cm; - Dimensões aproximadas da broca: 80cm x 15 cm; - Dimensão do extensor: 80cm - Dimensões aproximadas do motor: 43cm x 38cm x 33cm; - Cilindradas: 52CC; - Diâmetro aproximado das brocas: 10cm; 15cm; 20cm; - Rotação máxima: 12.000RPM; - Potência máxima: 1.57KW (2,17CV); - Tanque do Combustível: 1,2 Litros; - Combustível: gasolina comum + óleo de motor de 2 tempos na proporção 25:1; - Partida: Manual Retrátil leve (Easy Starter); - Modelo: PS522C; - Marca: Tssaper. Itens inclusos: 01 Motor Perfurador de Solo a Gasolina 52CC da Tssaper completo; 01 Broca 80cm x 10cm; 01 Broca 80cm x 15cm; 01 Broca 80cm x 20cm; 02 Extensor de 80 cm 01 Kit de peças e ferramentas; 01 Galão medidor de combustível; 01 Manual. Garantia de 6 meses.', 1629.0, 847.08, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meszj6u68a9u10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F709990445%2F20097788355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697182843', 'Livro Literatura infantil Quem é o monstro?', 'Quem está sujando nosso planeta? Será que a garrafa de plástico é o monstro que sozinho polui as cidades e as praias e envenena pessoas, plantas e animais? Somos nós quem precisamos prestar atenção ao que descartamos como lixo. Reciclar é tão importante e tão fácil de fazer que as próprias crianças podem ensinar aos adultos como separar o lixo em casa e na escola e assim reduzir a poluição e proteger o planeta, afinal ele é a nossa casa._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2023_x000D_ Autor: Mônica Ribeiro do Carmo, Clarice Alphen_x000D_ Ilustrador: Chris Eich_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 20.50 x A 27.50 x E 0.40_x000D_ ISBN: 9786553841901_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Lixo, Reciclagem, Mar, Vida Marinha, ODS 12 - Consumo e produção responsáveis, ODS 13 - Ação contra a mudança global do clima, Planeta_x000D_ BISAC: Literatura Infantil / Natureza & Mundo Natural / Meio Ambiente_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lpffm6b0gz3968', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22697182843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297607315', 'Argola Feminina de Prata 925 Triângulo 30mm', 'Argola Feminina de Prata 925 Triângulo 30mm A Argola Feminina de Prata 925 Triângulo 30mm é uma peça elegante e moderna que realça o estilo com seu design triangular. Com 30mm de tamanho e pesando 1.5g, essa argola adiciona um toque único à sua coleção de joias. Especificações: Tamanho: 30mm Peso: 1.5g Material: Prata 925 Design Triangular Moderno Com o seu fio triangular, esta argola combina elegância e modernidade. Seja para ocasiões casuais ou eventos especiais, esta peça é uma escolha versátil que complementa diversos looks. Descubra Mais na Aqua Joias Explore nossa coleção completa de argolas de Prata 925 e descubra peças exclusivas que refletem a sua personalidade. Na Aqua Joias, garantimos qualidade e estilo em cada detalhe.', 54.9, 42.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/sg-11134201-7rdxj-m03ig1cq6w4ubb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F19297607315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
