INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097083072', 'Corrente de Ouro Branco 18k - 750 Piastrine 1,2mm 45cm', 'Corrente de Ouro Branco 18k - 750 Piastrine 1,2mm 45cm Eleve seu estilo com esta deslumbrante Corrente de Ouro Branco 18k - 750 Piastrine 1,2mm 45cm. Um acessório atemporal que complementa qualquer look e é perfeito para acomodar um pingente de ouro. Detalhes do Produto Material: Ouro Branco 18k - 750 Modelo: Piastrine 1,2mm Comprimento: 45cm Peso: 1,40 gramas O Que é Ouro Branco? O Ouro Branco é uma liga metálica que combina ouro puro com metais brancos, como paládio, prata ou níquel, resultando em uma cor prateada e brilho distintos. O ouro 18k é composto por 75% de ouro puro, tornando esta corrente de ouro uma escolha durável e elegante. - Oferecemos frete grátis e enviamos para todo o Brasil com envio imediato. - Acompanha Caixinha de Joias e sacola Personalizada da Aqua Joias para presentear.', 2805.0, 1799.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9j94l0smmgp1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23097083072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399325415', 'Refil de Atualização #1 - Fichário de Lei Seca Rideel – Monte & Remonte - 2ª Edição (Capa Preta)', 'Coord.: Ricardo Baronovsky, Coorganizadores: Luiz Antônio, Ralpho Waldo de Barros Monteiro Filho e Rodrigo Francisconi Costa Pardal Refil de Atualização #1 – 2ª edição Atualizações do dia 06/05/2022 a 22/09/2022. Agora você poderá substituir suas páginas que sofreram atualizações e manter o seu Fichário (2ª edição - Capa Preta) sempre atualizado. Sua nova maneira de estudar nunca foi tão divertida! IMPORTANTE: Esse refil não acompanha o Fichário de Lei Seca Rideel – 2ª edição.', 99.9, 99.9, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-7rdw0-lxmj4nq48zt484', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F20399325415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593731889', 'Bala Gelatina Fini Ursinhos 250G', 'Ursinhos Fini, um clássico da marca. Docinhos, coloridos e saborosos, possuem formato de urso e são ricos em cada detalhe. No pacote contém ursinhos nas cores vermelho, laranja, amarelo, verde e azul, nos sabores de laranja, maçã verde, morango, framboesa e maracujá. Pacote com 250g de produto, ideal para dividir com os amigos, E perfeito para usar em decorações de mesas de festas e pratos de confeitaria, tornando tudo mais colorido, com um toque único e especial! Ingredientes: XAROPE DE GLICOSE, AÇÚCAR, ÁGUA, GELATINA, ÓLEO VEGETAL DE PALMA, ACIDULANTES ÁCIDO CÍTRICO E ÁCIDO LÁCTICO, GLACEANTES CERA DE CARNAÚBA E CERA DE ABELHA, AROMATIZANTES, ANTIOXIDANTE: LACTATO DE SÓDIO, CORANTES TARTRAZINA, VERMELHO 40, AMARELO CREPÚSCULO FCF E AZUL BRILHANTE FCF. NÃO CONTÉM GLÚTEN.', 24.33, 24.33, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-7rceg-m6n4sstbhxnef0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F23593731889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793688571', 'Condicionador Metais Militec 200ml', 'Descrição Geral: O Militec 200ml É Um Aditivo Sintético De Alta Performance Recomendado Para Motores A Gasolina, Álcool, Flex E Gnv. Características: Condicionador De Metais De Alto Desempenho. Desenvolvido Com Alta Tecnologia Para Maior Resistência E Proteção Do Motor. Modo De Aplicação: Para Motores (gasolina, Flex, Gnv E Diesel): Adicione 200ml Para Até 4 Litros De Óleo Lubrificante. Pode Ser Usado Com Qualquer Tipo De Óleo (mineral, Semissintético Ou Sintético). Proteção Garantida Por Até 20.000 Km. Em Condições Severas De Uso, Recomenda-se Reduzir O Período De Aplicação Pela Metade. Benefícios: Aumenta A Durabilidade E A Eficiência Do Motor. Ideal Para Quem Busca Alta Performance E Proteção. MILITEC 1 é o primeiro e melhor condicionador de metais do mundo, que protege o seu motor de verdade. Fabricado nos Estados Unidos com um processo único e tecnologia exclusiva, MILITEC 1 garante a proteção contra os desgastes tanto no dia a dia quanto nas condições mais críticas de uso e performance. Cerca de 80% do desgaste do motor acontece na partida a frio devido à falta de lubrificação momentânea. Nesse momento MILITEC 1 garante a proteção das peças pois o produto já está adsorvido no metal. Ao ser aplicado, MILITEC 1 impregna nas superfícies metálicas em atrito do motor. Essa exclusiva tecnologia Dry Impregnated Lubrication, reduz o atrito em até 85% e deixa os metais até 17 vezes mais resistentes. • Valor unitário • Produto novo e original • Envio do pedido com Nota Fiscal • Com garantia de fábrica • Imagem meramente ilustrativa • Antes de efetuar o pedido favor tirar as dúvidas no campo de perguntas Cuidar do seu carro de maneira preventiva gera economia e acima de tudo garante sua segurança para dirigir tranquilo. A Nova Via trabalha para oferecer melhor em autopeças, com um estoque de mais de vinte mil itens para que você encontre sempre o que precisar. Distribuímos autopeças das maiores e melhores marcas do mercado, com um atendimento qualificado de profissionais que atuam há mais de vinte anos no segmento. Nova Via Autopeças: sempre o melhor para seu carro!', 105.79, 100.51, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-m5ylky4t5qbk9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F714090968%2F23793688571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
