INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21741114462', 'Protetor de Respingos T-Racer T-150', 'O acessório T-Racer T-150 é utilizado na lavadora Kächer para evitar respingos na área de atuação. Possui dois jatos de alta pressão que giram em alta velocidade debaixo de seu protetor, sem espalhar para os demais locais. Proporciona uma limpeza mais rápida e eficiente das superfícies sem aquela "nuvem de respingos". Dispositivo anti-respingo, que além de proteger o usuário, parede e móveis contra os respingos, facilita a limpeza e proporciona mais agilidade. Além disso, você ainda pode acessar locais mais altos e fachadas em geral. Maior praticidade para você! - Ideal para limpeza em áreas internas, cantos e locais com móveis, equipamentos e decorações que não podem ser molhados. - Compatível com todas as lavadoras de alta pressão da linha residencial Kärcher. *Não acompanha prolongador', 299.9, 254.92, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zur-mikgkiagag3laa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F848951954%2F21741114462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899677872', 'Jogo de 6 Pratos Fundos 20,5 cm Oxford Unni Tropicano', 'Trazendo a vibração e a exuberância das paisagens tropicais, a decoração Tropicano traz o tucano em destaque em meio a folhagens fluídas estampando os pratos de formato minimalista do modelo Unni. Os pratos têm o acabamento de granilha e filete na borda de cada peça. O conjunto é a escolha perfeita para quem valoriza beleza natural, funcionalidade e um toque de sofisticação tropical. Conteúdo da embalagem: 06 Pratos Fundos 20,5 cm (diâmetro). - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Material: Cerâmica - Cor: Multicor - Forma: Redondo - Decoração: Estampado - Formato de venda: Conjunto - Modelo: Unni Tropicano - Tipo da embalagem: Papelão pardo - Utilizações seguras: Resistente a micro-ondas e lava-louças - Unidades por kit: 6 - Tipo de prato de louça: Fundo - Diâmetro: 20,5 cm - Condição do item: Novo - É apto para lava-louças: Sim - É kit: Sim - Linha: Tropicano ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 199.9, 199.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rd5z-m7vaax30erwnb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F18899677872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
