INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49511215932', 'Boneco Funko Pop! Marvel X-Men ''97 - Cable', 'Fortaleça sua coleção com o Boneco Funko Pop! Cable, inspirado no poderoso mutante viajante do tempo da aclamada série X-Men ''97. Este colecionável traz Cable com seu visual marcante e cheio de atitude, pronto para reunir os X-Men e enfrentar qualquer ameaça. Com aproximadamente 10 centímetros de altura e acabamento em vinil com cabeça oscilante, a peça combina detalhes incríveis e presença imponente, sendo perfeita para fãs da Marvel, colecionadores e apaixonados por cultura pop. Ideal para destacar sua coleção Funko Pop!, este Cable é um item indispensável para quem busca ação, nostalgia e personagens icônicos em um só produto.', 149.99, 149.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-823r9-mok1fkjk1r7y08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F49511215932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
