INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17238761529', 'Kit 2 Travesseiro Nasa Flocos de Visco Capa 200 Fios 100% algodão Repelente a líquidos Viva Conforto', 'Kit 2 Travesseiros Nasa Premium Flocos de Visco Capa Impermeável - Viva Conforto Os travesseiros produzidos com tecnologia NASA de material 100% viscoelástico de alta densidade, são capazes de moldar-se aos contornos da cabeça e da coluna cervical na região do pescoço, proporcionando o apoio ideal e a posição correta ao dormir. São compostos por um espuma termossensível, com a capacidade de dissipar o calor do corpo, anti-pressão com retorno lento, e tratamento ULTRA-FRESH evitando a proliferação de ácaros, fungos e bactérias, melhorando assim a sensação de conforto e bem-estar. Os travesseiros PREMIUM FLOCOS DE VISCO são revestidos em Percal 200 fios 100% algodão, com tratamento repelente à líquidos, proporcionando um toque macio e confortável para seu sono. Enchimento: Espuma poliuretano flocada 100% viscoelástica Revestimento: Percal 200 fios, 100% algodão com tratamento repelente à líquidos Medidas: 70cm x50cm x 15cm Conteúdo do kit: 02 travesseiros', 140.0, 77.9, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134207-820ld-mpi9270f6i2r8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F297240324%2F17238761529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
