INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893493257', '01 Tubo Solda Estanho 1mm 63x37 1.0mm C/ Fluxo - Cobix Bivolt', 'Apresentamos o Tubo Solda Estanho 1mm 63x37 1.0mm C/ Fluxo - Cobix Bivolt, uma ferramenta essencial para todos os profissionais e entusiastas de eletrônica. Este produto de alta qualidade da marca Cobix é perfeito para soldar placas eletrônicas com precisão e eficiência. Com um diâmetro de eletrodo de 1 mm, este tubo de solda é ideal para trabalhos delicados e detalhados. O modelo 63X37 1.0MM - Fio Fluxo RA T2 é projetado para ser usado com seu ferro de solda tipo lápis, proporcionando uma aplicação suave e consistente. Este tubo de solda possui uma potência de 60 W, garantindo que você tenha a energia necessária para realizar seus projetos. O fluxo incluído ajuda a criar uma solda limpa e forte, melhorando a qualidade e a durabilidade de suas conexões eletrônicas. Seja você um profissional experiente ou um hobbista, o Tubo Solda Estanho 1mm 63x37 1.0mm C/ Fluxo - Cobix Bivolt é uma adição valiosa para sua caixa de ferramentas. Compre hoje e experimente a diferença que uma ferramenta de qualidade pode fazer.', 21.9, 21.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7renr-m1u20bznlo6f2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397020362%2F22893493257', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
