INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293063879', 'Par Farol Milha Auxiliar Crossfox 2005 2006 2007 2008 2009 2010 Lente Lisa em Vidro', 'Par Farol de Milha Auxiliar Volkswagen Crossfox 2005 2006 2007 2008 2009 2010 Características: Produto novo de ótima qualidade; Feito sob medida, encaixe perfeito; Não acompanha lâmpadas e soquetes. Especificações técnicas: Encaixe de lâmpada H3; Regulagem de foco manual; Lente lisa em vidro resistente; Suporta lâmpadas até 55 watts. Compatível com os modelos: Gol 2006 a 2014; Fox 2003 a 2009; Polo 2006 a 2014; Parati 2006 a 2013; Saveiro 2006 a 2014; Crossfox 2005 a 2010; Spacefox 2006 a 2009. Atenção: para os modelos que contém farol de milha e neblina, esse produto refere-se ao farol inferior neblina. Obs: valor anunciado referente ao PAR. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 102.22, 92.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lweb6sf877xm9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F23293063879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898021739', 'Sandália Pegada Masculina Couro 2 em 1 134203', 'A Sandália Pegada 134203 é ideal para você passar o dia com um estilo casual e cheio de conforto. Seu cabedal é confeccionado em couro e contém uma tira auto colante, além de uma tira traseira (estilo slingback) elástica, para um calce facilitado. Conta com forro feito em tecido que permite maior conforto e absorção de suor, ajudando a manter o pé seco e arejado. Sua palmilha é feita em EVA, sendo anatômica e macia, enquanto o solado leve e flexível auxilia no amortecimento de impactos e conta com borracha antiderrapante, trazendo estabilidade ao caminhar. Versátil, a sandália possui uma tira ajustável 2 em 1, uma sandália que vira chinelo. Aproveite e garanta o seu!', 209.89, 166.88, NULL, 'Men Shoes > Sandals & Flip Flops > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-81zwd-mmj1y842fqxbe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23898021739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599772523', 'Suporte Porta Toalha De Banho Rosto Com Gancho Ventosa Sem Furos Arthi', 'Gancho Suporte Porta Toalha Banho/Rosto com Ventosa de Sucção em Aço Cromado - Arthi Organize seu banheiro com elegância e praticidade com o Gancho Suporte Porta Toalha Arthi. Ideal para toalhas de rosto ou banho, este gancho une funcionalidade, resistência e um design moderno que combina com qualquer decoração. Fabricado em aço cromado de alta qualidade, o suporte oferece durabilidade e resistência à umidade, garantindo um produto bonito por muito mais tempo. Sua instalação é simples e sem necessidade de furos: conta com ventosa de sucção potente, que fixa firmemente em superfícies lisas como vidro, azulejo ou espelho, sem danificar a parede. Características do Produto: - Material: Aço cromado com ventosa de PVC resistente - Fixação: Ventosa de sucção (sem necessidade de furar a parede) - Altura: 12,5 cm Largura: 4,5 cm Comprimento: 8 cm - Cor: Cromado (prata) - Uso indicado: Toalhas de rosto ou banho, roupas leves, acessórios - Marca: Arthi Ideal para quem busca praticidade na organização sem abrir mão do estilo. Com o gancho Arthi, seu banheiro fica mais organizado, sofisticado e funcional em poucos segundos!', 34.9, 29.69, NULL, 'Home & Living > Bathrooms > Toilet Bowls, Seats & Covers', 'https://cf.shopee.com.br/file/sg-11134201-7rasm-ma4artjc58785b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F20599772523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093706417', 'Tênis Vizzano Feminino Np Floather Madri 1444.100', 'Com seu estilo urbano, o tênis Vizzano 1444.100 vem conquistando o mundo da moda nos dias de hoje e é um calçado que não pode faltar em seu closet. Confeccionado em napa floather Madri, nobuck Lisboa e pelica, possui interior acolchoado com material super macio. Sua palmilha é aconchegante e proporciona máximo conforto ao caminhar. Seu solado é antiderrapante e foi desenvolvido para aumentar sua durabilidade. Além de ser prático, é super versátil, o tênis cai bem com diversos tipos de roupas, como por exemplo, uma calça jeans, uma saia ou até mesmo um shorts, entre diversos outros tipos de visuais que você pode criar. Aproveite!', 259.89, 154.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zu1-mmj38wqxyl1h0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23093706417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699677854', 'Kit 3 Cabos Rca 1 Metro Dupla Blindagem 1m 5mm Vermelho', 'Cabo RCA Luxo 1 Metro Plug Banhado a Ouro: Está em busca de um áudio de alta fidelidade para o seu sistema? Então pode se considerar uma pessoa muito sortuda, pois você acabou de encontrar a melhor opção de Cabo RCA para realizar a conexão dos seus equipamentos. Com material interno fabricado em OFHC livre de oxigênio que oferece máxima condução, pode ter certeza de que você terá um som de máxima qualidade. Inclusive ele ainda conta com dupla blindagem e malha interna trançada para que não acha qualquer tipo de interferência ou perda. Para uma maior durabilidade, o revestimento deste acessório é feito em PVC super resistente, além de contar com um acabamento arrojado. Seus plugues são duplos, de alta pressão e banhados a ouro, detalhes que fazem toda a diferença na hora de curtir o seu som. Especificação Técnica: - Diâmetro de 5mm - 1 Metro de Comprimento - Conectores Duplos de Alta Pressão Banhados a Ouro - Alta Capacidade de Condução - Condutor Interno Fabricado em OFHC Livre de Oxigênio - Com Isolamento Dielétrico - Malha Interna Trançada - Dupla Blindagem Contra Interferências - Revestimento em PVC Resistente - Cortes Polidos no Encaixe do Plugue que Evitam Ruídos por Trepidação - Alta Durabilidade - Qualidade de Transmissão Superior Conteúdo da Embalagem: - 03 Cabos 1 Metro', 81.0, 75.33, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7rep2-m820b0ygbus1c5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1495834698%2F21699677854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45303551512', 'Bola Futebol Society Mag11a R2 XXVI Penalty Original', 'Bola Society Mag11a R2 XXVI Penalty Modelo: 521438 A Bola Society Penalty Mag11A R2 XXVI é uma réplica da bola oficial do Campeonato Paulista 2026 desenvolvida para oferecer máximo desempenho e resistência nas partidas em gramado sintético. Características: - Maior durabilidade com construção Ultra Fusion - Toque macio e menor absorção de água - Retenção de ar prolongada com miolo Cápsula SIS - Tecnologia Kick Off para maior controle e menor quique. Detalhes: - Peso: 420-450g - Circunferência: 66-69cm - Gomos: 6 - Miolo Cápsula SIS: lubrificado e substituível. - Laminado PU: Conforto, aderência e maciez no domínio. - Construção ULTRA FUSION + DUPLA COLAGEM: reforça ainda mais a junção dos gomos. - Câmara 6D: Composta por 6 discos posicionados simetricamente para equilíbrio total da bola. - Sistema de forro TERMOFIXO: A câmara é enrolada com 3 mil metros de fios sintéticos em um sistema multiaxial. - Tecnologia Kick Off: Maior controle e menor quique na modalidade Society. A Bola Society Mag11a R2 XXVI Penalty pode ser encontrada aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 299.99, 185.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjjv9xs03vuu27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1559054473%2F45303551512', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203857657', 'FAIXA DE CABELO ESPORTIVA FEMININA SOUL DLK', 'A faixa esportiva para cabelo ou headband é o acessório ideal para quem deseja manter os fios longe dos olhos com conforto e estilo, focando no que realmente importa: O seu treino! Perfeita para você se movimentar livremente sem se preocupar com o cabelo. POR QUE INVESTIR - Proporciona ajuste confortável e funcional - Tecido de poliamida com toque macio e ótima elasticidade - Visual moderno que combina com qualquer look fitness ou casual - Possui secagem rápida INFORMAÇÕES ADICIONAIS Composição do tecido: 92.9% Poliamida 7.1% Elastano Compressão: Média Sobre a cor do produto: Pode haver variação na cor do produto final de acordo com o brilho do monitor ou tela do celular. Garantia: Contra defeito de fabricação SOBRE A MARCA - Somos uma das maiores marcas de moda fitness do Brasil. - Entregamos as melhores roupas esportivas há mais de 10 anos. - Já chegamos a mais de 5 mil cidades em todo o país. - Contamos com mais de 2,6 milhões de DLK Lovers.', 28.99, 28.99, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Sports Headbands', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mjsqzpd6x4oy5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F58203857657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
