INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194083633', 'Engate Reboque Rabicho Fixo Fiesta Sedan 2002 a 2012 700Kg tOP', 'Engate Reboque Rabicho Fixo Fiesta Sedan 2002 ate 2012 Fabricado de acordo com as especificações do fabricante do veículo. Utilizando como base tubos estruturais de alta resistência, design para uma melhor fixação, segurança para o condutor e ocupantes do veículo, melhor durabilidade e proteção em colisões leves. Em caso de transbikes é necessário utilização de dois apoios no porta-malas (O engates suporta o peso de 45kg se aplicados verticalmente sob a esfera) IMPORTANTE: A instalação deverá ser realizada por um profissional da área garantindo assim a funcionalidade, aplicação e segurança no uso do produto Capacidade de carga para reboque com freio: 700kg * Produto certificado pelo Inmetro; *Não Há necessidade de fazer furo do veículo ; * Fabricado em aço altamente resistente; * Ausência de superfícies cortantes ou cantos vivos na haste de fixação da esfera; * Selo de identificação com informações de registro em local visível; * Esfera maciça apropriada ao tracionamento de reboque ou trailer de acordo com a norma NBR ISO 1103; * Tomada elétrica conforme as normas NBR 9187 de 1985 e NBR 7332 de 1998. ::: Conteúdo da embalagem::: * Capa Protetora (ABS) Cromada * Caixa Personalizada * Engate * Esfera 50mm ABNT Cromada * Fiação Elétrica * Parafusos para Fixação * Tomada (ABS) Cromada 6 Polos ::: Ficha Técnica ::: * Peso da peça:6,04Kg * Largura:50cm * Altura:18cm * Comprimento:83cm * Pintura: Eletro Estática * Instalação: Instalado na furação original de Fábrica * Material: Aço ASTM36 1010/1020 * Garantia: 3 Meses', 401.86, 401.86, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-7rave-maplei9tzn5f6c', 'https: