INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40956535432', 'Palha Sintética Decorativa 50g Enchimento Decorativo Para Cestas e Embalagens', 'Dê um toque especial às suas embalagens com a Palha de Papel Decorativa Sintética! Ideal para montar cestas, caixas de presente, lembrancinhas ou dar aquele charme em produtos de confeitaria e artesanato. Feita em papel fininho, levemente frisado, ela ajuda a proteger os itens e ainda valoriza sua apresentação com um visual rústico e elegante. ✨ Destaques: Versátil: Use em cestas, kits presenteáveis, embalagens para doces e muito mais! Ótima opção para decorar sem pesar no orçamento. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacados em doces com lojas físicas no estado de São Paulo, desde 2002.', 8.99, 8.99, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbjk9jz9ajjsd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F40956535432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41251024634', 'Livro Objeções | Jeb Blount', 'Livro Objeções Como se tornar mestre na arte e na ciência de superar um não. Vendas não são uma profissão natural. Enquanto seres humanos, somos programados para evitar a rejeição. O sucesso nas vendas, no entanto, requer a busca incansável por ela. O medo e a repulsa à dor emocional causada pela rejeição são as principais razões para os profissionais de vendas fracassarem. O livro Objeções aborda o lado humano de lidar com o medo da rejeição, enquanto traz técnicas modernas e inovadoras para superar um não. Nas páginas de Objeções, você terá uma verdadeira epifania sobre: Como se tornar à prova de rejeição A ciência da resistência e por que os compradores fazem objeções Estruturas de influência que o transformam em um mestre da persuasão Como alavancar o “quarto de segundo mágico” para controlar suas emoções no mesmo instante em que receber objeções difíceis Estruturas de reversão de objeções comprovadas que lhe dão confiança e controle em praticamente qualquer situação de vendas O segredo para evitar as constrangedoras pistas falsas que comprometem as ligações de vendas Como evitar respostas por reflexo em chamadas frias e quando prospectar Como superar dispensas para chegar ao próximo passo, aumentar a velocidade do pipeline e encurtar o ciclo de vendas O Processo de 5 Passos para Reverter Objeções de Compromisso de Compra e fechar a venda Utilizada por executivos e equipes de vendas nas mais renomadas empresas do mundo, essa abordagem comprovada é versátil o suficiente para se adaptar a qualquer estilo de vendas e inclui técnicas práticas que você pode usar imediatamente, sem ressalvas. Nenhuma outra ferramenta oferece uma cobertura tão ampla do desafio mais devastador para os profissionais de vendas. Especificações do livro Objeções Título: Objeções Subtítulo: Como se tornar mestre na arte e na ciência de superar um não Autor(es): Jeb Blount Ano de Edição: 2019 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel Offset Páginas: 240 Dimensões: Altura: 23 cm Largura: 16 cm Profundidade: 1,0 cm Peso: 0,340 kg ISBN: 9788550803838 Editora: Alta Books', 61.43, 61.43, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ko3xbvhsea7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41251024634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
