INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4158479878', 'Bico De Confeitar Wilton 35 Estrela/Pitanga Fechada Original Pequeno', 'Utilização: Um dos mais famosos bicos de confeitar, que faz lindas rosas, flores, babados, estrela, cesta e etc em bolos e cupcake, e outros maravilhosos acabamentos. Deixe seus bolos, cupcakes, tortas entre outros com acabamento profissional com os bicos Wilton. Feito com aço inoxidável, não enferruja trazendo assim mais segurança e durabilidade. Bico Wilton sem emendas material: aço inox bico importado Wilton original medidas: 2,5 cm altura x 2 cm diâmetro Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 15.99, 15.99, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/c58df3f76d2336bb189558a82266b8b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F4158479878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
