INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22430823658', 'Os últimos Jovens da Terra | O rei dos pesadelos | Max Brallier', 'Os Últimos Jovens da Terra - O reis dos pesadelos Neste terceiro livro da série de sucesso da Netflix, Jack e seus três melhores amigos acreditam que são os únicos seres humanos que sobreviveram ao apocalipse dos monstros, mas algo que está prestes a acontecer irá surpreendê-los. Jack Sullivan era um menino normal: treze anos, vivendo uma vida comum em uma cidade desinteressante. Jack nunca foi um herói, nem durão e com certeza não lutava contra monstros gigantes. Mas agora ele enfrenta feras terríveis e zumbis assustadores… a vida se tornou uma loucura! Livro que originou a série de sucesso na Netflix: 4 Contra o Apocalipse. Título: Os Últimos Jovens da Terra Subtítulo: O rei dos pesadelos Autor: Max Brallier Ilustração: Douglas Holgate Acabamento: Capa Brochura, com alto relevo e verniz localizado Páginas: 272 Dimensões: Altura: 21 cm Largura: 13,6 cm Profundidade: 2,3 cm Peso: 380 g ISBN: 9786586041132 Editora: MilK Shakespeare | Faro Editorial', 41.92, 41.92, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-5l5fy1onihov6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22430823658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19307531557', 'Bíblia da Galerinha Capa Brochura', 'Bíblia da Galerinha Cultivar o hábito de ler nas crianças é de extrema relevância os livros fazem com que viajemos conhecendo outros mundos Esse hábito se torna ainda mais importante quando o assunto é aprender sobre Deus E por meio da leitura da Bíblia da Galerinha os pequenos irão se interessar sobre os ensinamentos deixados por Jesus e começarão a compreender como Deus fez o mundo sobre a história de Jonas e o grande peixe quando Jesus vive de novo entre outras passagens da Bíblia São 168 páginas enriquecidas de diversas histórias bíblicas que divertem a criançada Com este livro os pequenos irão descobrir e se apaixonar pela leitura e pela Palavra de Deus Título Bíblia da Galerinha Autor Marcelo Fonseca Páginas 168 Papel Offset 63g/m2 Formato 12x17 cm *essa medida pode sofrer variação de até 0 5 cm Peso 150g ISBN 7897185852158 Editora Geográfica', 16.91, 16.91, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/dccda6a9a8cc1989394f646dda8b05ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F19307531557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192777821', 'Violino Infantil Natural Zellmer ZLMNV', 'Violino Zellmer Natural-ZLMNV. Desvende o mundo da música clássica com o Violino Zellmer, uma obra-prima sonora e visual que encantará músicos de todos os níveis. Este instrumento excepcional não é apenas uma ferramenta musical; é uma expressão de arte e paixão. Qualidade e Tradição: O Zellmer é construído com materiais de alta qualidade que honram a tradição dos grandes fabricantes de violinos. Seu tampo, fundo e cavalete de maple proporcionam uma ressonância profunda e rica que permite uma incrível projeção sonora. Desempenho Excepcional: Tanto para músicos iniciantes como para profissionais, o Zellmer se destaca. Seu braço, escala e estandarte de maple, junto com a cravelha de madeira, garantem uma tocabilidade suave e precisa, permitindo que você alcance o máximo de expressão musical. Um Toque de Elegância: O acabamento do Zellmer confere um toque de elegância e autenticidade, destacando a beleza natural da madeira e dando ao violino uma aparência clássica e atemporal. Completo com Case e Arco: Não se preocupe com acessórios adicionais. Este violino é fornecido com um estojo resistente e um arco de alta qualidade, para que você possa começar a tocar imediatamente. De músicos aspirantes a virtuosos, o Violino Zellmer é a escolha certa para aqueles que buscam um instrumento excepcional. Descrição do produto : Braço: maple Fundo:plywood Escala: maple Estandarte: metal Queixeira: Wood Cravelha: wood Acabamento: Natural Brilhante Acompanha: Case e arco', 474.0, 474.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lps1ptolr7z3ae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F23192777821', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
