INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692865128', 'Livro Adesivos Enaldinho - Passatempos do Enaldinho', 'O dia a dia do Enaldinho é repleto de brincadeiras, aventuras, desafios e muita trollagem! Venha se divertir na companhia dele, fazendo diversos passatempos irados. Tem desenhos para colorir, caça-palavras, cruzadinha e muito mais. Editora: Ciranda Cultural Edição: 1, 2024 Autor: Paloma Blanca Idioma: Português Páginas: 32 Dimensões: L 20.10 x A 26.80 x E 0.33 ISBN: 9786526112489 Coleção: Adesivos e atividades Linha Editorial: Ciranda Cultural - Licenças Faixa Etária: + 4 anos Assuntos (tags): Entretenimento, Diversão, Colorir, Desenhos, Amizade, Youtube, Youtuber BISAC: Literatura Infantil / Mídia Tie-in Linha de Produto: Adesivos 32 p. Encadernação: Grampeado Acabamento: Verniz UV total Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcdx-lsbdlf7eyge3ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23692865128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
