INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593732914', 'Co2 12g Kit 10und + Esferas Aço 4.5 900und Pistolas Airguns', 'Co2 12g Kit 10und + Esferas Aço 4.5mm 900und para Pistola e revolver Airguns Os cilindros de CO2 12g, passam por rigorosos testes de segurança em sua produção, importação e recebimento para garantir a confiabilidade e segurança para os usuários. Os Cilindros de Co2 12g da Leão, foram desenvolvidos especialmente para serem usados em pistolas e carabinas de pressão que utilizam CO2, bem como Airsofts e paintball.Podem ser utilizado para armas de pressão, airsoft, paintball e outros dispositivos que utilizem este modelo de cápsula de CO2 de 12g. Dependendo do modelo da arma ou dispositivo possui um rendimento de 40 a 150 disparos. Detalhes: Composição: Gás Co2 Peso líquido: 12 gramas Peso bruto: 43 gramas Comprimento: 82.5mm Diâmetro: 18.6mm Encaixe: 3/8" sem rosca Comprimeiro do encaixa: 1/2" Acompanha: 10 Capsulas Co2 12g ( Conforme a marca disponível em estoque) 03 cx com 300und cada de esferas 4,5 aço ultra polidas', 90.85, 90.85, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6oc4b6dy5af52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F23593732914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21957311769', 'Filtro Ar Chevrolet Classic 1.0 2010 A 2016 Metal Leve', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação CHEVROLET CLASSIC ADVANTAGE 1.0 VHC FLEXPOWER 4P 2014 CLASSIC LIFE/LS 1.0 VHC FLEXP. 4P 2010 até 2016 Conteúdo Da Embalagem 1 Filtro de Ar Tipo de Veículo para Carros Marca O Grupo MAHLE é um parceiro mundial, líder no desenvolvimento e fornecimento para a indústria automotiva. Uma empresa que trabalha há 100 anos, com a qualidade de equipamento original, atendendo grandes montadoras e o mercado de reposição. Com uma extensa gama de produtos, fornecemos desde componentes de motor até o arrefecimento e climatização, turbo compressores, filtros, alternadores e motores de partida, além de equipamentos de oficina e diagnósticos. MAHLE – há 100 anos mantendo as pessoas em movimento! O Produto O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não se responsabiliza pelo mal uso ou instalação indevida, causando a perda da garantia. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Tempo de garantia: 3 Meses Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Imagem meramente ilustrativa Valor unitário EAN 7892415459350 Código do Fabricante LX523', 13.88, 13.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lltwpu29b5g9f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21957311769', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
