INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8087411322', 'Par Junta Homocinetica GM Prisma Manual com ABS 1.4 8V 2013 2016 Original Nakata', 'ATENÇÃO,CONFIRA A QUANTIDADE DE DENTES DA PEÇA EM SEU VEÍCULO ANTES DE EFETUAR A COMPRA,COBALT 2012 POSSUI 2 MODELOS( 25/22 DENTES E 25/21 DENTES),CONFIRA PARA NÃO COMPRAR ERRADO! Par Junta Homocinetica GM COBALT/ONIX/PRISMA MOTORES 1.4 COM ABS CÂMBIO MECÂNICO ORIGINAL NAKATA NJH55499 PRODUTO NOVO!!! A junta homocinética serve exatamente para transmitir torque (“Força”) do sistema de transmissão, para as rodas e ao mesmo tempo, permitir que as rodas girem - durante o comando da direção e os movimentos da suspensão - sem criar oscilações e vibrações na direção. Marca: Nakata Código da peça: NJH050583 Tipo: Junta homocinética Lado: Esquerdo, Direito Posição: Roda OBSERVAÇÃO: 25 DENTES EXTERNOS / 22 DENTES INTERNOS CONFIRA EM SEU VEÍCULO AS MEDIDAS ACIMA,POIS EXISTEM 4 MODELOS DIFERENTES PARA ESTE VEÍCULO Versão: JUNTA HOMOCINÉTICA - NJH050583 GM COBALT MANUAL COM ABS 1.4 8V 01/2012 12/2016 RODA 25 DENTES EXTERNO / 22 DENTES INTERNO DIR/ ESQ GM ONIX MANUAL COM ABS 1.4 8V 01/2013 12/2016 RODA 25 DENTES EXTERNO / 22 DENTES INTERNOS DIR/ ESQ GM PRISMA MANUAL COM ABS 1.4 8V 01/2013 12/2016 RODA 25 DENTES EXTERNO / 22 DENTES INTERNO VALOR REFERENTE À DUAS UNIDADES (02 JUNTAS HOMOCINÉTICA ) GARANTIA 90 DIAS PRODUTO ORIGINAL NOVO Imagens meramente ilustrativas Garantia de 90 Dias mediante apresentação do certificado de garantia. Imagens meramente ilustrativas. Instalação deve ser realizada por um profissional especializado. Não nos responsabilizamos por má instalação, uso inadequado do produto ou adaptações que não são compatíveis com a aplicação correta do produto segundo o fornecedor.', 462.0, 415.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/88aef06a03601706822736e0c985c1b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442403193%2F8087411322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21096910318', 'Touca De Natação Silicone P Record Breaker Hammerhead', 'A Record Breaker é uma touca específica para utilizar em competições. Com um design revolucionário, a tecnologia em múltiplas espessuras reduz o arrasto em 5%, eliminando rugas e mantendo a forma durante toda a prova. Aprovado pela FINA, ela é ergonomicamente perfeita e é a opção ideal para ser campeão dentro das águas. Específica para competição Design revolucionário em múltiplas espessuras Reduz o arrasto em 5% eliminando rugas e mantendo a forma Oferece ajuste ergonomicamente perfeito Composição : 100% silicone Itens inclusos: 01 un. Touca de Natação Silicone P Record Breaker Hammerhead Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 59.96, 59.96, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7qvdh-lgc7pk42dlphdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F21096910318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
