INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55301001163', 'Todo mundo neste trem é suspeito por Benjamin Stevenson, Intrínseca', 'Em suspense com pitadas de humor e repleto de pistas falsas, elenco estrelado de autores de mistério tenta solucionar crime durante uma viagem de trem pela Austrália Depois de ficar famoso por ter escrito um true crime sobre a própria família — em que literalmente todo mundo já matou alguém —, Ernest Cunningham está sofrendo pressão de sua agente e da editora para escrever um novo livro, desta vez de ficção. Sem nenhum assassinato previsto entre os parentes, no entanto, tem sido difícil colocar qualquer ideia no papel. Quando Ernest é convidado para participar de um festival de autores de mistérios que ocorrerá durante uma viagem de trem pela Austrália, ele sente que sua sorte pode virar. A jornada de quatro dias lhe oferecerá não apenas uma mudança de ares, mas a oportunidade de trocar ideias com outros escritores e, quem sabe, finalmente começar a escrever sua nova trama. Mas, logo no começo do trajeto — claro —, um dos passageiros aparece morto, e o caos se instaura. Em um evento repleto de participantes acostumados a investigações complexas, análises de perfis psicológicos e teorias rocambolescas, achar o culpado deveria ser simples. Muitos dos convidados ali presentes são especialistas em resolver assassinatos, mas, para impedir que o criminoso faça mais vítimas, eles vão precisar trabalhar rápido. O único problema é: como solucionar um mistério quando todos os suspeitos sabem a receita para o crime perfeito?', 74.9, 59.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mgs9mvl7rpc507', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F55301001163', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098787371', 'Cabo Rca Stetsom Injetado Amplificador Som 1Metro 2 Unid', '-------- CABO RCA FLEXÍVEL 1 METRO DUPLA BLINDAGEM ----- A série BRONZE foi desenvolvida para atender uma instalação profissional com a melhor relação custo benefício. Use a Série Bronze da Stetsom e seja um Pro. Desenvolvido com tecnologia que diminui interferência na transmissão de áudio ou vídeo. Revestimento em PVC translúcido flexível de fácil torção e instalação. Condutor 100% Cobre, livre de Oxigênio (OFC) e com cabo trançado. . Revestimento em PVC Flexível . Produzido PVC Cristal, que protege os fios de cobre contra corrosão e impede a penetração de interferências eletromagnéticas, que causam ruídos no sistema de som. . Dupla Blindagem . Malha de cobre nu altamente condutivo proporcionando alta flexibilidade com 95% de cobertura. Manta de alumínio isolando o condutor externo do condutor central . Conectores levemente revestidos em Ouro . Malha Trançada em Cobre Altamente Condutivo . Blindagem Interna de Alumínio . Diminui Interferências na Transmissão de Áudio ou Vídeo . Medidas Aproximadas da Espessura: 5mm . Comprimento Aproximado: 1 Metro . Condutor central . Formado de cobre isento de oxigênio (OFHC) com pureza superior a 99% apresentando total fidelidade na condução do sinal . HORÁRIO DE ATENDIMENTO DA NOSSA EQUIPE: Segunda a Sexta (exceto feriados) das 8:00 às 17:00hrs. (Mensagens recebidas após esse horário serão respondidas no próximo dia útil) ** RECOMENDAMOS SEMPRE QUE BUSQUE UM BOM TÉCNICO DE SUA CONFIANÇA PARA A INSTALAÇÃO.', 39.99, 39.99, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md3kcdbo74ld57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388765779%2F23098787371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299562937', 'Manguito Curto Voleibol Elite Muvin', 'Manguito Curto Voleibol Elite Muvin Os manguitos de compressão voleibol Elite da Muvin foram desenvolvidos com material específico para trazer desempenho e conforto em práticas esportivas. Desenvolvidos para proporcionar boa respirabilidade, eles trazem ótimo ajuste e não possuem costuras. Os manguitos de compressão são utilizados no voleibol com intuito de proteger e aliviar o contato da bola ao braço na recepção de manchete, além de evitar que o suor escorra para as mãos. O modelo Elite traz ainda esferas de absorção de impacto, que tem como objetivo aliviar ainda mais o contato e aumentar o controle da direção do passe. Composição: 96% Poliamida / 4% Elastano Medidas aproximadas: P: 8cm de largura / 22 cm de comprimento M: 8cm de largura / 23 cm de comprimento G: 8cm de largura / 25 cm de comprimento Conteúdo da Embalagem: 1 Par de Manguito Curto Voleibol Elite Muvin Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 52.0, 52.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Volleyball', 'https://cf.shopee.com.br/file/br-11134201-820m5-mqxgtdbsd1c567', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F20299562937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
